  final Map<String, String> values;

  static bool _matches(String expression, String value) =>
      RegExp(expression).firstMatch(value)?.group(0) == value;

  static bool _safeComponent(String value) =>
      _matches(r'[A-Za-z0-9][A-Za-z0-9_-]{0,95}', value) &&
      !_matches(r'CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]', value.toUpperCase());

  static _TechnicalCapturePlan? parse(
    Map<String, String> supplied, {
    bool allowBehaviorProfiles = false,
  }) {
    if (supplied.isEmpty) return null;
    if (supplied.length != keys.length ||
        keys.any((key) => !supplied.containsKey(key))) {
      throw const FormatException('Incomplete technical capture provenance');
    }
    final values = Map<String, String>.unmodifiable(supplied);
    if (!_matches(
          r'current-[A-Za-z0-9][A-Za-z0-9_-]{0,95}',
          values['runId']!,
        ) ||
        !_safeComponent(values['executionId']!) ||
        !(profiles.contains(values['profile']) ||
            (allowBehaviorProfiles &&
                const <String>{
                  'default',
                  'localstock_review',
                  'historical_store_review',
                }.contains(values['profile'])))) {
      throw const FormatException('Invalid technical capture execution');
    }
    for (final key in [
      'sourceCommit',
      'sourceTree',
      'executionHead',
      'producerBlob',
    ]) {
      if (!_matches(r'[0-9a-fA-F]{40}', values[key]!)) {
        throw FormatException('Invalid technical capture $key');
      }
    }
    if (!_matches(r'[0-9a-fA-F]{64}', values['registrySha256']!)) {
      throw const FormatException(
        'Invalid technical capture registry checksum',
      );
    }
    return _TechnicalCapturePlan._(values);
  }

  static _TechnicalCapturePlan? fromEnvironment() {
    const values = <String, String>{
      'runId': String.fromEnvironment('MOOL_TECHNICAL_CAPTURE_RUN_ID'),
      'executionId': String.fromEnvironment(
        'MOOL_TECHNICAL_CAPTURE_EXECUTION_ID',
      ),
      'profile': String.fromEnvironment('MOOL_TECHNICAL_CAPTURE_PROFILE'),
      'sourceCommit': String.fromEnvironment(
        'MOOL_TECHNICAL_CAPTURE_SOURCE_COMMIT',
      ),
      'sourceTree': String.fromEnvironment(
        'MOOL_TECHNICAL_CAPTURE_SOURCE_TREE',
      ),
      'executionHead': String.fromEnvironment(
        'MOOL_TECHNICAL_CAPTURE_EXECUTION_HEAD',
      ),
      'producerBlob': String.fromEnvironment(
        'MOOL_TECHNICAL_CAPTURE_PRODUCER_BLOB',
      ),
      'registrySha256': String.fromEnvironment(
        'MOOL_TECHNICAL_CAPTURE_REGISTRY_SHA256',
      ),
    };
    const presence = <String>{
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_RUN_ID')) 'runId',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_EXECUTION_ID'))
        'executionId',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_PROFILE')) 'profile',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_SOURCE_COMMIT'))
        'sourceCommit',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_SOURCE_TREE'))
        'sourceTree',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_EXECUTION_HEAD'))
        'executionHead',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_PRODUCER_BLOB'))
        'producerBlob',
      if (bool.hasEnvironment('MOOL_TECHNICAL_CAPTURE_REGISTRY_SHA256'))
        'registrySha256',
    };
    return parseCurrentEnvironment(
      values,
      presence,
      goldenUpdate: autoUpdateGoldenFiles,
      behaviorValue: const String.fromEnvironment(
        'MOOL_CURRENT_QUALIFICATION_BEHAVIOR_ONLY',
      ),
      behaviorPresent: const bool.hasEnvironment(
        'MOOL_CURRENT_QUALIFICATION_BEHAVIOR_ONLY',
      ),
      selectedValue: const String.fromEnvironment(
        'MOOL_CURRENT_QUALIFICATION_SELECTED_VISUAL_SLOTS',
      ),
      selectedPresent: const bool.hasEnvironment(
        'MOOL_CURRENT_QUALIFICATION_SELECTED_VISUAL_SLOTS',
      ),
    );
  }

  static _TechnicalCapturePlan? parseCurrentEnvironment(
    Map<String, String> values,
    Set<String> presence, {
    required bool goldenUpdate,
    required String behaviorValue,
    required bool behaviorPresent,
    required String selectedValue,
    required bool selectedPresent,
  }) {
    if (!behaviorPresent &&
        !selectedPresent &&
        presence.isEmpty &&
        values.values.every((value) => value.isEmpty)) {
      return null;
    }
    if (goldenUpdate ||
        behaviorPresent == selectedPresent ||
        (behaviorPresent && behaviorValue != 'true') ||
        (!behaviorPresent && behaviorValue.isNotEmpty) ||
        (!selectedPresent && selectedValue.isNotEmpty) ||
        presence.length != keys.length ||
        !keys.every(presence.contains)) {
      throw const FormatException('Invalid current qualification mode');
    }
    final plan = parse(values, allowBehaviorProfiles: behaviorPresent);
    if (plan == null) {
      throw const FormatException('Missing current capture provenance');
    }
    if (behaviorPresent) {
      return _TechnicalCapturePlan._(
        plan.values,
        currentMode: true,
        behaviorOnly: true,
      );
    }
    final Object? decoded;
    try {
      decoded = jsonDecode(selectedValue);
    } on FormatException {
      throw const FormatException('Invalid selected capture slots');
    }
    if (decoded is! List ||
        decoded.isEmpty ||
        decoded.any((value) => value is! String)) {
      throw const FormatException('Invalid selected capture slots');
    }
    final selected = decoded.cast<String>();
    final sorted = List<String>.of(selected)..sort();
    final allowed = slots[plan.values['profile']]!.values.toSet();
    if (jsonEncode(sorted) != selectedValue ||
        selected.toSet().length != selected.length ||
        selected.any((slot) => !allowed.contains(slot))) {
      throw const FormatException('Noncanonical or foreign capture slots');
    }
    return _TechnicalCapturePlan._(
      plan.values,
      currentMode: true,
      selectedSlots: Set<String>.unmodifiable(selected),
    );
  }

  bool capturesReference(String reference) {
    final profileSlots = slots[values['profile']];
    final slot = profileSlots?[reference];
    if (behaviorOnly && profileSlots == null) {
      final matches = slots.values
          .map((mapping) => mapping[reference])
          .whereType<String>()
          .toSet();
      if (matches.length != 1) {
        throw const FormatException(
          'Unknown or ambiguous current capture reference',
        );
      }
      return false;
    }
    if (slot == null) {
      throw const FormatException('Reference is not in this capture profile');
    }
    return !behaviorOnly && selectedSlots.contains(slot);
  }

  static _TechnicalCapturePlan? parseEnvironment(
    Map<String, String> values,
    Set<String> presence, {
    required bool goldenUpdate,
  }) {
    if (presence.isEmpty && values.values.every((value) => value.isEmpty)) {
      return null;
    }
    if (presence.length != keys.length ||
        !keys.every(presence.contains) ||
        values.length != keys.length ||
        !keys.every(values.containsKey) ||
        goldenUpdate) {
      throw const FormatException(
        'Incomplete or golden-update technical capture configuration',
      );
    }
    return parse(values);
  }

  String relativeImagePath(String slot) {
    final segments = slot.split('/');
    if (segments.isEmpty || segments.any((part) => !_safeComponent(part))) {
      throw const FormatException('Unsafe technical capture slot');
    }
    return 'build/compat-current-technical/${values['runId']}/'
        '${values['executionId']}/$slot.png';
  }

  String authorizedImagePath(String originalReference) {
    final slot = slots[values['profile']]?[originalReference];
    if (slot == null) {
      throw const FormatException('Reference is not in this capture profile');
    }
    return relativeImagePath(slot);
  }
}

// Dormant output writer. A producer must independently verify provenance and
// exclude concurrent writers before using this for technical observations.
class _TechnicalCaptureWriter {
  static String comparisonPath(String value, {required bool windows}) =>
      windows ? value.replaceAll('\\', '/').toLowerCase() : value;

  static bool _samePath(String left, String right) =>
      comparisonPath(left, windows: Platform.isWindows) ==
      comparisonPath(right, windows: Platform.isWindows);

  static Future<({String pngPath, String metadataPath})> write({
    required _TechnicalCapturePlan plan,
    required String originalReference,
    required ui.Image image,
    required Map<String, Object?> observations,
    required bool syntheticFixture,
    Future<void> Function()? fixtureBeforeEncoding,
  }) async {
    if (fixtureBeforeEncoding != null && !syntheticFixture) {
      throw ArgumentError('Failure injection is restricted to unit fixtures');
    }
    // Validate and deep-snapshot before any async boundary or output creation.
    final observedSnapshot = jsonDecode(jsonEncode(observations));
    final relative = plan.authorizedImagePath(originalReference);
    final root = Directory.current.absolute;
    final canonicalRoot = await root.resolveSymbolicLinks();
    if (!_samePath(canonicalRoot, root.path)) {
      throw StateError('Package root contains a redirected ancestor');
    }
    final pubspec = File('${root.path}/pubspec.yaml');
    if (FileSystemEntity.typeSync(pubspec.path, followLinks: false) !=
            FileSystemEntityType.file ||
        !RegExp(
          r'^name:\s*moolsocial\s*$',
          multiLine: true,
        ).hasMatch(await pubspec.readAsString())) {
      throw StateError('Technical capture requires the actual mobile package');
    }
    final components = relative.split('/');
    var parent = root.path;
    for (final component in components.take(components.length - 1)) {
      parent = '$parent/$component';
      var type = FileSystemEntity.typeSync(parent, followLinks: false);
      if (type == FileSystemEntityType.notFound) {
        await Directory(parent).create();
        type = FileSystemEntity.typeSync(parent, followLinks: false);
      }
      if (type != FileSystemEntityType.directory ||
          !_samePath(
            await Directory(parent).resolveSymbolicLinks(),
            Directory(parent).absolute.path,
          )) {
        throw StateError('Unsafe technical capture ancestor');
      }
    }
    final png = File('$parent/${components.last}');
    final metadata = File('${png.path.substring(0, png.path.length - 4)}.json');
    // Reserve both leaves before either payload. A second reservation failure
    // leaves the first empty and incomplete; never delete another run's files.
    await png.create(exclusive: true);
    await metadata.create(exclusive: true);
    if (fixtureBeforeEncoding != null) await fixtureBeforeEncoding();
    final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
    if (bytes == null) throw StateError('Image PNG encoding failed');
    final encoded = bytes.buffer.asUint8List(
      bytes.offsetInBytes,
      bytes.lengthInBytes,
    );
    await png.writeAsBytes(encoded, flush: true);
    final actualBytes = await png.readAsBytes();
    final hash = crypto.sha256.convert(actualBytes).toString();
    if (actualBytes.length != encoded.length ||
        hash != crypto.sha256.convert(encoded).toString()) {
      throw StateError('Written PNG differs from encoded image');
    }
    await metadata.writeAsString(
      jsonEncode({
        'schema': 'moolsocial.current-technical-capture.v1',
        'classification': 'technical-observation',
        'syntheticFixture': syntheticFixture,
        'complete': true,
        'founderApproved': false,
        'comparisonPassed': false,
        'providerVerified': false,
        'provenanceClaimsVerified': false,
        'provenanceClaims': plan.values,
        'originalReference': originalReference,
        'slotId': _TechnicalCapturePlan
            .slots[plan.values['profile']]![originalReference],
        'pngWidth': image.width,
        'pngHeight': image.height,
        'pngBytes': actualBytes.length,
        'pngSha256': hash,
        'observations': observedSnapshot,
      }),
      flush: true,
    );
    return (pngPath: png.path, metadataPath: metadata.path);
  }
}

Future<void> _dispatchTechnicalCapture(
  _TechnicalCapturePlan? plan, {
  String? originalReference,
  required Future<void> Function() historical,
  required Future<void> Function(_TechnicalCapturePlan) technical,
}) async {
  if (plan == null) {
    await historical();
  } else if (plan.currentMode) {
    if (originalReference == null) {
      throw const FormatException('Current capture reference is required');
    }
    if (plan.capturesReference(originalReference)) await technical(plan);
  } else {
    await technical(plan);
  }
}

const _technicalCaptureAppRootKey = Key('technical-capture-owned-app-root');

bool _captureElementIsWithin(Element element, Element ancestor) {
  if (identical(element, ancestor)) return true;
  var found = false;
  element.visitAncestorElements((parent) {
    if (identical(parent, ancestor)) {
      found = true;
      return false;
    }
    return true;
  });
  return found;
}

MediaQueryData? _captureMediaSettings(Element target, Finder? appRoot) {
  final inherited = MediaQuery.maybeOf(target);
  if (inherited != null || appRoot == null) return inherited;
  final roots = appRoot.evaluate().toList();
  if (roots.length != 1) throw StateError('Capture app root must be unique');
  final root = roots.single;
  if (!_captureElementIsWithin(target, root) &&
      !_captureElementIsWithin(root, target)) {
    throw StateError('Capture app root is outside target ancestry');
  }
  final navigators = <Element>[];
  void visit(Element element) {
    if (element.widget is Navigator) {
      // Nested navigators cannot identify the app's own effective context.
      navigators.add(element);
      return;
    }
    element.visitChildren(visit); // Includes offstage branches deliberately.
  }

  visit(root);
  if (navigators.length != 1) {
    throw StateError('Capture app must have one owned nonnested Navigator');
  }
  final navigator = navigators.single;
  if (!_captureElementIsWithin(navigator, target)) {
    throw StateError('Capture Navigator is outside requested target subtree');
  }
  final media = MediaQuery.maybeOf(navigator);
  if (media == null) {
    throw StateError('Capture Navigator has no media settings');
  }
  return media;
}

Future<({String pngPath, String metadataPath})> _recordTechnicalTarget(
  WidgetTester tester,
  Finder target,
  _TechnicalCapturePlan plan,
  String originalReference, {
  ui.Image? suppliedImage,
  Finder? mediaSettingsRoot,
  String fixtureKind = 'existing-authored-widget-test-state',
}) async {
  // Authorization before raster work; never silently change target or crop.
  plan.authorizedImagePath(originalReference);
  final elements = target.evaluate().toList();
  if (elements.length != 1) throw StateError('Capture target must be unique');
  final element = elements.single;
  final targetObject = element.findRenderObject();
  if (targetObject == null || !targetObject.attached) {
    throw StateError('Capture target is not attached');
  }
  RenderObject boundary = targetObject;
  while (!boundary.isRepaintBoundary) {
    final parent = boundary.parent;
    if (parent == null) throw StateError('No repaint boundary for capture');
    boundary = parent;
  }
  if (!boundary.attached || boundary.debugNeedsPaint) {
    throw StateError('Capture boundary must already be painted');
  }
  final layer = boundary.debugLayer;
  final paintBounds = boundary.paintBounds;
  if (layer is! OffsetLayer ||
      !paintBounds.isFinite ||
      paintBounds.width <= 0 ||
      paintBounds.height <= 0 ||
      paintBounds.width > 16384 ||
      paintBounds.height > 16384) {
    throw StateError('Invalid capture layer or dimensions');
  }
  const rasterRatio = 1.0;
  final targetRect = tester.getRect(target);
  final boundaryTransform = boundary.getTransformTo(null);
  final globalPaintBounds = MatrixUtils.transformRect(
    boundaryTransform,
    paintBounds,
  );
  if (boundaryTransform.storage.any((value) => !value.isFinite) ||
      !globalPaintBounds.isFinite) {
    throw StateError('Invalid boundary global transform');
  }
  if (!targetRect.isFinite) throw StateError('Invalid requested target bounds');
  final view = tester.view;
  final descendant = _captureMediaSettings(element, mediaSettingsRoot);
  Map<String, double> rect(Rect value) => {
    'left': value.left,
    'top': value.top,
    'width': value.width,
    'height': value.height,
  };
  Map<String, double> viewInsets(ui.ViewPadding value) => {
    'left': value.left,
    'top': value.top,
    'right': value.right,
    'bottom': value.bottom,
  };
  Map<String, double> edgeInsets(EdgeInsets value) => {
    'left': value.left,
    'top': value.top,
    'right': value.right,
    'bottom': value.bottom,
  };
  final observations = <String, Object?>{
    'fixtureKind': fixtureKind,
    'requestedTargetType': element.widget.runtimeType.toString(),
    'requestedTargetKey': element.widget.key?.toString(),
    'requestedTargetGlobalRect': rect(targetRect),
    'boundaryType': boundary.runtimeType.toString(),
    'boundaryLocalPaintBounds': rect(paintBounds),
    'boundaryToGlobalTransform': boundaryTransform.storage.toList(),
    'boundaryGlobalPaintBounds': rect(globalPaintBounds),
    'rasterPixelRatio': rasterRatio,
    'rootView': {
      'devicePixelRatio': view.devicePixelRatio,
      'physicalWidth': view.physicalSize.width,
      'physicalHeight': view.physicalSize.height,
      'logicalWidth': view.physicalSize.width / view.devicePixelRatio,
      'logicalHeight': view.physicalSize.height / view.devicePixelRatio,
      'padding': viewInsets(view.padding),
      'viewPadding': viewInsets(view.viewPadding),
      'viewInsets': viewInsets(view.viewInsets),
    },
    'descendantMediaQuery': descendant == null
        ? null
        : {
            'width': descendant.size.width,
            'height': descendant.size.height,
            'padding': edgeInsets(descendant.padding),
            'viewPadding': edgeInsets(descendant.viewPadding),
            'viewInsets': edgeInsets(descendant.viewInsets),
            'textScaleAtOne': descendant.textScaler.scale(1),
          },
  };
  final image =
      suppliedImage ??
      await tester.runAsync(
        () => layer.toImage(paintBounds, pixelRatio: rasterRatio),
      );
  if (image == null) throw StateError('Capture returned no image');
  try {
    if (image.width != (paintBounds.width * rasterRatio).ceil() ||
        image.height != (paintBounds.height * rasterRatio).ceil()) {
      throw StateError('Raster dimensions differ from painted boundary');
    }
    final result = await tester.runAsync(
      () => _TechnicalCaptureWriter.write(
        plan: plan,
        originalReference: originalReference,
        image: image,
        observations: observations,
        syntheticFixture: true,
      ),
    );
    if (result == null) throw StateError('Capture writer returned no result');
    final event = await tester.runAsync(() async {
      final metadataBytes = await File(result.metadataPath).readAsBytes();
      final metadata =
          jsonDecode(utf8.decode(metadataBytes)) as Map<String, dynamic>;
      final pngHash = crypto.sha256
          .convert(await File(result.pngPath).readAsBytes())
          .toString();
      if (metadata['complete'] != true || metadata['pngSha256'] != pngHash) {
        throw StateError('Capture files changed before event emission');
      }
      return {
        'schema': 'moolsocial.current-technical-capture-event.v1',
        'classification': 'technical-observation',
        'syntheticFixture': true,
        'founderApproved': false,
        'provenanceClaimsVerified': false,
        'slotId': metadata['slotId'],
        'originalReference': originalReference,
        'pngPath': result.pngPath,
        'metadataPath': result.metadataPath,
        'pngSha256': pngHash,
        'metadataSha256': crypto.sha256.convert(metadataBytes).toString(),
        'provenanceClaims': plan.values,
      };
    });
    if (event == null) throw StateError('Capture event returned no data');
    final eventPrefix = fixtureKind == 'existing-authored-widget-test-state'
        ? 'MOOL_TECHNICAL_CAPTURE'
        : 'MOOL_TECHNICAL_CAPTURE_UNIT';
    debugPrintSynchronously('$eventPrefix ${jsonEncode(event)}');
    return result;
  } finally {
    if (suppliedImage == null) image.dispose();
  }
}

Future<void> _expectGoldenOrTechnical(
  WidgetTester tester,
  Finder target,
  String originalReference,
  String goldenUri,
) => _dispatchTechnicalCapture(
  _TechnicalCapturePlan.fromEnvironment(),
  originalReference: originalReference,
  historical: () => expectLater(target, matchesGoldenFile(goldenUri)),
  technical: (plan) async {
    await _recordTechnicalTarget(
      tester,
      target,
      plan,
      originalReference,
      mediaSettingsRoot: plan.currentMode
          ? find.byKey(_technicalCaptureAppRootKey, skipOffstage: false)
          : null,
    );
  },
);

