class _HeldSupplierMoneyDraftStore extends SecureWorkLedgerFormDraftStore {
  _HeldSupplierMoneyDraftStore()
    : super(
        accountScope: () => 'review-draft-account',
        storage: const FlutterSecureStorage(),
      );
  Completer<void>? nextRead;
  Completer<void>? nextSave;
  WorkspaceLedgerFormKey? shortageSnapshotKey;
  Completer<void>? shortageSnapshotCaptured, shortageSnapshotRelease;
  bool failMoneyRead = false;
  bool failCopySave = false;
  bool failShortageRead = false;
  String frozenAllocationFailure = 'none';
  @override
  Future<void> save(
    WorkspaceLedgerFormDraft draft, {
    required int? expectedRevision,
  }) async {
    final saveGate = nextSave;
    nextSave = null;
    await saveGate?.future;
    if (failCopySave && draft.fields.containsKey('supportingCopies')) {
      throw StateError('HOST copy input save unavailable');
    }
    if (frozenAllocationFailure == 'draft-save' &&
        (draft.supplierAllocationIntent != null ||
            draft.supplierCreditIntent != null ||
            draft.supplierShortageIntent != null)) {
      throw StateError('HOST frozen allocation draft save failed');
    }
    await super.save(draft, expectedRevision: expectedRevision);
    if (frozenAllocationFailure == 'draft-lost-ack' &&
        (draft.supplierAllocationIntent != null ||
            draft.supplierCreditIntent != null ||
            draft.supplierShortageIntent != null)) {
      throw StateError('HOST frozen allocation draft acknowledgement lost');
    }
  }

  @override
  Future<WorkspaceLedgerFormDraft?> read(WorkspaceLedgerFormKey key) async {
    if (failShortageRead && key.kind == 'supplierShortage') {
      throw StateError('HOST shortage draft read unavailable');
    }
    if (failMoneyRead && key.kind == 'supplierMoney') {
      throw StateError('HOST supplier money draft read unavailable');
    }
    if (key == shortageSnapshotKey) {
      shortageSnapshotKey =
          null; // Consume before awaiting; modal reads stay live.
      final snapshot = await super.read(key);
      shortageSnapshotCaptured!.complete();
      await shortageSnapshotRelease!.future;
      return snapshot; // Deliver the actual earlier snapshot, not a fresh read.
    }
    final gate = nextRead;
    nextRead = null;
    if (gate != null) await gate.future;
    return super.read(key);
  }
}

