    product=work.workspaceCatalogueItems.firstWhere((row)=>row.canSellAtCounter&&(row.stockMode==WorkspaceStockMode.availabilityOnly||row.stock>=3)&&work.workspaceCounterAdjustedQuantity(row.id,0,1)==1);
