    test('absent configuration disables technical capture parsing', () {
      expect(_TechnicalCapturePlan.parse({}), isNull);
    });
    test(
      'source and actual execution identity remain distinct and immutable',
      () {
        final input = fixture();
        final plan = _TechnicalCapturePlan.parse(input)!;
        input['sourceCommit'] = 'changed';
        expect(plan.values['sourceCommit'], List.filled(40, 'a').join());
        expect(plan.values['executionHead'], List.filled(40, 'c').join());
        expect(
          () => plan.values['sourceCommit'] = 'changed',
          throwsUnsupportedError,
