        );
      },
    );
    test('each sanctioned profile accepts complete provenance only', () {
      for (final profile in _TechnicalCapturePlan.profiles) {
        expect(
          _TechnicalCapturePlan.parse({...fixture(), 'profile': profile}),
          isNotNull,
        );
      }
      for (final key in _TechnicalCapturePlan.keys) {
        final missing = fixture()..remove(key);
        expect(
          () => _TechnicalCapturePlan.parse(missing),
          throwsFormatException,
        );
        expect(
          () => _TechnicalCapturePlan.parse({...fixture(), key: ''}),
          throwsFormatException,
        );
      }
      expect(
        () => _TechnicalCapturePlan.parse({...fixture(), 'extra': 'x'}),
        throwsFormatException,
      );
      expect(
        () => _TechnicalCapturePlan.parse({...fixture(), 'profile': 'default'}),
        throwsFormatException,
      );
    });
    test(
      'literal slot mapping rejects unknown and cross-profile references',
      () {
        final slotIds = <String>{};
        var count = 0;
        for (final profile in _TechnicalCapturePlan.profiles) {
          final plan = _TechnicalCapturePlan.parse({
            ...fixture(),
            'profile': profile,
          })!;
          final mapping = _TechnicalCapturePlan.slots[profile]!;
          for (final entry in mapping.entries) {
            count++;
            expect(slotIds.add(entry.value), isTrue, reason: 'duplicate slot');
            expect(
              plan.authorizedImagePath(entry.key),
              endsWith('/${entry.value}.png'),
            );
            for (final otherProfile in _TechnicalCapturePlan.profiles.where(
              (p) => p != profile,
            )) {
              final other = _TechnicalCapturePlan.parse({
                ...fixture(),
                'profile': otherProfile,
              })!;
              expect(
                () => other.authorizedImagePath(entry.key),
                throwsFormatException,
              );
            }
          }
          expect(
            () => plan.authorizedImagePath('unknown.png'),
            throwsFormatException,
          );
          expect(() => mapping['unknown.png'] = 'H00', throwsUnsupportedError);
        }
        expect(count, 65);
        expect(
          _TechnicalCapturePlan.slots.map(
            (key, value) => MapEntry(key, value.length),
          ),
          {
            'workspace_capture': 15,
            'historical_store_capture': 6,
            'store_live_capture': 20,
            'founder_capture': 24,
          },
        );
