  for (final matched in [0, 1]) {
    for (final exception in ['shortage', 'damage', 'return']) {
      for (final due in <int?>[null, 0, 100, -100]) {
        test(
          'PURCHASEGUIDANCE historical $exception matched=$matched due=$due',
          () {
            final progress = (
              totalItems: 1,
              matchedItems: matched,
              hasMatches: true,
              damaged: exception == 'damage',
              shortage: exception == 'shortage',
              returnedOnMatchedDelivery: exception == 'return',
            );
            final before = progress;
            final text = workPurchaseNextStep(
              progress: progress,
              remainingMinor: due,
            );
            expect(progress, before);
            expect(text, isNot(contains('balance settled')));
            expect(text, isNot(contains('credit available')));
            if (due == null) {
              expect(
                text,
                'Next: verify this bill’s balance in the supplier account.',
              );
            } else if (matched == 0) {
              expect(
                text,
                startsWith(
                  due == 0
                      ? 'No amount due on this bill.'
                      : due > 0
                      ? 'Bill amount remains due.'
                      : 'Bill credit recorded.',
                ),
              );
              expect(
                text,
                contains('match existing receipts where applicable'),
              );
              expect(
                text,
                endsWith('Record another delivery only when goods arrive.'),
              );
            } else if (due == 0) {
              expect(
                text,
                'No amount due on this bill. Goods adjustments remain in history.',
              );
              expect(text, isNot(contains('Next:')));
            } else if (due < 0) {
              expect(
                text,
                'Bill credit recorded. Check eligible credit/refund options below; goods adjustments remain in history.',
              );
            } else {
              expect(
                text,
                'Next: record payment or link available payment / credit.',
              );
            }
          },
        );
      }
    }
  }
