  test(
    'RESTOCK01 review catalogue uses exact existing Store and refuses external actions',
    () async {
      var account = 'restock-review-account';
      final seed = StoreReviewSeed(
        accountScope: account,
        orderCount: 1000,
        now: DateTime.now(),
      );
      var store = seed.storeId;
      final bookmarks = _StorePurchaseBookmarks();
      final controller = WorkProcurementController(
        currentAccountId: () => account,
        currentStoreId: () => store,
        currentProfileId: () => 'retailer-grocery',
        storeApproved: () => true,
        reviewCatalogueAllowed: () => true,
        bookmarks: bookmarks,
        stateStoreFactory: _StorePurchaseState.new,
      );
      addTearDown(controller.dispose);
      expect(
        await controller.open(
          purpose: BuyV2ProcurementPurpose.restock,
          returnTo: 'dashboard',
        ),
        isTrue,
      );
      final session = controller.session!;
      const enabled =
          bool.fromEnvironment('MOOLSOCIAL_DEVICE_REVIEW') &&
          bool.fromEnvironment('MOOLSOCIAL_UI_REVIEW_ONLY');
      expect(controller.usesReviewCatalogue, enabled);
      if (!enabled) {
        expect(session.procurementUnavailableMessage, isNotNull);
        return;
      }
      expect(session.procurementUnavailableMessage, isNull);
      final snapshot = await session.commerceAdapter.refresh();
      expect(snapshot.products, isNotEmpty);
      final product = snapshot.products.first;
      expect(product.seller, startsWith('TEST · '));
      expect(
        session.procurementEligibilityFor(product),
        BuyV2ProcurementEligibility.eligible,
      );
      expect(session.addProduct(product.id), isFalse,
        reason: 'Review catalogue permission does not establish operational availability');
      final probe = _StorePaymentTermsProbe();
      final probeIdentity = ValueNotifier(session.procurementContext);
      final probeCore = BuySession();
      final probeSession = BuyV2Session(
        core: probeCore,
        procurementIdentity: probeIdentity,
        customerStateStore: _StorePurchaseState(
          session.procurementContext!.customerStateOwnerScope,
        ),
        commerceAdapter: session.commerceAdapter,
        commercialPaymentTermsAdapter: probe,
        productFactsAdapter: _StorePurchaseOrderReadyFacts(),
        reviewDataEnabled: false,
      );
      addTearDown(probeIdentity.dispose);
      addTearDown(probeCore.dispose);
      addTearDown(probeSession.dispose);
      await probeSession.restoreCommerce();
      expect(probeSession.addProduct(product.id), isTrue);
      probeSession.openCart(scope: BuyV2CartScope.wholesale);
      expect(probeSession.openCheckout(), isTrue);
      expect(probeSession.choosePayment('UPI'), isTrue);
      Future<int> acceptedTerms() async {
        await probeSession.refreshCommercialPaymentTerms();
        return probeSession
            .commercialPaymentTermsFor(
              probeSession.checkoutFulfilmentGroups.single.key,
            )
            .length;
      }

      for (final days in List.generate(45, (index) => index + 1)) {
        probe.days = days;
        expect(await acceptedTerms(), 1, reason: 'supplier credit $days days');
      }
      for (final days in [0, 46]) {
        probe.days = days;
        expect(await acceptedTerms(), 0);
      }
      probe.days = 45;
      for (final percent in [5, 10, 15, 20, 25]) {
        probe.percent = percent;
        expect(await acceptedTerms(), 1);
      }
      probe.percent = 30;
      expect(await acceptedTerms(), 0);
      probe.percent = 10;
      final due = (probeSession.checkoutPayableTotal * 10 + 99) ~/ 100;
      probe.limit = due - 1;
      expect(await acceptedTerms(), 0);
      probe.limit = due;
      expect(await acceptedTerms(), 1);
      probe.limit = 100000;
      probe.balanceAdjustment = 1;
      expect(await acceptedTerms(), 0);
      probe.balanceAdjustment = 0;
      probe.methods = {'Cheque'};
      expect(await acceptedTerms(), 0);
      expect(probeSession.choosePayment('Cheque'), isTrue);
      expect(await acceptedTerms(), 1);
      expect(probeSession.choosePayment('PhonePe'), isFalse);
      probe.methods = {'RTGS'};
      expect(probeSession.choosePayment('RTGS'), isFalse);
      expect(probeSession.selectedPayment, 'Cheque');
      expect(probeSession.notice, contains('RTGS requires'));
      expect(await acceptedTerms(), 0, reason: 'Advance is below RTGS minimum');
      expect(
        (await session.commerceAdapter.createAddressRequest()).available,
        isFalse,
      );
      expect(
        (await session.commerceAdapter.reconcileOrder(
          idempotencyKey: 'test',
          paymentReference: 'test',
        )).outcome,
        BuyV2OrderPlacementOutcome.unavailable,
      );
      final savedContext = bookmarks.value!.context.customerStateOwnerScope;
      expect(await controller.leave(), isTrue);
      expect(
        await controller.open(
          purpose: BuyV2ProcurementPurpose.restock,
          returnTo: 'dashboard',
        ),
        isTrue,
      );
      expect(identical(controller.session, session), isTrue);
      expect(bookmarks.value!.context.customerStateOwnerScope, savedContext);
      account = 'another-account';
      controller.invalidateIfChanged();
      expect(controller.session, isNull);
      await expectLater(session.commerceAdapter.refresh(), throwsStateError);
      store = 'ordinary-approved-store';
      expect(
        await controller.open(
          purpose: BuyV2ProcurementPurpose.restock,
          returnTo: 'dashboard',
        ),
        isTrue,
      );
      expect(controller.usesReviewCatalogue, isFalse);
      expect(controller.session!.procurementUnavailableMessage, isNotNull);
    },
  );

