  void expectExactMoneyVisible(WidgetTester tester, Finder amounts) {
    expect(amounts, findsWidgets);
    for (final element in amounts.evaluate()) {
      final target = find.byElementPredicate(
        (candidate) => candidate == element,
      );
      expect(
        find.ancestor(
          of: target,
          matching: find.byWidgetPredicate(
            (widget) =>
                widget is SingleChildScrollView &&
                widget.scrollDirection == Axis.horizontal,
          ),
        ),
        findsNothing,
        reason:
            'The complete supported amount must be visible without sideways scrolling',
      );
      final paragraph = element.renderObject! as RenderParagraph;
      final value = (element.widget as Text).data!;
      final boxes = paragraph.getBoxesForSelection(
        TextSelection(baseOffset: 0, extentOffset: value.length),
      );
      expect(boxes, hasLength(1));
      expect(boxes.single.left, greaterThanOrEqualTo(-.5));
      expect(boxes.single.right, lessThanOrEqualTo(paragraph.size.width + .5));
      expect(paragraph.didExceedMaxLines, isFalse);
      expect(tester.getTopLeft(target).dx, greaterThanOrEqualTo(-.5));
      expect(
        tester.getTopRight(target).dx,
        lessThanOrEqualTo(tester.view.physicalSize.width + .5),
      );
    }
  }

  // Founder now requires a horizontally scrollable stock statement. Keep the
  // old no-horizontal-scroll assertion for finance/checkout, not table cells.
  void expectStatementMoneyUntruncated(WidgetTester tester, Finder amount) {
    expect(amount, findsOneWidget);
    final paragraph = tester.renderObject<RenderParagraph>(amount);
    final value = tester.widget<Text>(amount).data!;
    final boxes = paragraph.getBoxesForSelection(
      TextSelection(baseOffset: 0, extentOffset: value.length),
    );
    expect(boxes, hasLength(1));
    expect(boxes.single.left, greaterThanOrEqualTo(-.5));
    expect(boxes.single.right, lessThanOrEqualTo(paragraph.size.width + .5));
    expect(paragraph.didExceedMaxLines, isFalse);
    expect(
      find.ancestor(
        of: amount,
        matching: find.byKey(const Key('work-stock-horizontal')),
      ),
      findsOneWidget,
    );
  }

  // Host-only qualified projection. Never writes a device/backend record.
  void qualifyFinance(
    WorkSession work, {
    required int available,
    int dues = 0,
  }) {
    final scope = work.workspaceStockHistoryScope()!;
    final revision = (work.workspaceFinance?.revision ?? 0) + 1;
    final now = DateTime.now();
    final snapshot = WorkspaceFinanceSnapshot(
      accountScope: scope.accountScope,
      workspaceId: scope.workspaceId,
      revision: revision,
      asOf: now,
      salesTodayMinor: 0,
      duesMinor: dues * 100,
      availableMinor: available * 100,
      heldMinor: 0,
      requestedMinor: 0,
      paidOutMinor: 0,
      feesMinor: 0,
      deliveryAdjustmentsMinor: 0,
      refundsMinor: 0,
      taxWithheldMinor: 0,
      historyComplete: true,
      payouts: const [],
      payments: [
        if (dues > 0)
          WorkspacePaymentRecord(
            orderId: 'APP-1043',
            customerId: 'money-layout-customer',
            customerName: 'Rakesh',
            revision: revision,
            updatedAt: now,
            amountMinor: dues * 100,
            paidMinor: 0,
            dueMinor: dues * 100,
            refundedMinor: 0,
            state: WorkspacePaymentState.unpaid,
            channel: WorkspacePaymentChannel.platform,
            invoiceId: 'INV-RANGE',
          ),
      ],
    );
    expect(work.applyWorkspaceFinance(snapshot), available >= 0);
    if (available < 0) {
      work.markWorkspaceFinanceStale(
        accountScope: scope.accountScope,
        storeId: scope.workspaceId,
      );
    }
  }

  Future<void> expectFinanceActionWords(WidgetTester tester) async {
    for (final entry in const {
      'customer-dues': 'Receivables',
      'settlement-available': 'Settlement available',
    }.entries) {
      final action = find.byKey(Key('store-overview-open-${entry.key}'));
      await tester.ensureVisible(action);
      await tester.pumpAndSettle();
      expect(action.hitTestable(), findsOneWidget);
      expect(tester.getSize(action).height, greaterThanOrEqualTo(48));
      final label = find.descendant(
        of: action,
        matching: find.text(entry.value),
      );
      final paragraph = tester.renderObject<RenderParagraph>(label);
      expect(paragraph.didExceedMaxLines, isFalse);
      for (final word in RegExp(r'\S+').allMatches(entry.value)) {
        final boxes = paragraph.getBoxesForSelection(
          TextSelection(baseOffset: word.start, extentOffset: word.end),
        );
        expect(boxes, hasLength(1), reason: entry.value);
        expect(boxes.single.left, greaterThanOrEqualTo(-.5));
        expect(
          boxes.single.right,
          lessThanOrEqualTo(paragraph.size.width + .5),
        );
      }
      expectExactMoneyVisible(
        tester,
        find.byKey(Key('store-overview-${entry.key}')),
      );
    }
  }

  Future<WorkProcurementController> prepareStoreProcurement(
    WorkSession work,
  ) async {
    final states = <String, _StorePurchaseState>{};
    final controller = WorkProcurementController(
      currentAccountId: () => 'fixture-purchaser',
      currentStoreId: () => work.activeWorkspace?.id,
      storeApproved: () => work.activeWorkspace?.verified == true,
      bookmarks: _StorePurchaseBookmarks(),
      stateStoreFactory: (scope) =>
          states.putIfAbsent(scope, () => _StorePurchaseState(scope)),
      sessionFactory: (identity, state) {
        final core = BuySession();
        addTearDown(core.dispose);
        return BuyV2Session(
          core: core,
          procurementIdentity: identity,
          customerStateStore: state,
          commerceAdapter: _StorePurchaseCommerce(identity.value!),
          productFactsAdapter: _StorePurchaseOrderReadyFacts(),
          reviewDataEnabled: false,
        );
      },
    );
    expect(
      await controller.open(
        purpose: BuyV2ProcurementPurpose.restock,
        returnTo: 'dashboard',
      ),
      isTrue,
    );
    expect(await controller.leave(), isTrue);
    return controller;
  }

  Future<void> mount(
    WidgetTester tester, {
    required String route,
    required WorkSession work,
    ChatSession? chat,
    double bottomInset = 44,
    Size viewport = const Size(360, 800),
    double textScale = 1.4,
    Widget Function(Widget child)? wrapper,
    WorkProcurementController Function()? procurementFactory,
    bool dashboardAccountAuthenticated = true,
    bool uiReviewOnly = false,
    BuyV2CustomerStateStore? consumerStateStore,
    bool settle = true,
    bool openHomeActions = true,
  }) async {
    tester.view.devicePixelRatio = 1;
    tester.view.physicalSize = viewport;
    tester.view.viewPadding = FakeViewPadding(bottom: bottomInset);
    // Flutter exposes both the physical safe inset and the current unobscured
    // padding. SafeArea reads padding, not viewPadding, with no keyboard open.
    tester.view.padding = FakeViewPadding(bottom: bottomInset);
    tester.platformDispatcher.textScaleFactorTestValue = textScale;
    addTearDown(tester.view.reset);
    addTearDown(tester.platformDispatcher.clearTextScaleFactorTestValue);
    final journey = JourneySession(
      store: MemoryJourneyStore(
        snapshot: const JourneySnapshot(
          languageCode: 'en',
          areaMode: 'manual',
          areaLabel: 'Jodhpur',
          setupComplete: true,
        ),
      ),
      otpGateway: ReviewOtpGateway(signedIn: true),
    );
    await journey.start();
    journey
      ..accountIdentity = const AuthenticatedAccountIdentity(
        displayName: 'Asha Sharma',
        emailAddress: 'asha@example.com',
        phoneNumber: '+91 98290 12321',
        providerAccountLabel: 'asha@example.com',
        signInMethods: ['Google', 'Phone'],
      )
      ..socialAuthProvider = SocialAuthProvider.google;
    addTearDown(journey.dispose);
    addTearDown(work.dispose);
    if (chat != null) addTearDown(chat.dispose);
    Widget app = MoolSocialApp(
      session: journey,
      workSession: work,
      chatSession: chat,
      initialLocation: route,
      uiReviewOnly: uiReviewOnly,
    );
    if (procurementFactory != null) {
      final core = BuySession();
      final consumer = BuyV2Session(
        core: core,
        customerStateStore: consumerStateStore,
      );
      addTearDown(core.dispose);
      addTearDown(consumer.dispose);
      final router = GoRouter(
        initialLocation: route,
        routes: [
          GoRoute(
            path: '/app/work/workspace/dashboard',
            builder: (_, _) => WorkWorkspaceDashboardScreen(
              session: work,
              procurementSession: consumer,
              useStoreProcurement: true,
              procurementControllerFactory: procurementFactory,
              accountAuthenticated: dashboardAccountAuthenticated,
              accountIdentity: journey.accountIdentity,
              initialSection: Uri.parse(route).queryParameters['section'],
            ),
          ),
        ],
      );
      addTearDown(router.dispose);
      app = MaterialApp.router(
        theme: MoolTheme.light(),
        routerConfig: router,
        debugShowCheckedModeBanner: false,
      );
    }
    await tester.pumpWidget(
      RepaintBoundary(
        key: const Key('store-review-root'),
        child: (wrapper ?? (child) => child)(
          KeyedSubtree(key: _technicalCaptureAppRootKey, child: app),
        ),
      ),
    );
    if (settle) await tester.pumpAndSettle();
    // Existing action journeys start by deliberately opening the new home tab.
    // HOME tests opt out to prove the actual collapsed entry state separately.
    final actions = find.byKey(const Key('work-home-actions-toggle'));
    if (settle && openHomeActions && actions.evaluate().isNotEmpty) {
      await tester.ensureVisible(actions);
      await tester.tap(actions);
      await tester.pumpAndSettle();
    }
  }

  WorkSession storeViewFixture([
    WorkGateway? gateway,
    WorkPendingProofStore? contactStore,
    WorkIssueDraftStore? issueDraftStore,
