  Future<void> reveal(WidgetTester tester, Finder finder) async {
    if (finder.evaluate().isEmpty) {
      for (final key in [
        'work-sales-new-counter-sale',
        'work-sales-dues',
        'work-sales-returns',
        'work-sales-exchange',
        'work-sales-customer-credit',
        'work-sales-statement',
      ]) {
        if (finder.describeMatch(Plurality.zero).contains(key)) {
          await revealSalesAction(tester, key);
          break;
        }
      }
    }
    if (finder.evaluate().isEmpty &&
        (find.byKey(const Key('work-sales-manage')).evaluate().isNotEmpty ||
            find
                .byKey(const Key('work-sales-recorded'))
                .evaluate()
                .isNotEmpty)) {
      final description = finder.describeMatch(Plurality.zero);
      for (final action in [
        'new-counter-sale',
        'dues',
        'returns',
        'exchange',
        'customer-credit',
        'statement',
      ]) {
        if (description.contains('work-sales-$action')) {
          await revealSalesAction(tester, 'work-sales-$action');
          break;
        }
      }
    }
    // Follow the approved contextual entry points, not obsolete Home controls.
    if (finder.evaluate().isEmpty &&
        find.byKey(const Key('work-store-home')).evaluate().isNotEmpty) {
      final description = finder.describeMatch(Plurality.zero);
      if (description.contains('work-pulse-')) {
        await openFinanceSummaryOrHome(tester, money: true);
      } else if (description.contains('work-quick-add-products') ||
          description.contains('work-quick-buy') ||
          description.contains('work-quick-group-buy') ||
          description.contains('work-incoming-purchases')) {
        await tester.tap(find.byKey(const Key('work-store-stock')));
        await tester.pumpAndSettle();
      }
    }
    final actions = find.byKey(const Key('work-home-actions-toggle'));
    if (finder.evaluate().isEmpty &&
        actions.evaluate().isNotEmpty &&
        find
            .byKey(const Key('work-store-quick-actions-scroll'))
            .evaluate()
            .isEmpty) {
      await tester.ensureVisible(actions);
      await tester.tap(actions);
      await tester.pumpAndSettle();
    }
    final salesRecords = find.byKey(const ValueKey('work-finance-payments'));
    final stockActions = find.byKey(const Key('work-stock-actions-toggle'));
    if (finder.evaluate().isEmpty &&
        stockActions.evaluate().isNotEmpty &&
        find.byKey(const Key('work-stock-actions-panel')).evaluate().isEmpty) {
      await tester.tap(stockActions);
      await tester.pumpAndSettle();
    }
    final vertical = find.byWidgetPredicate(
      (widget) =>
          widget is Scrollable &&
          (widget.axisDirection == AxisDirection.down ||
              widget.axisDirection == AxisDirection.up),
    );
    for (
      var attempt = 0;
      attempt < (salesRecords.evaluate().isNotEmpty ? 60 : 12) &&
          finder.evaluate().isEmpty;
      attempt++
    ) {
      final contactPage = find.byKey(const Key('work-contact-screen'));
      final counterItems = find.byKey(
        const Key('work-dashboard-counter-order-screen'),
      );
      final counterPage = counterItems.evaluate().isNotEmpty
          ? counterItems
          : find.byKey(const Key('work-counter-draft-recovery'));
      final purchases = find.byKey(const Key('work-store-track-stock'));
      final pageScroll = counterPage.evaluate().isNotEmpty
          ? find.descendant(of: counterPage, matching: vertical).first
          : salesRecords.evaluate().isNotEmpty
          ? find.descendant(of: salesRecords, matching: vertical).first
          : purchases.evaluate().isNotEmpty
          ? find.descendant(of: purchases, matching: vertical).first
          : contactPage.evaluate().isEmpty
          ? vertical.last
          : find
                .descendant(
                  of: contactPage,
                  matching: find.byWidgetPredicate(
                    (widget) =>
                        widget is Scrollable &&
                        widget.axisDirection == AxisDirection.down,
                  ),
                )
                .first;
      // Reveal the nested viewport before dragging its lazy rows; its centre
      // may initially sit below the screen inside the outer Store scroll.
      await tester.ensureVisible(pageScroll);
      await tester.pumpAndSettle();
      final scrollBox = tester.renderObject<RenderBox>(pageScroll);
      final rect = tester.getRect(pageScroll);
      Offset? visibleStart;
      for (final fraction in [.5, .25, .1, .75, .9]) {
        final point = Offset(rect.center.dx, rect.top + rect.height * fraction);
        if (tester
            .hitTestOnBinding(point)
            .path
            .any((entry) => entry.target == scrollBox)) {
          visibleStart = point;
          break;
        }
      }
      expect(
        visibleStart,
        isNotNull,
        reason:
            'The content scroll must be reachable, not covered by the action rail.',
      );
      await tester.dragFrom(visibleStart!, const Offset(0, -220));
      await tester.pumpAndSettle();
    }
    expect(finder, findsOneWidget);
    await tester.ensureVisible(finder);
    await tester.pumpAndSettle();
    for (final alignment in [.5, .1, .9]) {
      if (finder.hitTestable().evaluate().isNotEmpty) break;
      await Scrollable.ensureVisible(
        tester.element(finder),
        alignment: alignment,
      );
      await tester.pumpAndSettle();
    }
    for (
      var attempt = 0;
      attempt < 12 && finder.hitTestable().evaluate().isEmpty;
      attempt++
    ) {
      final ancestors = find.ancestor(of: finder, matching: vertical);
      var dragged = false;
      for (final element in ancestors.evaluate()) {
        final scroll = find.byElementPredicate(
          (candidate) => candidate == element,
        );
        final box = tester.renderObject<RenderBox>(scroll);
        final rect = tester.getRect(scroll);
        for (final fraction in [.25, .1, .5, .75]) {
          final point = Offset(
            rect.center.dx,
            rect.top + rect.height * fraction,
          );
          if (!tester
              .hitTestOnBinding(point)
              .path
              .any((entry) => entry.target == box)) {
            continue;
          }
          final direction = tester.getCenter(finder).dy > point.dy
              ? -100.0
              : 100.0;
          await tester.dragFrom(point, Offset(0, direction));
          await tester.pumpAndSettle();
          dragged = true;
          break;
        }
        if (dragged) break;
      }
      if (!dragged) break;
    }
    final stockTable = find.ancestor(
      of: finder,
      matching: find.byKey(const Key('work-stock-horizontal')),
    );
    final targetKey = tester.widget(finder).key;
    if (stockTable.evaluate().isNotEmpty &&
        targetKey is ValueKey<String> &&
        [
          'work-catalogue-price-',
          'work-catalogue-stock-',
          'work-catalogue-purchase-',
          'work-catalogue-mrp-',
          'work-catalogue-reorder-',
        ].any(targetKey.value.startsWith)) {
      // Pan the requested cell into the data viewport, not under the frozen
      // product column. The previous list had no horizontal gesture to replay.
      await Scrollable.ensureVisible(tester.element(finder), alignment: .5);
      await tester.pumpAndSettle();
      expect(finder.hitTestable(), findsOneWidget);
    }
  }

  // Former rail/notch tests are superseded by HOMEBOARD responsive routes below.

  test('HOME obsolete Store rails cannot be restored in application sources', () {
    // The approved Stock/Sales rail shares this primitive. Its placement, not
    // its existence, distinguishes it from the removed Home rail. Route tests
    // below additionally verify that Home cannot render those working rails.
    const permittedEdgeOwners = {
      '_StoreStatementSurfaceState',
      '_WorkspaceCatalogueSurfaceState',
      '_StoreEdgeAction',
    };
    List<String> misplacedEdgeReferences(String source) {
      final classes = RegExp(
        r'^class (\w+)\b',
        multiLine: true,
      ).allMatches(source).toList();
      final ends = RegExp(r'^}', multiLine: true).allMatches(source).toList();
      final bodies = <(String, int, int)>[];
      for (var index = 0; index < classes.length; index++) {
        final owner = classes[index];
        final nextStart = index + 1 < classes.length
            ? classes[index + 1].start
            : source.length;
        final end = ends
            .where(
              (match) => match.start > owner.start && match.start < nextStart,
            )
            .firstOrNull;
        expect(end, isNotNull, reason: 'Missing top-level class boundary.');
        bodies.add((owner.group(1)!, owner.start, end!.end));
      }
      final violations = <String>[];
      for (final reference in RegExp(
        r'\b_StoreEdgeAction\b',
      ).allMatches(source)) {
        final enclosing = bodies.where(
          (body) => body.$2 <= reference.start && reference.end <= body.$3,
        );
        final name = enclosing.isEmpty ? '' : enclosing.single.$1;
        if (!permittedEdgeOwners.contains(name)) violations.add(name);
      }
      return violations;
    }

    final files = Directory('lib')
        .listSync(recursive: true)
        .whereType<File>()
        .where((file) => file.path.endsWith('.dart'));
    for (final file in files) {
      final source = file.readAsStringSync();
      for (final obsolete in [
        '_StoreFirstTapAccess',
        '_StoreQuickActionBar',
        '_StoreActionEdge',
        '_QuickActionsNotch',
        '_StockContextRail',
        'work-contextual-shortcuts',
        'work-shortcut-restock',
      ]) {
        expect(
          source.contains(obsolete),
          isFalse,
          reason:
              '${file.path} must not restore the removed Store rail: $obsolete',
        );
      }
      if (source.contains('_StoreEdgeAction')) {
        expect(
          file.path.replaceAll('\\', '/'),
          'lib/features/work/screens/work_workspace_dashboard_screen.dart',
        );
        for (final owner in permittedEdgeOwners) {
          expect(
            RegExp(
              '^class $owner\\b',
              multiLine: true,
            ).allMatches(source).length,
            1,
            reason:
                'Each admitted rail owner must have one unambiguous boundary.',
          );
        }
        expect(misplacedEdgeReferences(source), isEmpty);
        // Labelled negative static fixtures only: constructor, named constructor
        // and tear-off references cannot be relocated into Home or another owner.
        for (final owner in ['_StoreControlDashboard', '_UnrelatedSurface']) {
          for (final reference in [
            '_StoreEdgeAction()',
            '_StoreEdgeAction.named()',
            '_StoreEdgeAction.new',
          ]) {
            final fixture = 'class $owner {\n  final rail = $reference;\n}\n';
            expect(misplacedEdgeReferences(fixture), [owner]);
          }
        }
        expect(
          misplacedEdgeReferences(
            'class _StoreEdgeAction {\n}\nfinal leakedRail = _StoreEdgeAction.new;',
          ),
          [''],
        );
      }
    }
  });

