  ]) {
    testWidgets('ANALYTICSRECOVERY scoped presentation $scenario', (
      tester,
    ) async {
      // Host-only presentation seeds, never provider, ledger or runtime records.
      final work = storeViewFixture(null, _ContactDraftFixtureStore());
      await mount(
        tester,
        route: '/app/work/workspace/dashboard',
        work: work,
        openHomeActions: false,
      );
      final scope = work.workspaceStockHistoryScope()!.key;
      final context = tester.element(
        find.byKey(const Key('store-analytics-public')),
      );
      final bucket = PageStorage.of(context);
      final now = DateTime.now();
      final yesterday = DateTime(now.year, now.month, now.day - 1, 12);
      final identifier = scenario == 'other-scope'
          ? '$scope-other-account'
          : scope;
      bucket.writeState(
        context,
        scenario == 'malformed'
            ? 'not a period'
            : (
                days: scenario == 'invalid-offset' ? 99 : 7,
                cutoff: scenario == 'future'
                    ? now.add(const Duration(days: 1))
                    : yesterday,
              ),
        identifier: ('analytics-period', identifier),
      );
      bucket.writeState(
        context,
        scenario == 'malformed'
            ? 123
            : (
                report: scenario == 'collapsed'
                    ? null
                    : scenario == 'unknown-report'
                    ? 'invented'
                    : 'money',
                summaryOffset: scenario == 'invalid-offset' ? double.nan : 0.0,
              ),
        identifier: ('analytics-report', identifier),
      );
      final invoices = List.of(work.workspaceInvoices);
      final movements = List.of(work.workspaceStockMovements);
      await tester.tap(find.byKey(const Key('work-store-stock')));
      await tester.pumpAndSettle();
      await tester.tap(find.byKey(const Key('work-store-home')));
      await tester.pumpAndSettle();
      final restored = const {'future', 'midnight'}.contains(scenario);
      expect(
        find.byKey(const Key('store-analytics-detail-money')),
        restored ? findsOneWidget : findsNothing,
      );
      expect(
        find.text(
          const {'unknown-report', 'midnight', 'collapsed'}.contains(scenario)
              ? 'Last 7 days'
              : 'Today',
        ),
        findsOneWidget,
      );
      final restoredPeriod = bucket.readState(
        context,
        identifier: ('analytics-period', scope),
      );
      // Refresh must write today's cutoff without changing the selected duration.
      await reveal(tester, find.byTooltip('Refresh analytics'));
      await tester.tap(find.byTooltip('Refresh analytics'));
      await tester.pumpAndSettle();
      final refreshed =
          bucket.readState(context, identifier: ('analytics-period', scope))
              as ({int days, DateTime cutoff});
      expect(DateUtils.dateOnly(refreshed.cutoff), DateUtils.dateOnly(now));
      expect(
        refreshed.days,
        const {'unknown-report', 'midnight', 'collapsed'}.contains(scenario)
            ? 7
            : 1,
      );
      if (scenario == 'midnight') {
        expect(
          (restoredPeriod as ({int days, DateTime cutoff})).cutoff,
          yesterday,
        );
      }
      expect(work.workspaceInvoices, invoices);
      expect(work.workspaceStockMovements, movements);
      expect(
        find.byKey(const Key('store-overview-open-settlement-available')),
        findsNothing,
      );
      expect(tester.takeException(), isNull);
    });
  }

  testWidgets(
    'ANALYTICSPDF canvas cancellation failure and late period result stay truthful',
    (tester) async {
      // Host-only save transport; no device data or transactions.
      final picker = _PurchaseOriginalSaveFixture();
      final previous = FilePickerPlatform.instance;
      FilePickerPlatform.instance = picker;
      addTearDown(() => FilePickerPlatform.instance = previous);
      final work = liveStore(
        analyticsReader: (request) async => WorkspaceAnalyticsSnapshot(
          request: request,
          state: WorkspaceAnalyticsState.unavailable,
          coverage: WorkspaceAnalyticsCoverage.unknown,
          source: 'HOST unconnected provider',
          metrics: const [],
        ),
      );
      await mount(
        tester,
        route: '/app/work/workspace/dashboard',
        work: work,
        viewport: const Size(320, 568),
        textScale: 2,
        openHomeActions: false,
      );
      final export = find.byKey(const Key('store-analytics-export'));
      expect(export, findsOneWidget);
      Future<void> save() async {
        await tester.ensureVisible(export);
        await tester.tap(export);
        await tester.runAsync(() async {
          for (var i = 0; i < 100 && picker.calls == 0; i++) {
            await Future<void>.delayed(const Duration(milliseconds: 100));
          }
        });
        await tester.pumpAndSettle();
      }

      await save();
      expect(picker.calls, 1);
      expect(
        picker.name,
        matches(RegExp(r'^store-analytics-[A-F0-9]{16}\.pdf$')),
      );
      expect(find.text('Download cancelled.'), findsOneWidget);
      expect(picker.bytes!.take(5), utf8.encode('%PDF-'));
      const output = String.fromEnvironment('MOOL_ANALYTICS_PDF_TEST_DIR');
      if (output.isNotEmpty) {
        Directory(output).createSync(recursive: true);
        File(
          '$output/analytics-canvas-host.pdf',
        ).writeAsBytesSync(picker.bytes!);
      }
      picker.calls = 0;
      picker.fail = true;
      await save();
      expect(
        find.text(
          'Could not save analytics. Check your files before retrying.',
        ),
        findsOneWidget,
      );
      picker.calls = 0;
      picker.fail = false;
      picker.holdSave = Completer<Uri?>();
      await tester.ensureVisible(export);
      await tester.tap(export);
      await tester.runAsync(() async {
        for (var i = 0; i < 100 && picker.calls == 0; i++) {
          await Future<void>.delayed(const Duration(milliseconds: 100));
        }
      });
      await tester.pump();
      expect(picker.calls, 1);
      await tester.ensureVisible(find.byTooltip('Refresh analytics'));
      await tester.tap(find.byTooltip('Refresh analytics'));
      await tester.pump();
      picker.holdSave!.complete(Uri.parse('content://host/late-result'));
      await tester.pumpAndSettle();
      expect(
        find.text('Analytics PDF saved.'),
        findsNothing,
        reason: 'Late save must not claim success for a different request.',
      );
      expect(tester.takeException(), isNull);
      await tester.pumpWidget(const SizedBox.shrink());
    },
  );

