  testWidgets('ANALYTICS changing period rejects delayed earlier data', (
    tester,
  ) async {
    final pending = <Completer<WorkspaceAnalyticsSnapshot>>[];
    final requests = <WorkspaceAnalyticsRequest>[];
    final work = liveStore(
      analyticsReader: (request) {
        requests.add(request);
        final result = Completer<WorkspaceAnalyticsSnapshot>();
        pending.add(result);
        return result.future;
      },
    );
    WorkspaceAnalyticsSnapshot response(int index, int count) {
      final request = requests[index];
      return WorkspaceAnalyticsSnapshot(
        request: request,
        state: WorkspaceAnalyticsState.verified,
        coverage: WorkspaceAnalyticsCoverage.complete,
        source: 'Automated aggregate fixture',
        updatedAt: DateTime.now(),
        coveredFrom: request.start,
        coveredUntil: request.end,
        metrics: [
          WorkspaceAnalyticsMetric(
            id: 'visitors',
            state: WorkspaceAnalyticsState.verified,
            coverage: WorkspaceAnalyticsCoverage.complete,
            basis: WorkspaceAnalyticsBasis.periodActivity,
            unit: WorkspaceAnalyticsUnit.count,
            source: 'Automated aggregate fixture',
            value: count,
            asOf: request.end,
          ),
        ],
      );
    }

    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      openHomeActions: false,
    );
    final public = find.byKey(const Key('store-analytics-public'));
    await tester.ensureVisible(public);
    await tester.tap(public);
    await tester.pumpAndSettle();
    expect(requests, hasLength(1));
    expect(find.text('Loading analytics…'), findsOneWidget);
    // Explicit recovery must remain possible even if the provider never settles.
    await tester.ensureVisible(find.byTooltip('Refresh analytics'));
    await tester.tap(find.byTooltip('Refresh analytics'));
    await tester.pumpAndSettle();
    expect(requests, hasLength(2));
    await tester.tap(find.byKey(const Key('store-analytics-period-picker')));
    await tester.pumpAndSettle();
    await tester.tap(find.text('Last 7 days').last);
    await tester.pumpAndSettle();
    expect(requests, hasLength(3));
    pending[2].complete(response(2, 7));
    await tester.pumpAndSettle();
    expect(
      tester
          .widget<Text>(find.byKey(const Key('store-analytics-value-visitors')))
          .data,
      '7',
    );
    expect(
      tester
          .widget<Text>(find.byKey(const Key('store-analytics-value-visits')))
          .data,
      '—',
    );
    pending[0].complete(response(0, 91));
    pending[1].complete(response(1, 92));
    await tester.pumpAndSettle();
    expect(
      tester
          .widget<Text>(find.byKey(const Key('store-analytics-value-visitors')))
          .data,
      '7',
    );
    expect(tester.takeException(), isNull);
    await tester.pumpWidget(const SizedBox.shrink());
  });

  testWidgets(
    'ANALYTICS hanging reader has a bounded lifetime and ignores late completion',
    (tester) async {
      final pending = Completer<WorkspaceAnalyticsSnapshot>();
      final work = liveStore(analyticsReader: (_) => pending.future);
      final end = DateTime.now();
      final request = work.analyticsRequest(
        start: end.subtract(const Duration(hours: 1)),
        end: end,
      )!;
      WorkspaceAnalyticsSnapshot? received;
      final operation = work
          .readWorkspaceAnalytics(request)
          .then((value) => received = value);
      await tester.pump(const Duration(seconds: 29));
      expect(received, isNull);
      await tester.pump(const Duration(seconds: 2));
      await operation;
      expect(received!.state, WorkspaceAnalyticsState.error);
      expect(received!.metrics, isEmpty);
      pending.complete(
        WorkspaceAnalyticsSnapshot(
          request: request,
          state: WorkspaceAnalyticsState.verified,
          coverage: WorkspaceAnalyticsCoverage.complete,
          source: 'Automated aggregate fixture',
          updatedAt: DateTime.now(),
          coveredFrom: request.start,
          coveredUntil: request.end,
          metrics: const [],
        ),
      );
      await tester.pump();
      expect(received!.state, WorkspaceAnalyticsState.error);
      work.dispose();
    },
  );

