  testWidgets('ANALYTICS percentages require matching cohort basis and unit', (
    tester,
  ) async {
    var phase = 0;
    final work = liveStore(
      analyticsReader: (request) async {
        WorkspaceAnalyticsMetric rate(String id, double value) =>
            WorkspaceAnalyticsMetric(
              id: id,
              state: WorkspaceAnalyticsState.verified,
              coverage: WorkspaceAnalyticsCoverage.complete,
              basis: phase == 2
                  ? WorkspaceAnalyticsBasis.currentPosition
                  : WorkspaceAnalyticsBasis.periodActivity,
              unit: phase == 3
                  ? WorkspaceAnalyticsUnit.count
                  : WorkspaceAnalyticsUnit.percent,
              cohortId: phase == 0
                  ? null
                  : phase == 1
                  ? '   '
                  : 'tracked-cohort',
              source: 'Automated aggregate fixture',
              value: value,
              asOf: request.end,
            );
        return WorkspaceAnalyticsSnapshot(
          request: request,
          state: WorkspaceAnalyticsState.verified,
          coverage: WorkspaceAnalyticsCoverage.complete,
          source: 'Automated aggregate fixture',
          updatedAt: DateTime.now(),
          coveredFrom: request.start,
          coveredUntil: request.end,
          metrics: [
            rate('order-conversion', 0),
            rate('cart-dropoff', phase == 5 ? 125 : 25),
          ],
        );
      },
    );
    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      openHomeActions: false,
    );
    final journey = find.byKey(const Key('store-analytics-journey'));
    await tester.ensureVisible(journey);
    await tester.tap(journey);
    await tester.pumpAndSettle();
    String value(String id) =>
        tester.widget<Text>(find.byKey(Key('store-analytics-value-$id'))).data!;
    for (phase = 0; phase < 6; phase++) {
      if (phase > 0) {
        await tester.ensureVisible(find.byTooltip('Refresh analytics'));
        await tester.tap(find.byTooltip('Refresh analytics'));
        await tester.pumpAndSettle();
      }
      expect(value('order-conversion'), phase == 4 ? '0.0%' : '—');
      expect(value('cart-dropoff'), phase == 4 ? '25.0%' : '—');
      final bar = find.byKey(const Key('analytics-percent-cart-dropoff'));
      expect(bar, phase == 4 ? findsOneWidget : findsNothing);
      if (phase == 4) {
        expect(tester.widget<LinearProgressIndicator>(bar).value, .25);
        expect(
          tester
              .widget<LinearProgressIndicator>(
                find.byKey(const Key('analytics-percent-order-conversion')),
              )
              .value,
          0,
        );
      }
    }
    expect(tester.takeException(), isNull);
    await tester.pumpWidget(const SizedBox.shrink());
  });

  Future<void> openStoreHeaderAction(WidgetTester tester, String key) async {
    // Profile is approved on Home only; alerts remain in the Orders header.
    if (find.byKey(Key(key)).evaluate().isEmpty) {
      await tester.tap(find.byKey(Key(key == 'work-dashboard-profile'
          ? 'work-store-home' : 'work-store-orders')));
      await tester.pumpAndSettle();
    }
    await tester.tap(find.byKey(Key(key)));
    await tester.pumpAndSettle();
  }

  Future<void> openStoreProfile(WidgetTester tester) =>
      openStoreHeaderAction(tester, 'work-dashboard-profile');

  Future<void> openStoreAlerts(WidgetTester tester) =>
      openStoreHeaderAction(tester, 'work-dashboard-alerts');

  Future<void> openStoreTools(WidgetTester tester) async {
    if (find.byKey(const Key('work-dashboard-profile')).evaluate().isEmpty) {
      await tester.tap(find.byKey(const Key('work-store-home')));
      await tester.pumpAndSettle();
    }
    await tester.tap(find.byKey(const Key('work-dashboard-settings')));
    await tester.pumpAndSettle();
    final operations = find.byKey(const Key('work-store-status-tools'));
    await tester.ensureVisible(operations);
    await tester.tap(operations);
    await tester.pumpAndSettle();
  }

  Future<void> openStoreStockReports(WidgetTester tester) async {
    // Analytics deliberately has no utility band; use the approved Store route.
    await openStoreTools(tester);
    for (final key in const [
      'work-business-downloads',
      'downloads-stock-statement',
    ]) {
      final action = find.byKey(Key(key));
      await reveal(tester, action);
      await tester.pumpAndSettle();
      expect(action.hitTestable(), findsOneWidget);
      await tester.tap(action);
      await tester.pumpAndSettle();
    }
  }

  Future<void> openSavedStoreRecordSearch(
    WidgetTester tester, {
    bool expand = true,
  }) async {
    await openStoreTools(tester);
    final customers = find.byKey(const Key('work-business-customers'));
    await reveal(tester, customers);
    await tester.tap(customers);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-customers-destination')), findsOneWidget);
    final search = find.byKey(const Key('work-dashboard-search'));
    expect(search.hitTestable(), findsOneWidget);
    if (!expand) return;
    await tester.tap(search);
    await tester.pumpAndSettle();
    expect(
      tester
          .widget<TextField>(
            find.byKey(const Key('work-dashboard-search-field')),
          )
          .decoration!
          .hintText,
      'Search your store',
    );
  }

  Finder purchaseRegisterFor(String storeId, {bool statement = false}) {
    final keyPattern = RegExp(
      '^work-purchases-${RegExp.escape(storeId)}-$statement-[0-9]+-register\$',
    );
    return find.descendant(
      of: find.byKey(const Key('purchase-action-category-scroll')),
      matching: find.byWidgetPredicate(
        (widget) =>
            widget is CustomScrollView &&
            widget.key is PageStorageKey<String> &&
            keyPattern.hasMatch((widget.key! as PageStorageKey<String>).value),
      ),
    );
  }

  Future<void> openStoreGrowthAction(
    WidgetTester tester,
    String key, {
    VoidCallback? beforeAction,
  }) async {
    if (find.byKey(const Key('work-grow-destination')).evaluate().isEmpty) {
      await openStoreTools(tester);
      final growth = find.byKey(const Key('work-business-grow'));
      await reveal(tester, growth);
      await tester.tap(growth);
      await tester.pumpAndSettle();
    }
    expect(find.byKey(const Key('work-grow-destination')), findsOneWidget);
    final action = find.byKey(Key(key));
    await reveal(tester, action);
    expect(action.hitTestable(), findsOneWidget);
    beforeAction?.call();
    await tester.tap(action);
    await tester.pumpAndSettle();
  }

  // Labelled host-only finance responses, never phone/provider acceptance.
  // The approved Analytics Money report requires scoped, complete snapshots;
  // legacy workspaceSettlementBalance cannot establish this fact.
  Future<(WorkSession, void Function(int, int))> finishFinanceFixture({
    bool withCustomerDues = false,
  }) async {
    final account = _ContactDraftFixtureStore();
    final work = await analyticsSavedStockFixture(contactStore: account);
    WorkspaceFinanceSnapshot snapshot(int revision, int availableMinor) =>
        WorkspaceFinanceSnapshot(
          accountScope: account.accountScope,
          workspaceId: work.activeWorkspace!.id,
          revision: revision,
          asOf: DateTime.now(),
          salesTodayMinor: 0,
          duesMinor: withCustomerDues ? 86000 : 0,
          availableMinor: availableMinor,
          heldMinor: 0,
          requestedMinor: 0,
          paidOutMinor: 0,
          feesMinor: 0,
          deliveryAdjustmentsMinor: 0,
          refundsMinor: 0,
          taxWithheldMinor: 0,
          payments: [
            if (withCustomerDues)
              WorkspacePaymentRecord(
                orderId: 'SALE-1042',
                customerId: '9876543210',
                customerName: 'Meena',
                revision: revision,
                updatedAt: DateTime.now().subtract(const Duration(seconds: 1)),
                amountMinor: 86000,
                paidMinor: 0,
                dueMinor: 86000,
                refundedMinor: 0,
                state: WorkspacePaymentState.unpaid,
                channel: WorkspacePaymentChannel.cash,
              ),
          ],
          payouts: const [],
          historyComplete: true,
        );
    expect(
      work.bindCustomerCollectionGateway(
        accountScope: account.accountScope,
        storeId: work.activeWorkspace!.id,
        adapter: StoreReviewCustomerCollectionGateway(snapshot(1, 1782000)),
        checkpointStore: _LedgerCheckpointFixtureStore(),
      ),
      isTrue,
    );
    expect(await work.recoverCustomerLedger(), isTrue);
    void update(int revision, int availableMinor) {
      expect(
        work.applyWorkspaceFinance(snapshot(revision, availableMinor)),
        isTrue,
      );
    }

    return (work, update);
  }

  Transform currentValueMotion(WidgetTester tester, Finder value) {
    Transform? result;
    tester.element(value).visitAncestorElements((element) {
      if (element.widget case final Transform transform) {
        result = transform;
        return false;
      }
      return true;
    });
    expect(
      result,
      isNotNull,
      reason: 'The actual displayed value must own motion',
    );
    return result!;
  }

