  Future<void> openBillActions(WidgetTester tester) async {
    final savedCopy = find.byKey(const Key('work-purchase-saved-copy'));
    if (savedCopy.evaluate().isNotEmpty) {
      tester.state<ScrollableState>(find.descendant(of: savedCopy,
        matching: find.byWidgetPredicate((widget) => widget is Scrollable &&
          widget.axisDirection == AxisDirection.down)).first).position.jumpTo(0);
      await tester.pumpAndSettle();
    }
    // Applicable bill actions are now permanently visible; only return to the top.
  }

  Future<void> openBillSection(WidgetTester tester, String label) async {
    await openBillActions(tester);
    final panel = find.byKey(Key(label == 'Payment' ? 'work-purchase-payment-toggle'
      : label == 'Goods' ? 'work-bill-goods-open' : 'work-purchase-adjustment-actions'));
    if (panel.evaluate().isEmpty) return;
    if (label == 'Goods') {
      final states = tester.widgetList<Semantics>(find.descendant(of: panel, matching: find.byType(Semantics)));
      if (states.any((state) => state.properties.expanded == true)) return;
    } else {
      final disclosures = find.descendant(of: panel, matching: find.byType(Expansible));
      if (disclosures.evaluate().isEmpty) return; // Flat actions are already visible.
      final disclosure = tester.widget<Expansible>(disclosures.first);
      if (disclosure.controller.isExpanded) return;
    }
    await tester.ensureVisible(panel);
    await tester.pumpAndSettle();
    await tester.tap(label == 'Goods' ? panel : find.descendant(of: panel, matching: find.text(label == 'Adjustments' ? 'Credit notes & refunds' : label)));
    await tester.pumpAndSettle();
  }

  Future<void> openBillPayment(WidgetTester tester) => openBillSection(tester, 'Payment');

  Future<void> revealPurchaseAction(WidgetTester tester, Finder action, {Finder? tapArea}) async {
    final viewport = find.byKey(const Key('purchase-action-category-scroll'));
    double obstructionTop(Rect bounds) {
      final group = find
          .ancestor(of: action, matching: find.byType(SliverMainAxisGroup))
          .first;
      final persistent = tester.widget<SliverPersistentHeader>(
        find
            .descendant(
              of: group,
              matching: find.byType(
                SliverPersistentHeader,
                skipOffstage: false,
              ),
              skipOffstage: false,
            )
            .first,
      );
      if (!persistent.pinned) return bounds.top;
      final header = find
          .descendant(
            of: group,
            matching: find.byWidgetPredicate(
              (w) =>
                  w is Semantics &&
                  w.key is ValueKey<String> &&
                  (w.key! as ValueKey<String>).value.startsWith(
                    'purchase-category-state-',
                  ),
              skipOffstage: false,
            ),
            skipOffstage: false,
          )
          .first;
      return tester.getRect(header).bottom.clamp(bounds.top, bounds.bottom);
    }

    // Resize can move a lazily built action above the retained scroll offset.
    // Search forward from the start rather than only scrolling farther away.
    if (action.evaluate().isEmpty) {
      final scroll = tester
          .state<ScrollableState>(
            find
                .descendant(of: viewport, matching: find.byType(Scrollable))
                .first,
          )
          .position;
      scroll.jumpTo(scroll.minScrollExtent);
      await tester.pumpAndSettle();
    }
    await tester.scrollUntilVisible(
      action,
      80,
      scrollable: find
          .descendant(of: viewport, matching: find.byType(Scrollable))
          .first,
    );
    await tester.ensureVisible(action);
    await tester.pumpAndSettle();
    // Sliver ensureVisible does not account for an expanded category's pinned header.
    // Correct that host-only reveal offset without tiny drag gestures becoming action taps.
    for (var attempt = 0; attempt < 8; attempt++) {
      final bounds = tester.getRect(viewport), target = tester.getRect(action);
      final top = obstructionTop(bounds);
      final delta = target.bottom > bounds.bottom
          ? bounds.bottom - target.bottom - 2
          : target.top < top
          ? top - target.top + 2
          : 0.0;
      if (delta.abs() < .1) break;
      final scroll = tester
          .state<ScrollableState>(
            find
                .descendant(of: viewport, matching: find.byType(Scrollable))
                .first,
          )
          .position;
      scroll.jumpTo(
        (scroll.pixels - delta).clamp(
          scroll.minScrollExtent,
          scroll.maxScrollExtent,
        ),
      );
      await tester.pumpAndSettle();
    }
    expect(action.hitTestable(), findsOneWidget);
    // A tall tile may exceed the viewport while its full title remains tappable.
    // Measure the enclosing touch area, retaining title visibility checks below.
    expect(tester.getSize(tapArea ?? action).height, greaterThanOrEqualTo(48));
    final bounds = tester.getRect(viewport), target = tester.getRect(action);
    if (tapArea != null) {
      final visibleArea = tester.getRect(tapArea).intersect(Rect.fromLTRB(
        bounds.left, obstructionTop(bounds), bounds.right, bounds.bottom));
      expect(visibleArea.height, greaterThanOrEqualTo(48));
    }
    expect(
      target.top,
      greaterThanOrEqualTo(obstructionTop(bounds) - .1),
      reason:
          'The entire action must be unobscured by its pinned category heading.',
    );
    expect(target.left, greaterThanOrEqualTo(bounds.left - .1));
    expect(target.right, lessThanOrEqualTo(bounds.right + .1));
    expect(target.top, greaterThanOrEqualTo(bounds.top - .1));
    expect(
      target.bottom,
      lessThanOrEqualTo(bounds.bottom + .1),
      reason:
          'The entire action must fit the visible category viewport. '
          'Action=$target viewport=$bounds obstructionTop=${obstructionTop(bounds)}',
    );
  }

  // Preserve intent parity while exercising the actual single entry point.
  Future<Finder> purchaseRegisterAction(
    WidgetTester tester,
    String intent, {WorkSession? owner}
  ) async {
    final work = owner ?? tester
        .widget<MoolSocialApp>(find.byType(MoolSocialApp))
        .workSession!;
    final action = switch (intent) {
      'work-purchase-new' => 'record-bill',
      'work-purchase-opening' => 'opening',
      'work-purchase-receive-goods' => 'receive',
      _ =>
        work.workspacePurchaseEntryDraft == null
            ? 'record-bill'
            : work.workspacePurchaseDraftReviewed
            ? 'edit'
            : 'continue-bill',
    };
    if (find
        .byKey(const Key('work-purchase-action-centre'))
        .evaluate()
        .isEmpty) {
      final entry = find.byKey(const Key('work-purchase-action-centre-open'));
      if (entry.evaluate().isEmpty) {
        final register = find.byWidgetPredicate(
          (w) =>
              w is CustomScrollView &&
              w.key is PageStorageKey<String> &&
              (w.key! as PageStorageKey<String>).value.startsWith(
                'work-purchases-',
              ),
        );
        expect(register, findsOneWidget);
        final scrollable = find
            .descendant(of: register, matching: find.byType(Scrollable))
            .first;
        for (
          var attempt = 0;
          attempt < 20 &&
              tester.state<ScrollableState>(scrollable).position.pixels > .1;
          attempt++
        ) {
          await tester.drag(register, const Offset(0, 400));
          await tester.pumpAndSettle();
        }
        expect(
          tester.state<ScrollableState>(scrollable).position.pixels,
          closeTo(0, .1),
        );
        await tester.scrollUntilVisible(
          entry,
          120,
          maxScrolls: 20,
          scrollable: scrollable,
        );
      }
      await tester.ensureVisible(entry);
      await tester.pumpAndSettle();
      expect(entry.hitTestable(), findsOneWidget);
      expect(tester.getSize(entry).height, greaterThanOrEqualTo(48));
      await tester.tap(entry);
      await tester.pumpAndSettle();
    }
    final category = action == 'opening'
        ? 'Starting records'
        : action == 'receive'
        ? 'Goods received & returns'
        : 'Supplier bills';
    final group = find.byKey(
      ValueKey('purchase-category-group-$category'),
      skipOffstage: false,
    );
    await Scrollable.ensureVisible(tester.element(group));
    await tester.pumpAndSettle();
    final tile = find.byKey(ValueKey('purchase-category-$category'));
    if (tester
            .widget<Semantics>(
              find.byKey(Key('purchase-category-state-$category')),
            )
            .properties
            .expanded !=
        true) {
      await tester.tap(tile);
      await tester.pumpAndSettle();
    }
    final target = find.byKey(Key('purchase-action-$action'));
    await revealPurchaseAction(tester, target);
    return target;
  }

  Future<void> openPurchaseEntryFromList(WidgetTester tester, {WorkSession? owner}) async {
    final action = await purchaseRegisterAction(tester, 'work-purchase-record', owner: owner);
    await revealPurchaseAction(tester, action);
    await tester.tap(action);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-record-purchase')), findsOneWidget);
  }

