      expectCompleteInvoiceFit();
      await openBillActions(tester);
      expect(find.byKey(const Key('work-purchase-bill-actions-toggle')), findsNothing,
        reason: 'No extra Actions tap is needed to reveal the permanent grid.');
      expect(find.byKey(const Key('work-purchase-bill-actions-panel')), findsOneWidget);
      expectCompleteInvoiceFit();
      final invoiceHeight = tester.getSize(find.byKey(const Key('purchase-review-zoom'))).height;
      expect(invoiceHeight,
        greaterThan(tester.getSize(find.byKey(const Key('work-purchase-saved-copy'))).height / 2));
      final scroll = tester.state<ScrollableState>(find.descendant(
        of: find.byKey(const Key('work-purchase-saved-copy')),
        matching: find.byWidgetPredicate((widget) => widget is Scrollable &&
          widget.axisDirection == AxisDirection.down)).first);
      scroll.position.jumpTo(scroll.position.maxScrollExtent.clamp(0.0, 30.0));
      await tester.pumpAndSettle();
      expect(tester.getSize(find.byKey(const Key('purchase-review-zoom'))).height,
        closeTo(invoiceHeight, .01), reason: 'Scrolling does not resize the invoice viewport.');
      await tester.ensureVisible(find.byKey(const Key('work-purchase-copy-close')));
      await tester.pumpAndSettle();
      await tester.tap(find.byKey(const Key('work-purchase-copy-close')));
      await tester.pumpAndSettle();
      expect(tester.widget<TextField>(find.byKey(const Key('work-purchase-search'))).controller!.text,
        reference, reason: 'Returning preserves the history selection rather than opening another bill.');
    }
    expect(jsonEncode(entry.value!.toJson()), before);
    expect(tester.takeException(), isNull);
    await tester.pumpWidget(const SizedBox.shrink());
  });

  Future<void> revealPurchaseInput(
    WidgetTester tester,
    Finder target, {
    double delta = 60,
  }) async {
    final reader = find.byKey(const Key('purchase-full-screen-preview'));
    if (reader.evaluate().isNotEmpty &&
        target.evaluate().isNotEmpty &&
        target.evaluate().every(
          (element) =>
              ModalRoute.of(element) != ModalRoute.of(tester.element(reader)),
        )) {
      // Editing/save controls are outside reading mode: explicitly return first.
      await tester.tap(find.byKey(const Key('purchase-full-screen-close')));
      await tester.pumpAndSettle();
    }
    if (target.evaluate().length == 1 && tester.widget(target) is Column) {
      // Static subsections can be taller than the viewport; their title, not centre, is the visible landmark.
      final title = find
          .descendant(of: target, matching: find.byType(Text))
          .first;
      await revealPurchaseInput(tester, title, delta: delta);
      return;
    }
    if (target.hitTestable().evaluate().isNotEmpty) return;
    // The outer purchase ListView comes first; detected SelectableText may also scroll.
    final scroll = find
        .descendant(
          of: find.byKey(const Key('work-record-purchase')),
          matching: find.byWidgetPredicate(
            (widget) =>
                widget is Scrollable &&
                widget.axisDirection == AxisDirection.down,
          ),
        )
        .first;
    await tester.scrollUntilVisible(target, delta, scrollable: scroll);
    await tester.pumpAndSettle();
    await Scrollable.ensureVisible(tester.element(target), alignment: .5);
    await tester.pumpAndSettle();
    expect(target.hitTestable(), findsOneWidget);
  }

  Future<void> expandPurchasePrimarySections(WidgetTester tester) async {
    // Explicit user taps for older editing/recovery tests, not a different app default.
    for (final key in [
      'supplier-section',
      'invoice-section',
      'items-section',
    ]) {
      final header = find.byKey(Key('work-purchase-$key'));
      await revealPurchaseInput(tester, header);
      await tester.tap(header);
      await tester.pumpAndSettle();
    }
    await revealPurchaseInput(
      tester,
      find.byKey(const Key('work-purchase-supplier-name')),
      delta: -60,
    );
  }

  Future<void> usePurchaseControl(
    WidgetTester tester,
    String key, {
    bool keepPreviewOpen = false,
  }) async {
    final target = key == 'work-purchase-record'
        ? await purchaseRegisterAction(tester, key)
        : find.byKey(Key(key));
    await revealPurchaseInput(tester, target);
    if (tester.widget(target) is Column) {
      // Former nested reveal controls are now static subheadings with all children present.
      expect(
        find.descendant(of: target, matching: find.byType(ExpansionTile)),
        findsNothing,
      );
      return;
    }
    if (find.byKey(ValueKey('purchase-panel-$key')).evaluate().isNotEmpty) {
      return;
    }
    await tester.tap(target);
    await tester.pumpAndSettle();
    if (key == 'work-purchase-preview' && !keepPreviewOpen) {
      // Existing accounting/editing tests review then Close before saving/editing.
      expect(
        find.byKey(const Key('purchase-full-screen-preview')),
        findsOneWidget,
      );
      await tester.tap(find.byKey(const Key('purchase-full-screen-close')));
      await tester.pumpAndSettle();
    }
  }

  Future<void> expandPurchaseActionCategory(
    WidgetTester tester,
    String category,
  ) async {
    final heading = find.byKey(Key('purchase-category-$category'));
    final group = find.byKey(
      ValueKey('purchase-category-group-$category'),
      skipOffstage: false,
    );
    await Scrollable.ensureVisible(tester.element(group));
    await tester.pumpAndSettle();
    final viewport = find.byKey(const Key('purchase-action-category-scroll'));
    final bounds = tester.getRect(viewport), target = tester.getRect(heading);
    final scroll = tester
        .state<ScrollableState>(
          find
              .descendant(of: viewport, matching: find.byType(Scrollable))
              .first,
        )
        .position;
    if (target.top < bounds.top || target.bottom > bounds.bottom) {
      scroll.jumpTo(
        (scroll.pixels + target.top - bounds.top).clamp(
          scroll.minScrollExtent,
          scroll.maxScrollExtent,
        ),
      );
      await tester.pumpAndSettle();
    }
    expect(heading.hitTestable(), findsOneWidget);
    await tester.tap(heading);
    await tester.pumpAndSettle();
  }

