  testWidgets(
    'P05-NEXT scoped save rejects duplicate bill and retains history on failure',
    (tester) async {
      final entry = _PurchaseEntryFixtureStore();
      final work = manualPurchaseFixture(entry);
      await mount(tester, route: '/app/work/workspace/dashboard', work: work);
      await openPurchaseList(tester);
      final scope = work.workspaceSupplierScope!;
      final at = DateTime.utc(2026, 9, 30);
      final supplier = WorkspaceSupplierProfile(
        id: 'p05-next-supplier',
        name: 'Evaluation next supplier',
        phone: '',
        address: '',
        gstin: '',
        createdAt: at,
        updatedAt: at,
      );
      WorkspacePurchaseEntryDraft bill(
        String id,
        String reference, {
        String date = '30/09/2026',
      }) => WorkspacePurchaseEntryDraft(
        id: id,
        supplierId: supplier.id,
        invoiceReference: reference,
        invoiceDate: date,
        createdAt: at,
        updatedAt: at,
        goods: [
          {
            'productId': '',
            'name': 'Evaluation rice',
            'pack': '1 kg',
            'quantity': '2',
            'cost': '50',
          },
        ],
      );
      WorkspacePurchaseSavedCopy copy(
        WorkspacePurchaseEntryDraft draft,
        int revision,
      ) => WorkspacePurchaseSavedCopy(
        id: '${draft.id}-r$revision',
        storeName: 'Evaluation Store',
        revision: revision,
        savedAt: at,
        supplier: supplier,
        draft: draft,
        labels: const {},
      );
      final original = bill('original-draft', 'EVAL-NEXT-01');
      expect(copy(original, 1).valid, isTrue);
      entry.value = WorkspacePurchaseEntryBook(
        account: scope.$1,
        store: scope.$2,
        qa: scope.$3,
        revision: 1,
        profiles: [supplier],
        draft: original,
        copies: [copy(original, 1)],
      );
      await work.loadWorkspaceSuppliers(retry: true);
      final before = jsonEncode(entry.value!.toJson());
      final inventoryBefore = work.workspaceCatalogueItems
          .map((p) => p.toInventoryJson())
          .toList();
      final duplicate = bill(
        'next-draft',
        ' eval-next-01 ',
        date: '01/10/2026',
      );
      expect(copy(duplicate, 2).valid, isTrue);
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: duplicate,
          expectedRevision: 1,
          replaceReviewedDraftId: original.id,
          reviewedCopy: copy(duplicate, 2),
        ),
        isFalse,
      );
      expect(work.workspaceSupplierError, contains('already saved'));
      expect(jsonEncode(entry.value!.toJson()), before);
      final invalidDate = bill(
        'next-draft',
        'EVAL-NEXT-02',
        date: '31/02/2026',
      );
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: invalidDate,
          expectedRevision: 1,
          replaceReviewedDraftId: original.id,
          reviewedCopy: copy(invalidDate, 2),
        ),
        isFalse,
      );
      expect(work.workspaceSupplierError, contains('Invoice date'));
      final next = bill('next-draft', 'EVAL-NEXT-02');
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: next,
          expectedRevision: 1,
          reviewedCopy: copy(next, 2),
        ),
        isFalse,
      );
      expect(jsonEncode(entry.value!.toJson()), before);
      entry.failSave = true;
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: next,
          expectedRevision: 1,
          replaceReviewedDraftId: original.id,
          reviewedCopy: copy(next, 2),
        ),
        isFalse,
      );
      expect(jsonEncode(entry.value!.toJson()), before);
      entry.failSave = false;
      await work.loadWorkspaceSuppliers(retry: true);
      final accepted = copy(next, 2);
      final saving = work.saveWorkspacePurchaseEntry(
        supplier,
        scope: scope,
        draft: next,
        expectedRevision: 1,
        replaceReviewedDraftId: original.id,
        reviewedCopy: accepted,
      );
      expect(work.workspaceSupplierSaving, isTrue);
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: next,
          expectedRevision: 1,
          replaceReviewedDraftId: original.id,
          reviewedCopy: accepted,
        ),
        isFalse,
      );
      expect(await saving, isTrue);
      expect(entry.value!.copies, hasLength(2));
      expect(entry.value!.copies.first.toJson(), copy(original, 1).toJson());
      final saved = jsonEncode(entry.value!.toJson());
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: next,
          expectedRevision: 1,
          replaceReviewedDraftId: original.id,
          reviewedCopy: accepted,
        ),
        isTrue,
      );
      expect(jsonEncode(entry.value!.toJson()), saved);
      final corrected = bill(next.id, 'EVAL-NEXT-02-CORRECTED');
      entry.failSave = true;
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: corrected,
          expectedRevision: 2,
          reviewedCopy: copy(corrected, 3),
        ),
        isFalse,
      );
      expect(
        entry.value!.duplicateInvoice(
          bill('third-draft', next.invoiceReference),
        ),
        isNotNull,
      );
      expect(
        entry.value!.duplicateInvoice(
          bill('third-draft', corrected.invoiceReference),
        ),
        isNull,
      );
      entry.failSave = false;
      await work.loadWorkspaceSuppliers(retry: true);
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: corrected,
          expectedRevision: 2,
          reviewedCopy: copy(corrected, 3),
        ),
        isTrue,
      );
      expect(
        entry.value!.duplicateInvoice(
          bill('third-draft', next.invoiceReference),
        ),
        isNull,
      );
      expect(
        entry.value!.duplicateInvoice(
          bill('third-draft', corrected.invoiceReference),
        ),
        isNotNull,
      );
      final later = jsonEncode(entry.value!.toJson());
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: next,
          expectedRevision: 1,
          replaceReviewedDraftId: original.id,
          reviewedCopy: accepted,
        ),
        isTrue,
      );
      expect(jsonEncode(entry.value!.toJson()), later);
      final reusedIdentity = WorkspacePurchaseSavedCopy(
        id: accepted.id,
        storeName: accepted.storeName,
        revision: accepted.revision,
        savedAt: accepted.savedAt,
        supplier: supplier,
        draft: corrected,
        labels: const {},
      );
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: corrected,
          expectedRevision: 3,
          reviewedCopy: reusedIdentity,
        ),
        isFalse,
      );
      expect(work.workspaceSupplierError, contains('different details'));
      expect(jsonEncode(entry.value!.toJson()), later);
      final third = bill('third-draft', 'EVAL-NEXT-03');
      expect(
        await work.saveWorkspacePurchaseEntry(
          supplier,
          scope: scope,
          draft: third,
          expectedRevision: 3,
          replaceReviewedDraftId: original.id,
          reviewedCopy: copy(third, 4),
        ),
        isFalse,
      );
      expect(jsonEncode(entry.value!.toJson()), later);
      expect(
        work.workspaceCatalogueItems.map((p) => p.toInventoryJson()).toList(),
        inventoryBefore,
      );
      await tester.pumpWidget(const SizedBox.shrink());
    },
  );

  testWidgets('P05-R12-C04 saved copy download wording preserves readonly state', (
    tester,
  ) async {
    // Labelled host fixture only, never runtime acceptance data.
    final entry = _PurchaseEntryFixtureStore();
    final work = manualPurchaseFixture(entry);
    final scope = work.workspaceSupplierScope!;
    final at = DateTime.utc(2026, 10, 2);
    final profile = WorkspaceSupplierProfile(
      id: 'host-c04-supplier',
      name: 'HOST ONLY C04 supplier',
      createdAt: at,
      updatedAt: at,
    );
    final draft = WorkspacePurchaseEntryDraft(
      id: 'host-c04-entry',
      supplierId: profile.id,
      invoiceReference: 'HOST-C04-1',
      invoiceDate: '02/10/2026',
      createdAt: at,
      updatedAt: at,
      goods: [
        {
          'name': 'HOST ONLY C04 rice',
          'pack': '1 kg',
          'quantity': '2',
          'cost': '40',
          'productId': '',
        },
      ],
      details: {
        'invoiceTotal': '80',
        'paymentStatus': 'On credit',
        'receiptStatus': 'Already added to Stock',
      },
    );
    final copy = WorkspacePurchaseSavedCopy(
      id: 'host-c04-copy-r1',
      storeName: 'HOST ONLY Store',
      revision: 1,
      savedAt: at,
      supplier: profile,
      draft: draft,
      labels: const {},
    );
    entry.value = WorkspacePurchaseEntryBook(
      account: scope.$1,
      store: scope.$2,
      qa: scope.$3,
      revision: 1,
      profiles: [profile],
      draft: draft,
      copies: [copy],
    );
    final original = jsonEncode(entry.value!.toJson());
    final picker = _PurchaseOriginalSaveFixture();
    final previous = FilePickerPlatform.instance;
    FilePickerPlatform.instance = picker;
    addTearDown(() => FilePickerPlatform.instance = previous);
    await mount(tester, route: '/app/work/workspace/dashboard', work: work);
    await openPurchaseList(tester);
    await tester.tap(
      find.byKey(const ValueKey('work-purchase-copy-host-c04-copy-r1')),
    );
    await tester.pumpAndSettle();
    // This fixture supplies a purchase book, not a recovered accounting journal.
    await openBillActions(tester);
    expect(work.workspaceInvoiceHistoryLoaded, isFalse);
    expect(find.text('No system voucher assigned'), findsNothing);
    expect(find.text('Supplier account status unavailable'), findsWidgets);
    expect(find.byKey(const Key('work-purchase-draft-save')), findsNothing);
    expect(find.text('Goods & payment details'), findsNothing);
    expect(find.byKey(const ValueKey('purchase-review-receiptStatus')), findsNothing);
    expect(copy.draft.details['receiptStatus'], 'Already added to Stock',
      reason: 'Removing redundant screen observations must preserve the immutable saved fields.');
    await tester.ensureVisible(find.byKey(const Key('purchase-recorded-download')));
    await tester.pumpAndSettle();
    Future<void> download() async {
      await tester.runAsync(() async {
        await tester.tap(find.byKey(const Key('purchase-recorded-download')));
        for (var i = 0; i < 40 && picker.bytes == null; i++) {
          await Future<void>.delayed(const Duration(milliseconds: 25));
        }
      });
      await tester.pumpAndSettle();
    }

    await download();
    expect(
      find.text('Download cancelled. Your saved purchase copy is kept.'),
      findsOneWidget,
    );
    picker.bytes = null;
    picker.fail = true;
    await download();
    expect(
      find.text('Could not download the purchase copy. It is kept; retry.'),
      findsOneWidget,
    );
    picker.bytes = null;
    picker.fail = false;
    picker.result = Uri.file('/host-only/c04.pdf');
    await download();
    expect(find.text('Purchase copy downloaded.'), findsOneWidget);
    expect(jsonEncode(entry.value!.toJson()), original);
    expect(work.workspacePurchases, isEmpty);
    expect(work.workspaceStockMovements, isEmpty);
    // Lose the saved-copy membership while the PDF font is loading. This is a
    // controlled host race, not a runtime storage or device injection.
    final font = await tester.runAsync(
      () => rootBundle.load('assets/fonts/Inter-Variable.ttf'),
    );
    final messenger =
        TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
    picker.bytes = null;
    final downloadControl = find.byKey(const Key('purchase-recorded-download'));
    await revealPurchaseInput(tester, downloadControl);
    final downloadCallback = tester
        .widget<TextButton>(downloadControl)
        .onPressed;
    expect(downloadCallback, isNotNull);
    await tester.runAsync(() async {
      final started = Completer<void>();
      final heldFont = Completer<ByteData?>();
      messenger.setMockMessageHandler('flutter/assets', (message) {
        expect(
          utf8.decode(
            message!.buffer.asUint8List(
              message.offsetInBytes,
              message.lengthInBytes,
            ),
          ),
          'assets/fonts/Inter-Variable.ttf',
        );
        started.complete();
        return heldFont.future;
      });
      try {
        final operation =
            Function.apply(downloadCallback!, const []) as Future<void>;
        await started.future.timeout(const Duration(seconds: 2));
        entry.value = WorkspacePurchaseEntryBook(
          account: scope.$1,
          store: scope.$2,
          qa: scope.$3,
          revision: 2,
          profiles: [profile],
          draft: draft,
        );
        await work.loadWorkspaceSuppliers(retry: true);
        heldFont.complete(font);
        await operation.timeout(const Duration(seconds: 5));
      } finally {
        if (!heldFont.isCompleted) {
          heldFont.complete(font);
        }
        messenger.setMockMessageHandler('flutter/assets', null);
      }
    });
    await tester.pumpAndSettle();
    expect(picker.bytes, isNull);
    expect(
      find.text(
        'Saved purchase copy changed or is unavailable. Reopen it from Purchases before downloading.',
      ),
      findsOneWidget,
    );
    final unavailable = jsonEncode(entry.value!.toJson());
    await tester.tap(find.byKey(const Key('purchase-recorded-download')));
    await tester.pumpAndSettle();
    expect(
      find.text(
        'Saved purchase copy is unavailable. Reopen it from Purchases and retry.',
      ),
      findsOneWidget,
    );
    expect(picker.bytes, isNull);
    expect(jsonEncode(entry.value!.toJson()), unavailable);
    expect(work.workspacePurchases, isEmpty);
    expect(work.workspaceStockMovements, isEmpty);
    expect(tester.takeException(), isNull);
    await tester.pumpWidget(const SizedBox.shrink());
  });

