          for (final delta in [
            const Offset(0, 40),
            const Offset(40, 0),
            const Offset(0, -40),
            const Offset(-40, 0),
          ]) {
            final rect = tester.getRect(surface);
            final scroll = outer.position.pixels;
            final before = Matrix4.copy(transform.value);
            final gesture = await tester.startGesture(rect.center);
            await tester.pump();
            await gesture.moveBy(delta / 2);
            await tester.pump();
            await gesture.moveBy(delta / 2);
            await tester.pump();
            await gesture.up();
            await tester.pumpAndSettle();
            expect(
              outer.position.pixels,
              closeTo(scroll, .1),
              reason: 'Document drag must not scroll the surrounding form.',
            );
            expect(tester.getRect(surface).top, closeTo(rect.top, .1));
            expect(
              transform.value,
