  // P04 automated UI evidence only; physical OPPO/user-flow acceptance remains separate.
  Future<void> revealOpening(
    WidgetTester tester,
    Finder target, {
    double delta = 120,
  }) async {
    if (target.evaluate().isEmpty) {
      await tester.scrollUntilVisible(
        target,
        delta,
        scrollable: find
            .descendant(
              of: find.byKey(const Key('work-opening-dues-form')),
              matching: find.byType(Scrollable),
            )
            .first,
      );
    }
    await tester.ensureVisible(target);
    await tester.pumpAndSettle();
    expect(
      target.hitTestable(),
      findsOneWidget,
      reason: 'Opening record control must be reachable by touch.',
    );
  }

  Future<void> saveOpeningSupplier(
    WidgetTester tester, {
    String name = 'Evaluation opening supplier',
  }) async {
    await openPurchaseList(tester);
    await tester.ensureVisible(
      await purchaseRegisterAction(tester, 'work-purchase-record'),
    );
    await tester.tap(
      await purchaseRegisterAction(tester, 'work-purchase-record'),
