                matching: find.byType(Scrollable)).first;
              await tester.scrollUntilVisible(position, 100, scrollable: statementScroll); await tester.pumpAndSettle();
              await Scrollable.ensureVisible(tester.element(position), alignment: .4); await tester.pumpAndSettle();
              await tester.tap(position); await tester.pumpAndSettle();
              final reference = find.byKey(ValueKey('work-stock-reference-${movement.id}'));
              final historyScroll = find.descendant(of: find.byKey(const Key('work-stock-statement-screen')),
                matching: find.byType(Scrollable)).first;
              await tester.scrollUntilVisible(reference, 100, scrollable: historyScroll); await tester.pumpAndSettle();
              await Scrollable.ensureVisible(tester.element(reference), alignment: .4); await tester.pumpAndSettle();
              await tester.tap(reference); await tester.pumpAndSettle();
              expect(find.text('Receiving details'), findsOneWidget);
              final detailScroll = find.descendant(of: find.byType(Dialog), matching: find.byType(Scrollable)).first;
              for (final label in ['Recorded from this arrival · private', 'Batch: HOST-RESTOCK-LOT', 'Manufactured: 09/2026',
                'Expiry / best before: Best before 03/2027', 'Pack MRP ₹125.50']) {
                final detail = find.text(label);
                await tester.scrollUntilVisible(detail, 80, scrollable: detailScroll); await tester.pumpAndSettle();
                await Scrollable.ensureVisible(tester.element(detail), alignment: .4); await tester.pumpAndSettle();
                expect(detail.hitTestable(), findsOneWidget);
              }
              final close = tester.widget<IconButton>(find.byWidgetPredicate((widget) =>
                widget is IconButton && widget.tooltip == 'Close receiving details')).onPressed!;
              final dialogContext = tester.element(find.byType(Dialog));
              final covered = showDialog<void>(context: dialogContext, builder: (_) => const AlertDialog(title: Text('HOST successor')));
              await tester.pumpAndSettle(); close(); await tester.pumpAndSettle();
              expect(find.text('HOST successor'), findsOneWidget, reason: 'A covered dialog Close cannot pop the successor.');
              Navigator.of(tester.element(find.text('HOST successor'))).pop(); await tester.pumpAndSettle(); await covered;
              final current = work.activeWorkspace;
              work.activeWorkspace = null; work.activeWorkspace = current; work.notifyListeners(); await tester.pumpAndSettle();
              expect(find.text('Batch: HOST-RESTOCK-LOT'), findsNothing);
              expect(find.text('This receiving record is no longer available in the current Store. Close and reopen it.'), findsOneWidget);
              await tester.tap(find.byTooltip('Close receiving details')); await tester.pumpAndSettle();
              expect(find.text('Receiving details'), findsNothing);
              close(); await tester.pumpAndSettle();
              expect(find.byKey(const Key('work-stock-statement-screen')), findsOneWidget);
              expect(work.workspaceCatalogueItems.singleWhere((p) => p.id == product.id).stock, before + 1);
              expect(work.workspaceGoodsReceiptDrafts.single.receipt.toJson(), savedReceipt.toJson());
              expect(wire.requests.where((r) => r['operation'] == 'recordBuyerGoodsArrival'), hasLength(1));
            }
            if (mode == 'server-partial') {
              expect(work.workspaceGoodsReceiptDrafts.single.receipt.restockOriginal!.lines, hasLength(2));
              expect(work.workspaceGoodsReceiptDrafts.single.receipt.lines, hasLength(1));
              final reads = wire.requests.where((r) => r['operation'] == 'readBuyerGoodsReceiving').length;
              await receivingField('work-receive-next'); await tester.tap(find.byKey(const Key('work-receive-next'))); await tester.pumpAndSettle();
              expect(wire.requests.where((r) => r['operation'] == 'readBuyerGoodsReceiving').length, greaterThan(reads));
              await receivingField('work-receive-factor-0', delta: -140);
              final factor = tester.widget<TextField>(find.byKey(const Key('work-receive-factor-0')));
              expect(factor.controller!.text, '2'); expect(factor.enabled, isFalse);
              await receivingField('work-receive-delivered-0'); await tester.enterText(find.byKey(const Key('work-receive-delivered-0')), '0.5');
              await receivingField('work-receive-lot-0');
              await tester.tap(find.descendant(of: find.byKey(const Key('work-receive-lot-0')),
                matching: find.text('Batch & pack details · optional'))); await tester.pumpAndSettle();
              await receivingField('work-receive-batch-0');
              await tester.enterText(find.byKey(const Key('work-receive-batch-0')), 'HOST-RESTOCK-SECOND');
              await receivingField('work-receive-product-1'); await tester.tap(find.byKey(const Key('work-receive-product-1'))); await tester.pumpAndSettle();
              await tester.tap(find.text('${product.title} · ${product.pack}').last); await tester.pumpAndSettle();
              await receivingField('work-receive-factor-1'); await tester.enterText(find.byKey(const Key('work-receive-factor-1')), '1');
              await receivingField('work-receive-delivered-1'); await tester.enterText(find.byKey(const Key('work-receive-delivered-1')), '1');
              FocusManager.instance.primaryFocus?.unfocus(); await tester.pumpAndSettle();
              await receivingField('work-receive-review'); await tester.tap(find.byKey(const Key('work-receive-review'))); await tester.pumpAndSettle();
              await receivingField('work-receive-confirm'); await tester.tap(find.byKey(const Key('work-receive-confirm'))); await tester.pumpAndSettle();
              await receivingField('work-receive-status'); expect(find.text('Goods recorded'), findsOneWidget);
              expect(work.workspaceCatalogueItems.singleWhere((p) => p.id == product.id).stock, before + 3);
              expect(work.workspaceGoodsReceiptDrafts, hasLength(2));
              for (final (index, batch) in [(0, 'HOST-RESTOCK-LOT'), (1, 'HOST-RESTOCK-SECOND')]) {
                final arrival = work.workspaceGoodsReceiptDrafts[index].receipt;
                final movement = work.workspaceStockMovements.singleWhere((m) =>
                  m.referenceKind == WorkspaceStockReferenceKind.restockGoodsArrival &&
                  work.workspaceReceivingForStockMovement(m)?.$1.id == arrival.id &&
                  work.workspaceReceivingForStockMovement(m)?.$2.sourceLineId == 'line-one');
                expect(work.workspaceReceivingForStockMovement(movement)?.$2.lotDetails?.batch, batch);
              }
              expect(find.byKey(const Key('work-receive-next')), findsNothing);
              expect(work.workspaceSupplierLedger(supplier.id), isNull);
              expect(wire.requests.where((r) => r['operation'] == 'recordBuyerGoodsArrival'), hasLength(2));
            }
            expect(tester.takeException(), isNull);
            return;
          }
        }
      }
      await tester.binding.handlePopRoute(); await tester.pumpAndSettle();
      expect(find.byKey(const Key('work-goods-receiving')), findsNothing);
      expect(controller.session, same(buy)); expect(buy.itemCount, cartBefore);
      expect(tester.state(originalTile()), same(originalState));
      expect(find.byKey(const ValueKey('purchase-receive-order-order-v2')), findsOneWidget);
      if (scopedReader) {
        await reveal(tester, receive);
        final restored = tester.getSemantics(receive).getSemanticsData();
        expect(restored.label, receiveLabel); expect(restored.hasAction(ui.SemanticsAction.tap), isTrue);
      }
      if (mode != 'unrelated') {
        expect(jsonDecode(forms.drafts[key]!.fields['input']!)[0], 'HOST actual arrival input');
        await reveal(tester, receive); await tester.tap(receive); await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('work-receive-supplier'))); await tester.pumpAndSettle();
        await tester.tap(find.text(supplier.name).last); await tester.pumpAndSettle();
        await receivingField('work-receive-reference');
        expect(tester.widget<TextField>(find.byKey(const Key('work-receive-reference'))).controller!.text, 'HOST actual arrival input');
        expect(forms.drafts[key]!.fields.containsKey('restockOriginal'), isTrue);
        await tester.tap(find.byKey(const Key('work-back'))); await tester.pumpAndSettle();
        expect(find.byKey(const Key('work-goods-receiving')), findsNothing);
      }
      expect(work.workspaceGoodsReceiptDrafts.length, mode == 'review' ? 1 : 0,
        reason: 'Opening or saving input never posts Stock or a receipt review.');
      if (mode == 'normal' || mode == 'review') {
        final savedInput = Map<String, String>.of(forms.drafts[key]!.fields);
        await tester.pumpWidget(const SizedBox.shrink()); await tester.pumpAndSettle();
        final resumed = serverWork()..bindOriginalPurchaseReader(reader, 'evaluation');
        await mount(tester, route: '/app/work/workspace/dashboard', work: resumed, textScale: 1);
        // The default host app has no authenticated purchase source. Restore
        // this isolated accepted reader after that root binding, as on entry.
        resumed.bindOriginalPurchaseReader(reader, 'evaluation');
        await openPurchaseList(tester);
        final action = await purchaseRegisterAction(tester, 'work-purchase-receive-goods');
        await revealPurchaseAction(tester, action); await tester.tap(action); await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('work-receive-supplier'))); await tester.pumpAndSettle();
        await tester.tap(find.text(supplier.name).last); await tester.pumpAndSettle();
        expect(forms.drafts[key]!.fields, savedInput);
        expect(find.byKey(const Key('work-receive-order-context')), findsOneWidget);
        if (mode == 'review') {
          await receivingField('work-receive-status'); expect(find.text('Receipt reviewed · Stock unchanged'), findsOneWidget);
        } else {
          await receivingField('work-receive-expected-0');
          expect(tester.widget<TextField>(find.byKey(const Key('work-receive-expected-0'))).enabled, isFalse);
        }
      }
      expect(tester.takeException(), isNull);
      await tester.pumpWidget(const SizedBox.shrink());
      } finally {
        scopedSemantics?.dispose();
      }
    });
  }

  for (final failDiscard in [false, true]) {
    testWidgets(
      'PURCHASERECEIVEUI discard preserves history and recovers failed reset $failDiscard',
      (tester) async {
        // Host-only evaluation fixtures; not device or backend acceptance.
        FlutterSecureStorage.setMockInitialValues({});
        final entry = _OpeningPostingFixtureStore(),
            checkpoint = _LedgerCheckpointFixtureStore();
        final forms = _LedgerFormFixtureStore();
        var work = postingOpeningFixture(entry, checkpoint, moneyStore: forms);
        final scope = work.workspaceSupplierScope!, at = DateTime.now().toUtc();
        final supplier = WorkspaceSupplierProfile(
          id: 'discard-draft-supplier',
          name: 'Evaluation delivery supplier',
          phone: '',
          address: '',
          gstin: '',
          createdAt: at,
          updatedAt: at,
        );
        entry.value = WorkspacePurchaseEntryBook(
          account: scope.$1,
          store: scope.$2,
          qa: scope.$3,
          revision: 1,
          profiles: [supplier],
        );
        final bookBefore = entry.value!.toJson();
        await mount(tester, route: '/app/work/workspace/dashboard', work: work);
        await openPurchaseList(tester);
        final action = await purchaseRegisterAction(
          tester,
          'work-purchase-receive-goods',
        );
        await revealPurchaseAction(tester, action);
        await tester.tap(action);
        await tester.pumpAndSettle();
        final picker = find.byKey(const Key('work-receive-supplier'));
        await Scrollable.ensureVisible(tester.element(picker), alignment: .5);
        await tester.pumpAndSettle();
        await tester.tap(picker);
        await tester.pumpAndSettle();
        await tester.tap(find.text(supplier.name).last);
        await tester.pumpAndSettle();
        final reference = find.byKey(const Key('work-receive-reference'));
        await Scrollable.ensureVisible(
          tester.element(reference),
          alignment: .5,
        );
        await tester.pumpAndSettle();
        await tester.enterText(reference, 'Unfinished delivery');
        FocusManager.instance.primaryFocus?.unfocus();
        await tester.pumpAndSettle();
        final key = work.supplierReceivingInputFormKey(supplier.id)!;
        final before = (await work.readLedgerForm(key))!.fields;
        final discard = find.byKey(const Key('work-receive-discard-input'));
        await Scrollable.ensureVisible(tester.element(discard), alignment: .5);
        await tester.pumpAndSettle();
        expect(discard.hitTestable(), findsOneWidget);
        await tester.tap(discard);
        await tester.pumpAndSettle();
        await tester.tap(find.text('Keep draft'));
        await tester.pumpAndSettle();
        expect((await work.readLedgerForm(key))!.fields, before);
        forms.failWrite = failDiscard;
        await tester.tap(discard);
        await tester.pumpAndSettle();
        await tester.tap(find.text('Discard draft'));
        await tester.pumpAndSettle();
        if (failDiscard) {
          expect(
            find.textContaining('Draft discard is not verified.'),
            findsWidgets,
          );
          expect((await work.readLedgerForm(key))!.fields, before);
          expect(
            tester.widget<TextField>(reference).controller!.text,
            'Unfinished delivery',
          );
          expect(tester.widget<TextField>(reference).enabled, isFalse);
          forms.failWrite = false;
          await Scrollable.ensureVisible(
            tester.element(discard),
            alignment: .5,
          );
          await tester.pumpAndSettle();
          await tester.tap(discard);
          await tester.pumpAndSettle();
        }
        final after = (await work.readLedgerForm(key))!.fields;
        expect(after['arrivalId'], isNot(before['arrivalId']));
        expect(tester.widget<TextField>(reference).controller!.text, isEmpty);
        expect(entry.value!.toJson(), bookBefore);
        expect(checkpoint.saveAttempts, 0);
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
        work = postingOpeningFixture(entry, checkpoint, moneyStore: forms);
        await mount(tester, route: '/app/work/workspace/dashboard', work: work);
        await openPurchaseList(tester);
        await tester.tap(
          await purchaseRegisterAction(tester, 'work-purchase-receive-goods'),
        );
        await tester.pumpAndSettle();
        await Scrollable.ensureVisible(tester.element(picker), alignment: .5);
        await tester.pumpAndSettle();
        await tester.tap(picker);
        await tester.pumpAndSettle();
        await tester.tap(find.text(supplier.name).last);
        await tester.pumpAndSettle();
        expect(tester.widget<TextField>(reference).controller!.text, isEmpty);
        expect(
          (await work.readLedgerForm(
            work.supplierReceivingInputFormKey(supplier.id)!,
          ))!.fields['arrivalId'],
          after['arrivalId'],
        );
        expect(entry.value!.toJson(), bookBefore);
        expect(checkpoint.saveAttempts, 0);
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
      },
    );
  }

