        await tester.pumpAndSettle();
        await reveal('work-receive-review');
        await tester.tap(find.byKey(const Key('work-receive-review')));
        await tester.pumpAndSettle();
        inventory.failProjection = variant == 'projection-failed';
        await reveal('work-receive-confirm');
        await tester.tap(find.byKey(const Key('work-receive-confirm')));
        await tester.pumpAndSettle();
        if (variant == 'projection-failed') {
          // Before authoritative readback, the frozen editor must not claim success.
          expect(
            find.byKey(const Key('work-receive-new-delivery')),
            findsNothing,
          );
          final recover = find.text('Recover saved status');
          await tester.scrollUntilVisible(recover, 120, scrollable: scroll);
          await tester.pumpAndSettle();
          await tester.tap(recover);
          await tester.pumpAndSettle();
        }
        final summary = find.byKey(const Key('work-receive-total-1'));
        await tester.scrollUntilVisible(summary, -120, scrollable: scroll);
        await tester.pumpAndSettle();
        expect(
          find.text(
            variant == 'unknown-expected'
                ? 'Total received 3 · expected quantity not entered'
                : 'Total received 3 of 3 · pending 0',
          ),
          findsOneWidget,
        );
        expect(
          find.byKey(const Key('work-receive-delivered-0')),
