          reason:
              'Confirmed receipt is a compact read-only record, not a disabled editor.',
        );
        await reveal('work-receive-saved-supplier', delta: -120);
        expect(find.text('Goods received'), findsOneWidget);
        expect(
          tester
              .widget<Text>(
                find.byKey(const Key('work-receive-saved-supplier')),
              )
              .style!
              .color,
          MoolColors.ink,
        );
        expect(find.byKey(const Key('work-receive-reference')), findsNothing);
        expect(find.byKey(const Key('work-receive-date')), findsNothing);
        expect(
          find.text(
            'Record goods with or without a supplier bill. Link earlier Stock entries instead of adding them again.',
          ),
