          expect(
            find.byKey(const Key('work-receive-new-delivery')),
            findsNothing,
          );
          final receiptCount = work
              .workspaceSupplierLedger(supplier.id)!
              .goodsReceipts
              .length;
          inventory.failProjection = false;
          await tester.tap(find.byKey(const Key('work-receive-confirm')));
          await tester.pumpAndSettle();
          expect(work.workspaceGoodsReceiptRecoveryPending, isFalse);
          expect(
            work.workspaceSupplierLedger(supplier.id)!.goodsReceipts.length,
            receiptCount,
          );
        }
        if (variant == 'unavailable-records') {
          entry.failRead = true;
          expect(await work.loadWorkspaceSuppliers(retry: true), isFalse);
          await tester.pumpAndSettle();
          expect(find.byKey(const Key('work-receive-next')), findsNothing);
          expect(
            find.byKey(const Key('work-receive-new-delivery')),
            findsNothing,
          );
          entry.failRead = false;
          final recover = find.text('Recover saved status');
          await tester.scrollUntilVisible(recover, 120, scrollable: scroll);
          await tester.pumpAndSettle();
          await tester.tap(recover);
          await tester.pumpAndSettle();
          expect(work.workspaceSupplierRecoveryError, isNull);
        }
        await reveal('work-receive-new-delivery');
        if (variant == 'unknown-expected') {
          expect(find.byKey(const Key('work-receive-next')), findsOneWidget);
        } else {
          expect(
            find.byKey(const Key('work-receive-next')),
            findsNothing,
            reason:
                'Every known expected line is fully delivered, including earlier omitted lines.',
          );
        }
        expect(find.byKey(const Key('work-receive-confirm')), findsNothing);
        expect(find.text('Recover saved status'), findsNothing);
        final ledgerAfter = jsonEncode(
          work.workspaceSupplierLedger(supplier.id)!.toJson(),
        );
        final stockAfter = work.workspaceCatalogueItems
            .map((p) => (p.id, p.stock))
            .toList();
        await tester.tap(find.byKey(const Key('work-receive-new-delivery')));
        await tester.pumpAndSettle();
        expect(
          jsonEncode(work.workspaceSupplierLedger(supplier.id)!.toJson()),
          ledgerAfter,
        );
        expect(
          work.workspaceCatalogueItems.map((p) => (p.id, p.stock)).toList(),
          stockAfter,
          reason:
              'Starting a new delivery must not change Stock or supplier books.',
        );
        if (variant == 'portrait' || variant == 'large-landscape') {
          await tester.tap(find.byKey(const Key('work-store-stock')));
          await tester.pumpAndSettle();
          await openStoreStockStatement(tester);
          await tester.pumpAndSettle();
          final position = find.byKey(Key('work-stock-position-${products.first.id}'));
          final positionScroll = find.descendant(of: find.byKey(const Key('work-stock-statement-screen')),
            matching: find.byType(Scrollable)).first;
          await tester.scrollUntilVisible(position, 100, scrollable: positionScroll);
          await tester.pumpAndSettle();
          await Scrollable.ensureVisible(tester.element(position), alignment: .4);
          await tester.pumpAndSettle();
          await tester.tap(position);
          await tester.pumpAndSettle();
          final movement = first.movementFor(first.lines.first)!;
          final reference = find.byKey(ValueKey('work-stock-reference-${movement.id}'));
          final historyScroll = find.descendant(of: find.byKey(const Key('work-stock-statement-screen')),
            matching: find.byType(Scrollable)).first;
          await tester.scrollUntilVisible(reference, 100, scrollable: historyScroll);
          await tester.pumpAndSettle();
          await Scrollable.ensureVisible(tester.element(reference), alignment: .4);
          await tester.pumpAndSettle();
          await tester.tap(reference);
          await tester.pumpAndSettle();
          expect(find.text('Receiving details'), findsOneWidget);
          final detailScroll = find.descendant(of: find.byType(Dialog), matching: find.byType(Scrollable)).first;
          for (final label in ['Batch: HOST-PREVIOUS-LOT', 'Manufactured: 09/2026',
            'Expiry / best before: Use by 03/2027', 'Pack MRP ₹125.50']) {
            final detail = find.text(label);
            await tester.scrollUntilVisible(detail, 80, scrollable: detailScroll);
            await tester.pumpAndSettle();
            await Scrollable.ensureVisible(tester.element(detail), alignment: .4);
            await tester.pumpAndSettle();
            expect(detail.hitTestable(), findsOneWidget);
          }
          expect(work.workspaceCatalogueItems.map((p) => (p.id, p.stock)).toList(), stockAfter);
          await tester.tap(find.byTooltip('Close receiving details'));
          await tester.pumpAndSettle();
        }
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
      },
    );
  }

  for (final (display, failedReview, freeText, cancelReview, recoveryCase) in [
    (const Size(360, 800), false, '0', false, 'normal'),
    (const Size(915, 412), false, '0', false, 'normal'),
    (const Size(360, 800), true, '0', false, 'normal'),
    (const Size(360, 800), false, '   ', false, 'normal'),
    (const Size(360, 800), false, '-', false, 'normal'),
    (const Size(360, 800), false, '0', true, 'normal'),
    (const Size(360, 800), false, '1', false, 'normal'),
    (const Size(360, 800), false, '0', false, 'completed-read-failure'),
    (const Size(360, 800), false, '0', false, 'different-units'),
    (const Size(360, 800), false, '0', false, 'identical-receipts'),
