      expect(tester.widget<TextField>(amount).controller!.text, '1500');
      expect(
        tester.widget<TextField>(reference).controller!.text,
        'HOST-PAY-FULL',
      );
      expect(tester.takeException(), isNull);
      tester.view.viewInsets = FakeViewPadding.zero;
      await revealMoney(reference);
      await tester.tap(reference);
      await tester.pumpAndSettle();
      expect(tester.testTextInput.isVisible, isTrue);
      final retainedSelection = tester
          .widget<TextField>(reference)
          .controller!
          .selection;
      await revealMoney(find.byKey(const Key('supplier-money-submit')));
      expect(keyboardClose.hitTestable(), findsOneWidget);
      expect(
        hideKeyboard.hitTestable(),
        findsOneWidget,
        reason:
            'Dismissal must not depend on floating keyboards reporting bottom insets.',
      );
      await tester.tap(hideKeyboard);
      await tester.pumpAndSettle();
      expect(tester.testTextInput.isVisible, isFalse);
      expect(
        tester.widget<TextField>(reference).controller!.selection,
        retainedSelection,
      );
      FocusManager.instance.primaryFocus?.unfocus();
      await tester.pumpAndSettle();
      final excluded = find.byKey(const Key('supplier-money-opening-excluded'));
      await revealMoney(excluded);
      await tester.tap(excluded);
      await tester.pumpAndSettle();
      final submit = find.widgetWithText(FilledButton, 'Record payment');
      await revealMoney(submit);
      expect(
        tester.widget<FilledButton>(submit).onPressed,
        isNotNull,
        reason:
            'Scoped encrypted draft must be saved before submission is enabled.',
      );
      final callback = tester.widget<FilledButton>(submit).onPressed!;
      callback();
      callback(); // Two immediate callbacks must retain one attempt.
      await tester.pumpAndSettle();
      expect(work.workspaceSupplierLedger(supplierId)!.payableMinor, 0);
      expect(
        work
            .workspaceSupplierLedger(supplierId)!
