        expect(inbox, findsOneWidget);
        expect(
          find.byKey(const ValueKey('chat-inbox-all'), skipOffstage: false),
          findsOneWidget,
          reason: 'The approved navigation opens exactly one Chat destination.',
        );
        expect(
          GoRouterState.of(tester.element(inbox)).uri.path,
