        expect(tester.widget(taxAmounts), isA<Column>());
      }
      final values = switch (section) {
        'tax' => {
          'work-purchase-cgst': '30.30',
          'work-purchase-sgstAmount': '30.30',
        },
        'item' => {
          'work-purchase-hsn-0': '1006',
          'work-purchase-batch-0': 'EVAL-BATCH-1',
        },
        'receipt' => {'work-purchase-receivedDate': '30/09/2026'},
        _ => {
          'work-purchase-paidAmount': '100',
          'work-purchase-dueDate': '15/10/2026',
        },
      };
      for (final value in values.entries) {
        await revealPurchaseInput(tester, find.byKey(Key(value.key)));
        await tester.enterText(find.byKey(Key(value.key)), value.value);
      }
