      tester
          .widget<TextField>(
            find.byKey(const Key('work-purchase-invoiceTotal')),
          )
          .controller!
          .text,
      '600.60',
    );
    expect(tester.takeException(), isNull);
    await tester.pumpWidget(const SizedBox.shrink());
  });
  testWidgets(
    'P05-MATCH product cancel and Android Back retain the same bill',
    (tester) async {
      final entry = _PurchaseEntryFixtureStore();
      final work = manualPurchaseFixture(entry);
      final products = List.of(work.workspaceCatalogueItems);
      await mount(tester, route: '/app/work/workspace/dashboard', work: work);
      await openPurchaseList(tester);
      await tester.tap(
        await purchaseRegisterAction(tester, 'work-purchase-record'),
      );
      await tester.pumpAndSettle();
      await expandPurchasePrimarySections(tester);
      for (final e in {
        'supplier-name': 'Evaluation supplier',
        'reference': 'EVAL-MATCH-1',
        'item-0': 'Evaluation new rice',
        'pack-0': '1 kg',
        'quantity-0': '12',
        'cost-0': '45.50',
      }.entries) {
        final field = find.byKey(Key('work-purchase-${e.key}'));
        await revealPurchaseInput(tester, field);
        await tester.enterText(field, e.value);
      }
      for (final androidBack in [false, true]) {
        final add = find.byKey(const Key('work-purchase-add-product-0'));
        await revealPurchaseInput(tester, add, delta: -60);
        await tester.tap(add);
        await tester.pumpAndSettle();
        expect(find.byKey(const Key('work-product-stock')), findsNothing);
        expect(find.byKey(const Key('work-product-public')), findsNothing);
        expect(find.text('Product & prices'), findsOneWidget);
        expect(find.text('Product, price & stock'), findsNothing);
        expect(
          tester
              .widget<TextField>(find.byKey(const Key('work-product-title')))
              .controller!
              .text,
          'Evaluation new rice',
        );
        expect(
          tester
              .widget<TextField>(
                find.byKey(const Key('work-product-purchase-price')),
              )
              .controller!
              .text,
          isEmpty,
          reason:
              'Decimal bill cost must not be rounded into the product model.',
        );
        if (androidBack) {
          await tester.enterText(
            find.byKey(const Key('work-product-title')),
            'Unsaved editor change',
          );
          FocusManager.instance.primaryFocus?.unfocus();
          await tester.pumpAndSettle();
          await tester.binding.handlePopRoute();
          await tester.pumpAndSettle();
          expect(
            find.byKey(const Key('work-product-unsaved-dialog')),
            findsOneWidget,
          );
          await tester.tap(find.byKey(const Key('work-product-discard-edits')));
        } else {
          await reveal(tester, find.byKey(const Key('work-product-cancel')));
          await tester.tap(find.byKey(const Key('work-product-cancel')));
        }
        await tester.pumpAndSettle();
        expect(find.byKey(const Key('work-record-purchase')), findsOneWidget);
        for (final e in {
          'reference': 'EVAL-MATCH-1',
          'item-0': 'Evaluation new rice',
          'quantity-0': '12',
          'cost-0': '45.50',
        }.entries) {
          expect(
            tester
                .widget<TextField>(find.byKey(Key('work-purchase-${e.key}')))
                .controller!
                .text,
            e.value,
          );
        }
        expect(work.workspaceCatalogueItems, orderedEquals(products));
        expect(entry.value, isNull);
      }
      expect(tester.takeException(), isNull);
      await tester.pumpWidget(const SizedBox.shrink());
    },
  );

