      await tester.pumpAndSettle();
      await tester.enterText(
        find.byKey(const Key('work-product-title')),
        'Different Stock product title',
      );
      await reveal(
        tester,
        find.byKey(const Key('work-product-details-section')),
      );
      await tester.tap(find.byKey(const Key('work-product-details-section')));
      await tester.pumpAndSettle();
      for (final e in {
        'brand': 'Evaluation maker',
        'sku': 'EVAL-MATCH-RICE',
        'purchase-price': '45',
        'selling-price': '55',
      }.entries) {
        final field = find.byKey(Key('work-product-${e.key}'));
        await reveal(tester, field);
        await tester.enterText(field, e.value);
      }
      await reveal(tester, find.byKey(const Key('work-product-save')));
      expect(find.text('Save product & return'), findsOneWidget);
      await tester.tap(find.byKey(const Key('work-product-save')));
      await tester.pumpAndSettle();
      expect(find.byKey(const Key('work-record-purchase')), findsOneWidget);
      final product = work.workspaceCatalogueItems.singleWhere(
        (p) => p.sku == 'EVAL-MATCH-RICE',
      );
      expect(product.stock, 0);
      expect(product.available, isFalse);
      expect(product.publicListing, isFalse);
      final scope = work.workspaceSupplierScope!;
      final persisted = await inventory.read(scope.$1, scope.$2, qa: scope.$3);
      expect(persisted!.products.singleWhere((p) => p.id == product.id).toInventoryJson(),
        product.toInventoryJson(), reason: 'Return only after the exact zero-Stock product is saved.');
      expect(
        work.workspaceCatalogueItems.where((p) => p.id != product.id),
        orderedEquals(products),
      );
      expect(
        tester
            .widget<TextField>(
              find.byKey(const Key('work-purchase-quantity-0')),
            )
            .controller!
            .text,
        '12',
      );
      expect(
        tester
            .widget<TextField>(find.byKey(const Key('work-purchase-cost-0')))
            .controller!
            .text,
        '45.50',
      );
      expect(
        tester
            .widget<TextField>(find.byKey(const Key('work-purchase-item-0')))
            .controller!
            .text,
        'Evaluation new rice',
      );
      expect(
        find.byKey(const Key('work-purchase-add-product-0')),
        findsNothing,
      );
      await revealPurchaseInput(
        tester,
        find.byKey(const Key('work-purchase-draft-save')),
      );
      await tester.tap(find.byKey(const Key('work-purchase-draft-save')));
      await tester.pumpAndSettle();
      final draft = entry.value!.draft!;
      expect(draft.goods.single['productId'], product.id);
      expect(draft.goods.single['quantity'], '12');
      expect(draft.goods.single['cost'], '45.50');
      expect(work.workspaceFinance, same(finance));
      expect(work.workspacePurchases, isEmpty);
      await tester.tap(
        await purchaseRegisterAction(tester, 'work-purchase-record'),
      );
      await tester.pumpAndSettle();
      await expandPurchasePrimarySections(tester);
      expect(work.workspacePurchaseEntryDraft!.id, draft.id);
      expect(
        find.byKey(const Key('work-purchase-add-product-0')),
        findsNothing,
      );
      expect(tester.takeException(), isNull);
      await tester.pumpWidget(const SizedBox.shrink());
    },
  );

