  testWidgets(
    'P05-R11-C02 download saved copy cancels retries and rejects dirty or stale records',
    (tester) async {
      final entry = _PurchaseEntryFixtureStore();
      final work = manualPurchaseFixture(entry);
      final scope = work.workspaceSupplierScope!;
      final at = DateTime.utc(2026, 9, 30);
      final profile = WorkspaceSupplierProfile(
        id: 'export-supplier',
        name: 'Host export supplier',
        createdAt: at,
        updatedAt: at,
      );
      final draft = WorkspacePurchaseEntryDraft(
        id: 'export-draft',
        supplierId: profile.id,
        invoiceReference: 'HOST-EXPORT-1',
        invoiceDate: '30/09/2026',
        createdAt: at,
        updatedAt: at,
        goods: [
          {
            'name': 'Host-only oil',
            'pack': '1 L',
            'quantity': '12',
            'cost': '230',
            'productId': '',
          },
        ],
        details: {'invoiceTotal': '2840', 'paymentStatus': 'On credit'},
      );
      entry.value = WorkspacePurchaseEntryBook(
        account: scope.$1,
        store: scope.$2,
        qa: scope.$3,
        revision: 1,
        profiles: [profile],
        draft: draft,
      );
      final picker = _PurchaseOriginalSaveFixture();
      final previous = FilePickerPlatform.instance;
      FilePickerPlatform.instance = picker;
      addTearDown(() => FilePickerPlatform.instance = previous);
      await mount(tester, route: '/app/work/workspace/dashboard', work: work);
      await openPurchaseList(tester);
      await tester.tap(
        await purchaseRegisterAction(tester, 'work-purchase-record'),
      );
      await tester.pumpAndSettle();
      await usePurchaseControl(tester, 'work-purchase-preview');
      final saved = work.workspacePurchaseEntryDraft;
      Future<void> download() async {
        await revealPurchaseInput(
          tester,
          find.byKey(const Key('purchase-recorded-download')),
        );
        await tester.runAsync(() async {
          await tester.tap(find.byKey(const Key('purchase-recorded-download')));
          for (var i = 0; i < 40 && picker.bytes == null; i++) {
            await Future<void>.delayed(const Duration(milliseconds: 25));
          }
        });
        await tester.pumpAndSettle();
      }

      await download();
      expect(picker.name, startsWith('purchase-recorded-'));
      expect(picker.mime, 'application/pdf');
      expect(ascii.decode(picker.bytes!.take(4).toList()), '%PDF');
      expect(
        find.text('Download cancelled. Your saved draft is kept.'),
        findsOneWidget,
      );
      expect(work.workspacePurchaseEntryDraft, same(saved));
      expect(work.workspacePurchases, isEmpty);
      picker.bytes = null;
      picker.holdSave = Completer<Uri?>();
      final beforeDoubleTap = picker.calls;
      await download();
      await tester.tap(find.byKey(const Key('purchase-recorded-download')));
      await tester.pumpAndSettle();
      expect(picker.calls, beforeDoubleTap + 1);
      picker.holdSave!.complete(null);
      picker.holdSave = null;
      await tester.pumpAndSettle();
      picker.bytes = null;
      picker.fail = true;
      await download();
      expect(
        find.text(
          'Could not download the recorded copy. Your saved draft is kept; retry.',
        ),
        findsOneWidget,
      );
      picker.bytes = null;
      picker.fail = false;
      picker.result = Uri.file('/host-only/export.pdf');
      await download();
      expect(find.text('Recorded copy saved.'), findsOneWidget);
      await usePurchaseControl(tester, 'work-purchase-invoice-section');
      await revealPurchaseInput(
        tester,
        find.byKey(const Key('work-purchase-reference')),
      );
      await tester.enterText(
        find.byKey(const Key('work-purchase-reference')),
        'UNSAVED-CHANGE',
      );
      await usePurchaseControl(tester, 'work-purchase-preview');
      picker.bytes = null;
      await revealPurchaseInput(
        tester,
        find.byKey(const Key('purchase-recorded-download')),
      );
      await tester.tap(find.byKey(const Key('purchase-recorded-download')));
      await tester.pumpAndSettle();
      expect(picker.bytes, isNull);
      expect(
        find.text(
          'Save draft, then reopen it to download the saved copy. Your entries are kept.',
        ),
        findsOneWidget,
      );
      await revealPurchaseInput(
        tester,
        find.byKey(const Key('work-purchase-reference')),
      );
      await tester.enterText(
        find.byKey(const Key('work-purchase-reference')),
        draft.invoiceReference,
      );
      entry.value = WorkspacePurchaseEntryBook(
        account: scope.$1,
        store: scope.$2,
        qa: scope.$3,
        revision: 2,
        profiles: [profile],
        draft: draft,
      );
      await work.loadWorkspaceSuppliers(retry: true);
      await revealPurchaseInput(
        tester,
        find.byKey(const Key('purchase-recorded-download')),
      );
      await tester.tap(find.byKey(const Key('purchase-recorded-download')));
      await tester.pumpAndSettle();
      expect(picker.bytes, isNull);
      expect(
        find.text(
          'Saved details changed or are unavailable. Reopen this purchase draft and retry.',
        ),
        findsOneWidget,
      );
      final originalStore = work.activeWorkspace!;
      work.activateWorkspace(
        WorkWorkspace(
          id: 'HOST-OTHER-STORE',
          name: 'Host other Store',
          profileId: originalStore.profileId,
          profileLabel: originalStore.profileLabel,
          area: originalStore.area,
          verified: true,
        ),
      );
      await tester.pumpAndSettle();
      expect(picker.bytes, isNull);
      expect(find.byKey(const Key('purchase-recorded-download')), findsNothing);
      expect(work.workspacePurchases, isEmpty);
      expect(tester.takeException(), isNull);
      await tester.pumpWidget(const SizedBox.shrink());
    },
  );

