          findsOneWidget,
        );
        expect(find.text('Invoice total'), findsOneWidget);
        expect(find.text('₹1,23,456.78'), findsOneWidget);
        expect(find.text('Not entered'), findsNothing);
        final paperRect = tester.getRect(
          find.byKey(const Key('purchase-review-paper')),
        );
        expect(
          paperRect.width,
          lessThanOrEqualTo(config.$1.width),
          reason:
              'The recorded phone copy must not start half offscreen. Only its item columns scroll sideways.',
        );
        final headerRect = tester.getRect(
          find.byKey(const Key('purchase-review-paper-header')),
        );
        if (config.$2 == 1) {
          expect(
            headerRect.height,
            lessThan(190),
            reason:
                'Sparse supplier details must not stretch beside taller invoice metadata.',
          );
        }
        for (final id in ['supplier-Supplier name', 'reference', 'date']) {
          final fact = tester.getRect(
            find.byKey(ValueKey('purchase-review-$id')),
          );
          expect(fact.left, greaterThanOrEqualTo(paperRect.left));
          expect(fact.right, lessThanOrEqualTo(paperRect.right));
        }
        expect(
          find.byKey(const Key('purchase-review-item-space')),
          findsNothing,
          reason: 'Phone reading must not reserve blank A4-height filler.',
        );
        expect(
          find.byKey(const Key('purchase-review-item-scroll')),
          findsOneWidget,
        );
        expect(find.text('Pinch to zoom · drag to read'), findsNothing);
        expect(find.text('Item amounts not entered'), findsNothing);
        expect(find.text('Enter item amounts'), findsOneWidget);
        if (config.$2 == 1) {
          expect(
            tester
                .getSize(find.byKey(const Key('purchase-review-toolbar')))
                .height,
            48,
            reason:
                'The recorded-copy controls use one compact accessible lane.',
          );
          await revealPurchaseInput(
            tester,
            find.byKey(const Key('purchase-review-item-scroll')),
          );
          final supplierBeforeDrag = tester.getRect(
            find.byKey(
              const ValueKey('purchase-review-supplier-Supplier name'),
            ),
          );
          await tester.drag(
            find.byKey(const Key('purchase-review-item-scroll')),
            const Offset(-500, 0),
          );
          await tester.pumpAndSettle();
          final itemScroll = tester.widget<SingleChildScrollView>(
            find.byKey(const Key('purchase-review-item-scroll')),
          );
          expect(itemScroll.controller!.offset, greaterThan(0));
          expect(
            tester.getRect(
              find.byKey(
                const ValueKey('purchase-review-supplier-Supplier name'),
              ),
            ),
            supplierBeforeDrag,
            reason:
                'Sideways item-table reading must not move or clip the supplier header.',
          );
        }
        await revealPurchaseInput(
          tester,
          find.byKey(const Key('work-purchase-draft-save')),
        );
        expect(
          find.byKey(const Key('work-purchase-draft-save')).hitTestable(),
          findsOneWidget,
        );
        expect(entry.value, same(saved));
        expect(work.workspacePurchases, isEmpty);
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
      },
    );
  }

