  for (final enteredItems in [false, true]) {
    testWidgets(
      'P05-R15-C01 automated scan retains extras before acceptance and protects edits $enteredItems',
      (tester) async {
        final bytes = (await tester.runAsync(_catalogueTestPhoto))!;
        final capture = _PurchaseScanReviewFixture(bytes);
        final entry = _PurchaseEntryFixtureStore();
        final work = storeViewFixture(
          null,
          _ContactDraftFixtureStore(),
          null,
          null,
          null,
          null,
          null,
          null,
          null,
          entry,
          capture,
        );
        final scope = work.workspaceSupplierScope!;
        final at = DateTime.utc(2026, 9, 30);
        final digest = 'c' * 64;
        entry.value = WorkspacePurchaseEntryBook(
          account: scope.$1,
          store: scope.$2,
          qa: scope.$3,
          revision: 1,
          profiles: [
            WorkspaceSupplierProfile(
              id: 'supplier-fixture',
              name: 'Entered supplier',
              createdAt: at,
              updatedAt: at,
            ),
          ],
          draft: WorkspacePurchaseEntryDraft(
            id: 'draft-fixture',
            supplierId: 'supplier-fixture',
            invoiceReference: 'MANUAL-KEPT',
            invoiceDate: '',
            createdAt: at,
            updatedAt: at,
            goods: [
              enteredItems
                  ? {
                      'productId': '',
                      'name': 'Entered item',
                      'pack': '1 kg',
                      'quantity': '2',
                      'cost': '50',
                    }
                  : {
                      'productId': '',
                      'name': '',
                      'pack': '',
                      'quantity': '',
                      'cost': '',
                    },
            ],
            attachments: [
              WorkspacePurchaseInvoiceAttachment(
                owner: jsonEncode([
                  scope.$1,
                  scope.$2,
                  scope.$3,
                  'draft-fixture',
                ]),
                digest: digest,
                fileName: 'Automated scan-review fixture.png',
                contentType: 'image/png',
                byteLength: bytes.length,
                source: 'upload',
              ),
            ],
          ),
        );
        await mount(tester, route: '/app/work/workspace/dashboard', work: work);
        await openPurchaseList(tester);
        await tester.tap(
          await purchaseRegisterAction(tester, 'work-purchase-record'),
        );
        await tester.pumpAndSettle();
        Future<void> tap(String key) async {
          await usePurchaseControl(tester, key);
        }

        await tap('work-purchase-document-$digest');
        await tap('work-purchase-read-$digest');
        final extra = find.byWidgetPredicate(
          (w) => w is TextField && w.decoration?.labelText == 'Value as printed',
        );
        expect(
          extra,
          findsNWidgets(2),
          reason:
              'Invoice and unassigned item extras appear immediately, before acceptance.',
        );
        expect(
          find.textContaining(
            'Check the bill details, then tap Fill blank fields.',
          ),
          findsOneWidget,
        );
        expect(
          tester.widget<TextField>(extra.first).controller!.text,
          'Two years',
        );
        expect(
          tester
              .widget<TextField>(
                find.byKey(const Key('work-purchase-reference')),
              )
              .controller!
              .text,
          'MANUAL-KEPT',
        );
        await revealPurchaseInput(tester, extra.first);
        await tester.enterText(extra.first, 'Retailer correction');
        await tap('work-purchase-read-$digest');
        expect(
          extra,
          findsNWidgets(2),
          reason: 'Repeated reading must not create duplicate extras.',
        );
        expect(
          tester.widget<TextField>(extra.first).controller!.text,
          'Retailer correction',
        );
        await tap('work-purchase-use-$digest');
        expect(
          find.textContaining(
            enteredItems
                ? 'Your item rows were kept'
                : 'Match scanned items to Stock',
          ),
          findsOneWidget,
        );
        expect(
          tester
              .widget<TextField>(find.byKey(const Key('work-purchase-item-0')))
              .controller!
              .text,
          enteredItems ? 'Entered item' : 'Detected item',
        );
        expect(
          extra,
          findsNWidgets(2),
          reason: 'All captured extras stay editable regardless of matching.',
        );
        final match = find.byWidgetPredicate(
          (w) => w is DropdownButtonFormField<int>,
        );
        expect(
          match,
          enteredItems ? findsOneWidget : findsNothing,
          reason:
              'Only accepting new candidate rows proves a detected item-index match.',
        );
        if (enteredItems) {
          await revealPurchaseInput(tester, match);
          await tester.tap(match);
          await tester.pumpAndSettle();
          await tester.tap(find.text('Item 1 · Entered item').last);
          await tester.pumpAndSettle();
          expect(
            match,
            findsNothing,
            reason:
                'Explicit retailer choice moves the extra into the correct item.',
          );
        }
        capture.fail = true;
        await tap('work-purchase-read-$digest');
        expect(
          find.byKey(const Key('work-purchase-entry-error')),
          findsOneWidget,
        );
        expect(
          tester.widget<TextField>(extra.first).controller!.text,
          'Retailer correction',
        );
        expect(
          entry.value!.draft!.additionalFields,
          isEmpty,
          reason: 'Reading/review alone does not save or post.',
        );
        await tap('work-purchase-draft-save');
        expect(
          entry.value!.draft!.additionalFields.map(
            (f) => (f.value, f.itemIndex, f.sourceItemIndex),
          ),
          containsAll([('Retailer correction', null, null), ('SUP-01', 0, 0)]),
        );
        // Saving returns to the register. Reopen that saved draft before
        // testing a removal; do not tap a control on the retired editor.
        final removedId = entry.value!.draft!.additionalFields.first.id;
        await tester.tap(await purchaseRegisterAction(tester, 'work-purchase-record')); await tester.pumpAndSettle();
        await tap('work-purchase-document-$digest');
        capture.fail = false;
        await tap('work-purchase-read-$digest');
        final removePrinted = find.byKey(Key('purchase-extra-remove-$removedId'));
        await revealPurchaseInput(tester, removePrinted, delta: -80);
        await tester.tap(removePrinted); await tester.pumpAndSettle();
        capture.fail = false;
        await tap('work-purchase-read-$digest');
        expect(extra, findsOneWidget, reason: 'An explicitly removed invoice field must not return on rescan.');
        await tap('work-purchase-draft-save');
        expect(entry.value!.draft!.additionalFields, hasLength(1));
        expect(entry.value!.draft!.attachments.single.dismissedFieldIds, isNotEmpty);
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
      },
    );
  }

