  Future<void> captureStoreView(
    WidgetTester tester,
    String name, {
    Rect? requiredInkRect,
    void Function(List<bool>)? onCapturedInk,
  }) async {
    if (!captureStoreViewV2) return;
    const folder = String.fromEnvironment(
      'MOOL_STORE_VIEW_CAPTURE_DIR',
      defaultValue: 'store-dashboard-first-tap-local-review-20260905',
    );
    final root = find.byKey(const Key('store-review-root'));
    final matcher = matchesGoldenFile(
      '../../../../MOOLSOCIAL-POST-UI-AUDIT-20260905/$folder/$name.png',
    );
    if (requiredInkRect == null) {
      await _expectGoldenOrTechnical(
        tester,
        root,
        '$name.png',
        '../../../../MOOLSOCIAL-POST-UI-AUDIT-20260905/$folder/$name.png',
      );
      return;
    }
    // Inspect the same unmodified raster that is saved as evidence, not merely
    // the title's widget geometry. Do not force app repaint to hide a failure.
    final technicalPlan = _TechnicalCapturePlan.fromEnvironment();
    if (technicalPlan?.currentMode == true) {
      _captureMediaSettings(
        tester.element(root),
        find.byKey(_technicalCaptureAppRootKey, skipOffstage: false),
      );
    }
    final boundary = tester.renderObject<RenderRepaintBoundary>(root);
    final image = (await tester.runAsync(() => boundary.toImage()))!;
    try {
      await _dispatchTechnicalCapture(
        technicalPlan,
        originalReference: '$name.png',
        historical: () => expectLater(image, matcher),
        technical: (plan) async {
          await _recordTechnicalTarget(
            tester,
            root,
            plan,
            '$name.png',
            suppliedImage: image,
            mediaSettingsRoot: plan.currentMode
                ? find.byKey(_technicalCaptureAppRootKey, skipOffstage: false)
                : null,
          );
        },
      );
      final pixels = (await tester.runAsync(
        () => image.toByteData(format: ui.ImageByteFormat.rawRgba),
      ))!;
      expect(requiredInkRect.left, greaterThanOrEqualTo(0));
      expect(requiredInkRect.top, greaterThanOrEqualTo(0));
      expect(requiredInkRect.right, lessThanOrEqualTo(image.width));
      expect(requiredInkRect.bottom, lessThanOrEqualTo(image.height));
      var inkPixels = 0;
      var trailingInkPixels = 0;
      final inkMask = <bool>[];
      for (
        var y = requiredInkRect.top.ceil();
        y < requiredInkRect.bottom.floor();
        y++
      ) {
        for (
          var x = requiredInkRect.left.ceil();
          x < requiredInkRect.right.floor();
          x++
        ) {
          final offset = (y * image.width + x) * 4;
          // Counter Sale uses white title glyphs on its dark gradient.
          final isInk =
              pixels.getUint8(offset) > 200 &&
              pixels.getUint8(offset + 1) > 200 &&
              pixels.getUint8(offset + 2) > 200 &&
              pixels.getUint8(offset + 3) > 200;
          inkMask.add(isInk);
          if (isInk) {
            inkPixels++;
            if (x > requiredInkRect.left + requiredInkRect.width * 2 / 3) {
              trailingInkPixels++;
            }
          }
        }
      }
      expect(
        inkPixels,
        greaterThan(100),
        reason: 'The saved $name raster must visibly paint its header title.',
      );
      expect(
        trailingInkPixels,
        greaterThan(30),
        reason: 'The final word of the header must appear in $name.',
      );
      onCapturedInk?.call(inkMask);
    } finally {
      image.dispose();
    }
  }

  WorkSession collectionStore(
    _CollectionFixtureGateway gateway, {
    bool readinessAvailable = true,
  }) {
    final work = storeViewFixture();
    final original = work.currentWorkspaceOrder!;
    work.workspaceOrders[0] = WorkspaceOrderRecord(
      id: original.id,
      customer: original.customer,
      items: original.items,
      quantities: original.quantities,
      amount: original.amount,
      source: 'App',
      fulfilment: 'Collect at store',
      payment: 'Paid online',
      address: '',
      stage: 'Ready for collection',
      needsDelivery: false,
      createdAt: DateTime(2026, 8, 1),
      collectionStoreId: work.activeWorkspace!.id,
    );
    gateway.storeId = work.activeWorkspace!.id;
    work.attachCollection(
      StoreCollectionController(
        storeId: gateway.storeId,
        orderId: original.id,
        gateway: gateway,
        readinessGateway: readinessAvailable ? gateway : null,
      ),
    );
    return work;
  }

  Future<void> openSaleCustomer(WidgetTester tester) async {
    // New sales already start on the approved central customer step.
    // Existing drafts expose the same fields through Customer details.
    if (find.byKey(const Key('work-order-customer')).evaluate().isEmpty) {
      final edit = find.byKey(const Key('work-sale-customer'));
      await reveal(tester, edit);
      await tester.tap(edit);
      await tester.pumpAndSettle();
    }
    expect(find.byKey(const Key('work-order-customer')), findsOneWidget);
  }

  Future<void> enterSaleCustomer(
    WidgetTester tester,
    String phone, {
    String? name,
  }) async {
    if (find.byKey(const Key('work-order-customer')).evaluate().isEmpty) {
      await openSaleCustomer(tester);
      await tester.pumpAndSettle();
    }
    await tester.enterText(find.byKey(const Key('work-order-customer')), phone);
    await tester.testTextInput.receiveAction(TextInputAction.done);
    await tester.pumpAndSettle();
    if (name != null) {
      final nameField = find.byKey(const Key('work-sale-customer-name'));
      await reveal(tester, nameField);
      await tester.enterText(nameField, name);
      await tester.testTextInput.receiveAction(TextInputAction.done);
      await tester.pumpAndSettle();
    }
    await reveal(tester, find.byKey(const Key('work-sale-customer-confirm')));
    if (find
        .byKey(const Key('work-sale-customer-confirm'))
        .hitTestable()
        .evaluate()
        .isEmpty) {
      await captureStoreView(tester, 'pos-customer-confirm-unreachable');
    }
    expect(
      find.byKey(const Key('work-sale-customer-confirm')).hitTestable(),
      findsOneWidget,
    );
    await tester.tap(find.byKey(const Key('work-sale-customer-confirm')));
    await tester.pumpAndSettle();
  }

