            }
            await tester.pump(const Duration(seconds: 31));
            await tester.pumpAndSettle();
            expect(work.activeWorkspace, isNull);
            expect(work.reviewCaseId, caseId);
            expect(
              find.byKey(const Key('work-inline-review-status')),
