  String csv23(List<Map<String, String>> rows) {
    final headers = WorkspaceProductImport.templateLabels.keys;
    String cell(String value) => '"${value.replaceAll('"', '""')}"';
    return '${WorkspaceProductImport.csvTemplate}${rows.map((r) => headers.map((h) => cell(r[h] ?? '')).join(',')).join('\r\n')}\r\n';
  }

  const csv23Required = {
    'title': 'Rice',
    'brand': 'Local',
    'pack': '1 kg',
    'purchasePrice': '40',
    'sellingPrice': '50',
    'stock': '10',
  };
  const csv23MappedPackFields = ['genericName', 'netQuantity', 'manufacturerName',
    'packerName', 'importerName', 'countryOfOrigin', 'fssaiLicenseNumber', 'consumerCare'];

  test(
    'CSV23 eight pack fields reach shared snapshot and public adapter',
    () async {
      final facts = {
        for (final key in csv23MappedPackFields)
          key: mappedPack.toJson()[key]! as String,
        'consumerCare': 'Product care,\nMon–Sat',
      };
      final parsed = WorkspaceProductImport.parse(
        csv23([
          {...csv23Required, ...facts, 'variant': 'Long grain'},
        ]),
        catalogue: const [],
        owned: const [],
      ).rows.single.product!;
      expect(parsed.variant, 'Long grain');
      expect(parsed.compliance!.manufacturedOrPackedOn, isNull);
      expect(parsed.compliance!.bestBeforeOrUseBy, isNull);
      expect(parsed.catalogueFactsRequireReview, isTrue);
      expect(parsed.copyWith(publicListing: true).published, isFalse);
      for (final field in facts.entries) {
        expect(parsed.compliance!.toJson()[field.key], field.value);
      }
      final gateway = ReviewWorkGateway();
      final work = WorkSession(gateway: gateway)..seedVerifiedWorkspace();
      addTearDown(work.dispose);
      work.importWorkspaceProducts([parsed]);
      final saved = work.workspaceCatalogueItems.singleWhere(
        (p) => p.id == parsed.id,
      );
      final snapshot =
          (gateway.lastOperationalSnapshot!.state['catalogue'] as List)
              .cast<Map>()
              .singleWhere((r) => r['id'] == parsed.id);
      final restoredFacts = WorkspaceProductCompliance.fromJson(
        jsonDecode(jsonEncode(snapshot['compliance'])),
      )!;
      expect(restoredFacts.toJson(), saved.compliance!.toJson());
      final public = saved.toBuyPublicProduct(storeName: 'Store');
      final c = public.compliance!;
      expect(
        [
          c.genericName,
          c.netQuantity,
          c.manufacturerName,
          c.packerName,
          c.importerName,
          c.countryOfOrigin,
          c.fssaiLicenseNumber,
          c.consumerCare,
        ],
        csv23MappedPackFields
            .map((k) => facts[k])
            .toList(),
      );
      expect(public.variant, 'Long grain');
      expect(public.pack, '1 kg');
      expect(public.catalogueListing, isFalse);
      await Future<void>.delayed(Duration.zero);
    },
  );

  test(
    'CSV23 blank exact-match facts preserve values and changes hold review',
    () {
      final master = workspaceMasterCatalogue.first.copyWith(
        compliance: mappedPack,
        cataloguePhoto: photoFixture(),
      );
      final row = {
        ...csv23Required,
        'title': master.title,
        'brand': master.brand,
        'pack': master.pack,
        'variant': master.variant,
        'barcode': master.barcode,
      };
      WorkspaceCatalogueItem read(Map<String, String> r) =>
          WorkspaceProductImport.parse(
            csv23([r]),
            catalogue: [master],
            owned: const [],
          ).rows.single.product!;
      final blank = read(row);
      expect(blank.cataloguePhoto, master.cataloguePhoto);
      expect(
        blank.catalogueFactsRequireReview,
        master.catalogueFactsRequireReview,
      );
      expect(blank.compliance!.manufacturedOrPackedOn, isNull);
      expect(blank.compliance!.bestBeforeOrUseBy, isNull);
      for (final key in WorkspaceProductImport.packFieldLabels.keys) {
        final expected = mappedPack.toJson()[key];
        expect(blank.compliance!.toJson()[key], expected);
        // Added optional fields are absent, not the literal text "null".
        final same = read({...row, key: expected == null ? '  ' : '  $expected  '});
        expect(same.compliance!.toJson()[key], expected);
        expect(
          same.catalogueFactsRequireReview,
          master.catalogueFactsRequireReview,
        );
        final changed = read({...row, key: 'Corrected pack fact'});
        expect(changed.compliance!.toJson()[key], 'Corrected pack fact');
        expect(changed.catalogueFactsRequireReview, isTrue);
        expect(changed.copyWith(publicListing: true).published, isFalse);
      }
    },
  );

  test(
    'CSV25 exact-match public facts distinguish unchanged and corrected values',
    () {
      final master = workspaceMasterCatalogue.first.copyWith(
        origin: 'India',
        composition: 'Sunflower oil',
        regulatoryNote: 'Store in a cool, dry place',
        catalogueFactsRequireReview: false,
      );
      final facts = {
        'categoryId': master.categoryId,
        'origin': master.origin,
        'composition': master.composition!,
        'regulatoryNote': master.regulatoryNote!,
        'visualLabel': master.visualLabel,
      };
      final row = {
        ...csv23Required,
        'title': master.title,
        'brand': master.brand,
        'pack': master.pack,
        'variant': master.variant,
        'barcode': master.barcode,
      };
      WorkspaceCatalogueItem read(
        Map<String, String> input, {
        bool held = false,
      }) {
        // visualLabel remains a legacy accepted column, not a template input.
        final headers = [
          ...WorkspaceProductImport.templateLabels.keys,
          'visualLabel',
        ];
        String cell(String value) => '"${value.replaceAll('"', '""')}"';
        final csv =
            '${headers.join(',')}\r\n'
            '${headers.map((h) => cell(input[h] ?? '')).join(',')}\r\n';
        return WorkspaceProductImport.parse(
          csv,
          catalogue: [master.copyWith(catalogueFactsRequireReview: held)],
          owned: const [],
        ).rows.single.product!;
      }

      Map<String, String?> publicFacts(WorkspaceCatalogueItem product) {
        final public = product.toBuyPublicProduct(storeName: 'Store');
        expect(public.title, master.title);
        expect(public.brand, master.brand);
        expect(public.variant, master.variant);
        expect(public.pack, master.pack);
        expect(public.catalogueListing, isFalse);
        return {
          'categoryId': public.categoryId,
          'origin': public.origin,
          'composition': public.composition,
          'regulatoryNote': public.regulatoryNote,
          'visualLabel': public.visualLabel,
        };
      }

      expect(publicFacts(read(row)), facts);
      for (final fact in facts.entries) {
        final unchanged = {...row, fact.key: '  ${fact.value}  '};
        expect(read(unchanged).catalogueFactsRequireReview, isFalse);
        expect(publicFacts(read(unchanged)), facts);
        expect(read(unchanged, held: true).catalogueFactsRequireReview, isTrue);
        final corrected = read({...row, fact.key: 'Corrected ${fact.key}'});
        expect(corrected.catalogueFactsRequireReview, isTrue);
        expect(corrected.copyWith(publicListing: true).published, isFalse);
        expect(publicFacts(corrected)[fact.key], 'Corrected ${fact.key}');
      }
    },
  );

  test('CSV25 minimum order preserves exact SKU rule or explicit override', () {
    final master = workspaceMasterCatalogue.first.copyWith(minimumOrder: 12);
    final row = {
      ...csv23Required,
      'title': master.title,
      'brand': master.brand,
      'pack': master.pack,
      'variant': master.variant,
    };
    for (final override in [null, '', '6']) {
      final product = WorkspaceProductImport.parse(
        csv23([
          {...row, 'minimumOrder': ?override},
        ]),
        catalogue: [master],
        owned: const [],
      ).rows.single.product!;
      final expected = override == '6' ? 6 : 12;
      expect(product.minimumOrder, expected);
      expect(
        product.toBuyPublicProduct(storeName: 'Store').minimumOrder,
        expected,
      );
      expect(product.publicListing, isFalse);
    }
    final unmatched = WorkspaceProductImport.parse(
      csv23([csv23Required]),
      catalogue: const [],
      owned: const [],
    ).rows.single.product!;
    expect(unmatched.minimumOrder, 1);
    final invalid = WorkspaceProductImport.parse(
      csv23([
        {...row, 'minimumOrder': '0'},
      ]),
      catalogue: [master],
      owned: const [],
    ).rows.single;
    expect(invalid.product, isNull);
    expect(invalid.issueValues, {'minimumOrder': '0'});
  });

  test('CSV23 exact variants remain separate across 1000 SKU rows', () {
    final rows = List.generate(
