        'manufacturerName': 'Local maker',
        'description': 'First line\nSecond, quoted line',
        'specifications': 'Storage: Dry',
      };
      String record(Map<String, String> row) => raw.keys
          .map((key) => '"${(row[key] ?? '').replaceAll('"', '""')}"')
          .join(',');
      final tea = {
        ...raw,
        'title': 'Tea',
        'stock': '7',
        'sku': 'TEA001',
        'barcode': '0001234562',
      };
