      expect(initialRect.height, greaterThanOrEqualTo(48));
      await captureStoreView(tester, 'catalogue-photo-loading-FIXTURE-360');
      client.pending!.complete(client.bytes);
      client.pending = null;
      bool decoded() => tester
          .widgetList<RawImage>(find.byType(RawImage))
