      );
      const failedSource = 'https://example.invalid/catalogue/failure/oil.png';
      client.failures.add(Uri.parse(failedSource));
      update(() {
        product = product.copyWith(
          cataloguePhoto: photoFixture(
            revision: 'failure',
            source: failedSource,
          ),
