      now.year,
      now.month,
      now.day,
      now.timeZoneOffset.isNegative ? 23 : 1,
    );
    final stored = local.toUtc();
    final date =
        '${local.day.toString().padLeft(2, '0')}/${local.month.toString().padLeft(2, '0')}/${local.year}';
    work.workspaceInvoices
      ..clear()
      ..add(
        WorkspaceCustomerInvoice(
          id: 'LOCAL-DATE',
          orderId: 'LOCAL-DATE-ORDER',
          customer: 'Timezone customer',
          items: 'Saved item',
          amount: 56,
          payment: 'Cash',
          issuedAt: stored,
        ),
      );
    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      viewport: const Size(412, 915),
    );
    await openRecordedSales(tester);
    await tester.pumpAndSettle();
    final row = find.byKey(const ValueKey('work-sales-invoice-LOCAL-DATE'));
    expect(
      find.descendant(
        of: row,
        matching: find.text(
          '${local.day.toString().padLeft(2, '0')}/${local.month.toString().padLeft(2, '0')}/${local.year}',
        ),
      ),
      findsOneWidget,
    );
    await tester.tap(row);
    await tester.pumpAndSettle();
    final invoiceDetails = find.byKey(const Key('work-invoice-details'));
    expect(find.text('Invoice No.: LOCAL-DATE'), findsOneWidget);
    expect(find.text('Invoice date: $date'), findsOneWidget);
    expect(
      tester.getRect(find.text('Invoice No.: LOCAL-DATE')).top,
      lessThan(tester.getRect(invoiceDetails).top),
    );
    await reveal(tester, invoiceDetails);
    await tester.tap(
      find.descendant(of: invoiceDetails, matching: find.text('Bill details')),
    );
    await tester.pumpAndSettle();
    expect(find.text('Invoice date: $date'), findsOneWidget);
    expect(work.workspaceInvoices.single.issuedAt, stored);
    expect(work.workspaceInvoices.single.issuedAt.isUtc, isTrue);
    expect(tester.takeException(), isNull);
  });

