  testWidgets('SALESHOME draft label dates and newest-first', (tester) async {
    final work = storeViewFixture(null, _ContactDraftFixtureStore());
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    work.workspaceInvoices.clear();
    for (final entry in [('OLD', today), ('NEW', now)]) {
      work.workspaceInvoices.add(
        WorkspaceCustomerInvoice(
          id: entry.$1,
          orderId: entry.$1,
          customer: 'Test',
          items: 'Goods',
          amount: 100,
          payment: 'Cash',
          issuedAt: entry.$2,
        ),
      );
    }
    work.workspaceOrderSource = 'Counter';
    work.workspaceOrderFulfilment = 'At the shop';
    work.workspaceOrderCustomer = 'Saved customer';
    work.currentWorkspaceOrderId = null;
    await mount(tester, route: '/app/work/workspace/dashboard', work: work);
    await openRecordedSales(tester);
    await tester.pumpAndSettle();
    expect(
      tester
          .getTopLeft(find.byKey(const ValueKey('work-sales-invoice-NEW')))
          .dy,
      lessThan(
        tester
            .getTopLeft(find.byKey(const ValueKey('work-sales-invoice-OLD')))
            .dy,
      ),
    );
    final primary = find.byKey(const Key('work-sales-primary-counter-sale'));
    expect(primary, findsOneWidget);
    expect(find.byKey(const Key('work-sales-home')), findsOneWidget);
    expect(work.workspaceOrderCustomer, 'Saved customer');
    expect(work.currentWorkspaceOrderId, isNull);
    await tester.tap(find.byKey(const Key('work-statement-period')));
    await tester.pumpAndSettle();
    await tester.tap(
      find.widgetWithText(PopupMenuItem<String>, 'Custom range'),
    );
    await tester.pumpAndSettle();
    final range = DateTimeRange(
      start: today.subtract(const Duration(days: 2)),
      end: today,
    );
    final dialog = find.byType(DateRangePickerDialog);
    final datePicker = tester.widget<DateRangePickerDialog>(dialog);
    expect(datePicker.helpText, 'Dates · DD/MM/YYYY');
    expect(datePicker.fieldStartLabelText, 'From');
    expect(datePicker.fieldEndLabelText, 'To');
    expect(datePicker.fieldStartHintText, '');
    expect(datePicker.fieldEndHintText, '');
    final delegate = tester
        .widget<DateRangePickerDialog>(dialog)
        .calendarDelegate;
    final localizations = MaterialLocalizations.of(tester.element(dialog));
    expect(delegate.dateHelpText(localizations), 'DD/MM/YYYY');
    expect(
      delegate.parseCompactDate('13/09/2026', localizations),
      DateTime(2026, 9, 13),
    );
    expect(
      delegate.parseCompactDate('29/02/2024', localizations),
      DateTime(2024, 2, 29),
    );
    for (final invalid in [
      '31/02/2026',
      '09/13/2026',
      '00/09/2026',
      '01/01/0000',
    ]) {
      expect(delegate.parseCompactDate(invalid, localizations), isNull);
    }
    await tester.tap(find.byTooltip('Switch to input'));
    await tester.pumpAndSettle();
    final inputs = find.descendant(
      of: dialog,
      matching: find.byType(TextField),
    );
    expect(inputs, findsNWidgets(2));
    await tester.enterText(
      inputs.first,
      delegate.formatCompactDate(range.start, localizations),
    );
    await tester.enterText(
      inputs.last,
      delegate.formatCompactDate(range.end, localizations),
    );
    tester.testTextInput.hide();
    FocusManager.instance.primaryFocus?.unfocus();
    await tester.tap(find.widgetWithText(TextButton, 'OK'));
    await tester.pumpAndSettle();
    String date(DateTime d) =>
        '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}';
    expect(
      find.text('${date(range.start)} – ${date(range.end)}'),
      findsOneWidget,
    );
    expect(work.workspaceInvoices, hasLength(2));
    expect(tester.takeException(), isNull);
  });

  testWidgets('SALESHOME payment identity and unavailable guard', (
    tester,
  ) async {
    final contactStore = _ContactDraftFixtureStore();
    final work = storeViewFixture(null, contactStore);
    final seed = StoreReviewSeed(
      accountScope: 'review-draft-account',
      orderCount: 0,
      now: DateTime.now(),
    );
    work.activeWorkspace = seed.workspace;
    final saved = DateTime.now().subtract(const Duration(seconds: 1));
    work.workspaceInvoices.clear();
    final states = [
      WorkspacePaymentState.paid,
      WorkspacePaymentState.partPaid,
      WorkspacePaymentState.unpaid,
    ];
    for (final state in states) {
      work.workspaceInvoices.add(
        WorkspaceCustomerInvoice(
          id: state.name,
          orderId: state.name,
          customer: 'Customer',
          items: 'Goods',
          amount: 100,
          payment: 'Cash',
          issuedAt: saved,
        ),
      );
    }
    WorkspaceFinanceSnapshot snapshot(
      int revision, {
      bool complete = true,
      bool mismatch = false,
    }) => WorkspaceFinanceSnapshot(
      accountScope: seed.accountScope,
      workspaceId: seed.storeId,
      revision: revision,
      asOf: saved,
      salesTodayMinor: 30000,
      duesMinor: 15000,
      availableMinor: 0,
      heldMinor: 0,
      requestedMinor: 0,
      paidOutMinor: 0,
      feesMinor: 0,
      deliveryAdjustmentsMinor: 0,
      refundsMinor: 0,
      taxWithheldMinor: 0,
      historyComplete: complete,
      payments: [
        for (final state in states)
          WorkspacePaymentRecord(
            orderId: state.name,
            invoiceId: mismatch ? 'OTHER-${state.name}' : state.name,
            customerId: 'Customer',
            customerName: 'Customer',
            revision: revision,
            updatedAt: saved,
            amountMinor: 10000,
            paidMinor: state == WorkspacePaymentState.paid
                ? 10000
                : state == WorkspacePaymentState.partPaid
                ? 5000
                : 0,
            dueMinor: state == WorkspacePaymentState.paid
                ? 0
                : state == WorkspacePaymentState.partPaid
                ? 5000
                : 10000,
            refundedMinor: 0,
            state: state,
            channel: WorkspacePaymentChannel.cash,
          ),
      ],
      payouts: const [],
      customerLedgers: const [],
    );
    work.applyWorkspaceFinance(snapshot(1));
    await mount(tester, route: '/app/work/workspace/dashboard', work: work);
    await openRecordedSales(tester);
    await tester.pumpAndSettle();
    String? status(WorkspacePaymentState state) => tester
        .widget<Text>(find.byKey(ValueKey('work-sales-status-${state.name}')))
        .data;
    expect(
      status(WorkspacePaymentState.paid),
      WorkspacePaymentState.paid.label,
    );
    expect(
      status(WorkspacePaymentState.partPaid),
      '${WorkspacePaymentState.partPaid.label} · Due ₹50',
    );
    expect(status(WorkspacePaymentState.unpaid), 'Amount due ₹100');
    await tester.tap(find.byKey(const ValueKey('work-sales-invoice-unpaid')));
    await tester.pumpAndSettle();
    final guide = find.byKey(const Key('work-counter-handover-hint'));
    final receipt = find.byKey(const Key('work-invoice-record-payment'));
    await reveal(tester, receipt);
    expect(guide, findsOneWidget);
    expect(
      tester.getBottomRight(guide).dy,
      lessThanOrEqualTo(tester.getTopLeft(receipt).dy),
    );
    expect(
      find.text(
        'Record money received against this bill to update customer dues.',
      ),
      findsOneWidget,
    );
    await openSalesTask(tester, 'records');
    await tester.pumpAndSettle();
    work.applyWorkspaceFinance(snapshot(2, mismatch: true));
    await tester.pumpAndSettle();
    expect(status(WorkspacePaymentState.paid), 'Payment status unavailable');
    work.applyWorkspaceFinance(snapshot(3, complete: false));
    await tester.pumpAndSettle();
    expect(
      status(WorkspacePaymentState.partPaid),
      'Payment status unavailable',
    );
    work.applyWorkspaceFinance(snapshot(4));
    work.markWorkspaceFinanceStale(
      accountScope: seed.accountScope,
      storeId: seed.storeId,
    );
    await tester.pumpAndSettle();
    expect(status(WorkspacePaymentState.unpaid), 'Payment status unavailable');
    work.workspaceOrders.add(
      WorkspaceOrderRecord(
        id: 'paid',
        customer: 'Customer',
        items: 'Goods',
        quantities: const {'test-product': 1},
        amount: 100,
        source: 'Counter',
        fulfilment: 'At the shop',
        payment: 'Cash',
        address: '',
        stage: 'Completed',
        needsDelivery: false,
        createdAt: saved,
        itemSnapshots: const [
          WorkspaceOrderItemSnapshot(
            productId: 'test-product',
            name: 'Goods',
            pack: '1 pack',
            quantity: 1,
            unitPricePaise: 10000,
            lineTotalPaise: 10000,
          ),
        ],
      ),
    );
    expect(work.applyWorkspaceFinance(snapshot(5)), isTrue);
    await tester.pumpAndSettle();
    await openSavedInvoiceFromSales(tester, 'paid');
    final adjustments = find.byKey(const Key('work-invoice-adjustments'));
    await reveal(tester, adjustments);
    await tester.tap(adjustments);
    await tester.pumpAndSettle();
    final sheet = find.byType(BottomSheet).last;
    final originalFinance = work.workspaceFinance;
    final originalInvoiceCount = work.workspaceInvoices.length;
    final originalInvoices = List<WorkspaceCustomerInvoice>.of(
      work.workspaceInvoices,
    );
    const incompleteReturnHistory =
        'Return quantities unavailable. Recover the original invoice records before recording a return.';
    expect(
      find.descendant(of: sheet, matching: find.text(incompleteReturnHistory)),
      findsOneWidget,
    );
    expect(find.byKey(const ValueKey('record-return-paid')), findsNothing);
    // Use the real Work account-recovery owner, not a money-period repaint
    // that previously happened to rebuild the entry gate in the top layout.
    await work.recoverPendingProof(accountReady: true);
    contactStore.accountScope = 'different-evaluation-account';
    await work.recoverPendingProof(accountReady: true);
    work.setWorkspaceMoneyPeriod('Today');
    await tester.pumpAndSettle();
    expect(work.workspaceFinance, isNull);
    expect(
      work.activeWorkspace,
      isNull,
      reason: 'Account change must clear the previous approved Store.',
    );
    expect(
      find.descendant(
        of: sheet,
        matching: find.text('Return to this invoice’s Store to view it.'),
      ),
      findsOneWidget,
    );
    expect(find.byKey(const ValueKey('record-return-paid')), findsNothing);
    expect(find.byKey(const ValueKey('record-refund-paid')), findsNothing);
    contactStore.accountScope = seed.accountScope;
    await work.recoverPendingProof(accountReady: true);
    work.setWorkspaceMoneyPeriod('Today');
    await tester.pumpAndSettle();
    // Host-only authenticated-return stimulus; not backend/persistence proof.
    work.activeWorkspace = seed.workspace;
    work.workspaceInvoices
      ..clear()
      ..addAll(originalInvoices);
    expect(work.applyWorkspaceFinance(originalFinance!), isTrue);
    await tester.pumpAndSettle();
    expect(work.workspaceFinance, same(originalFinance));
    expect(work.workspaceInvoices, hasLength(originalInvoiceCount));
    expect(
      find.descendant(
        of: sheet,
        matching: find.text(
          'Payment records are unavailable. Close and reopen this invoice after records have loaded.',
        ),
      ),
      findsNothing,
    );
    expect(
      find.descendant(of: sheet, matching: find.text(incompleteReturnHistory)),
      findsOneWidget,
    );
    expect(find.byKey(const ValueKey('record-return-paid')), findsNothing);
    expect(work.applyWorkspaceFinance(snapshot(6, mismatch: true)), isTrue);
    await tester.pumpAndSettle();
    expect(
      find.descendant(
        of: sheet,
        matching: find.text(
          'This invoice’s payment record is unavailable. Close and check its saved records before recording an adjustment.',
        ),
      ),
      findsOneWidget,
    );
    expect(
      find.descendant(
        of: sheet,
        matching: find.text('Return to this invoice’s Store to view it.'),
      ),
      findsNothing,
    );
    work.activeWorkspace = null;
    work.setWorkspaceMoneyPeriod('Today');
    await tester.pumpAndSettle();
    expect(
      find.descendant(
        of: sheet,
        matching: find.text('Return to this invoice’s Store to view it.'),
      ),
      findsOneWidget,
    );
    expect(find.byKey(const ValueKey('record-return-paid')), findsNothing);
    expect(tester.takeException(), isNull);
  });

