  testWidgets('COUNTERD01 Sales periods filter saved invoice issue dates', (
    tester,
  ) async {
    final work = storeViewFixture(null, _ContactDraftFixtureStore());
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final dates = [
      today,
      today.subtract(const Duration(days: 6)),
      today.subtract(const Duration(days: 8)),
      DateTime(now.year - 1, 12, 31),
      today.add(const Duration(days: 1)),
    ];
    work.workspaceInvoices.clear();
    for (var index = 0; index < dates.length; index++) {
      work.workspaceInvoices.add(
        WorkspaceCustomerInvoice(
          id: 'PERIOD-$index',
          orderId: 'ORDER-$index',
          customer: 'Customer $index',
          items: 'Saved product',
          amount: 125,
          payment: 'Cash',
          issuedAt: dates[index],
        ),
      );
    }
    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      viewport: const Size(800, 1400),
    );
    await openRecordedSales(tester);
    await tester.pumpAndSettle();
    final period = find.byKey(const Key('work-statement-period'));
    Future<void> checkPeriod(String label, DateTime start) async {
      await tester.tap(period);
      await tester.pumpAndSettle();
      await tester.tap(find.widgetWithText(PopupMenuItem<String>, label));
      await tester.pumpAndSettle();
      final includedCount = dates
          .where(
            (date) =>
                !date.isBefore(start) &&
                date.isBefore(today.add(const Duration(days: 1))),
          )
          .length;
      expect(
        tester
            .widget<Text>(find.byKey(const Key('work-sales-period-total')))
            .data,
        '₹${includedCount * 125}',
      );
      final displayLabel = label == 'Year'
          ? 'Year ${now.year}'
          : label == 'Month'
          ? MaterialLocalizations.of(
              tester.element(period),
            ).formatMonthYear(now)
          : label == 'Week'
          ? 'This week'
          : label;
      expect(
        find.descendant(of: period, matching: find.text(displayLabel)),
        findsOneWidget,
      );
      expect(find.byTooltip('Sales period · $displayLabel'), findsOneWidget);
      for (var index = 0; index < dates.length; index++) {
        final included =
            !dates[index].isBefore(start) &&
            dates[index].isBefore(today.add(const Duration(days: 1)));
        expect(
          find.byKey(ValueKey('work-sales-invoice-PERIOD-$index')),
          included ? findsOneWidget : findsNothing,
        );
      }
      expect(tester.takeException(), isNull);
    }

    await checkPeriod('Today', today);
    await checkPeriod('Week', today.subtract(const Duration(days: 6)));
    await checkPeriod('Month', DateTime(now.year, now.month));
    await checkPeriod('Year', DateTime(now.year));
    await tester.tap(period);
    await tester.pumpAndSettle();
    await tester.tap(
      find.widgetWithText(PopupMenuItem<String>, 'Custom range'),
    );
    await tester.pumpAndSettle();
    expect(find.byType(DateRangePickerDialog), findsOneWidget);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(
      find.descendant(of: period, matching: find.text('Year ${now.year}')),
      findsOneWidget,
    );
    expect(work.workspaceInvoices, hasLength(dates.length));
    expect(tester.takeException(), isNull);
  });

  testWidgets('COUNTERPOLISH readable scoped theme preserves Store styling', (
    tester,
  ) async {
    final work = liveStore();
    final invoicesBefore = List<WorkspaceCustomerInvoice>.of(
      work.workspaceInvoices,
    );
    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      viewport: const Size(412, 915),
    );
    final entry = find.byKey(const Key('work-store-sell'));
    final storeTheme = Theme.of(tester.element(entry));
    await openCounterSaleFromSales(tester);
    await tester.pumpAndSettle();
    final business = tester.widget<TextButton>(
      find.byKey(const Key('work-sale-business-details')),
    );
    expect(business.style!.backgroundColor?.resolve({}), isNull);
    expect(business.style!.foregroundColor!.resolve({}), MoolColors.navy);
    await enterSaleCustomer(
      tester,
      '9829012345',
      name: 'HOST ONLY theme customer',
    );
    // The approved full-screen Sales task uses the shared shell, not the
    // retired counterOrder gradient/Close branch. Inspect rendered styles.
    final heading = find.byKey(const Key('work-sales-task-heading'));
    final title = tester.widget<Text>(heading);
    expect(title.data, 'Counter sale');
    expect(title.style!.fontSize, 18);
    final appBar = find.ancestor(of: heading, matching: find.byType(AppBar));
    final header = tester.widget<AppBar>(appBar);
    expect(tester.getSize(appBar).width, 412);
    expect(tester.getSize(appBar).height, greaterThanOrEqualTo(48));
    expect(
      tester.getRect(appBar).contains(tester.getRect(heading).topLeft),
      isTrue,
    );
    expect(
      tester.getRect(appBar).contains(tester.getRect(heading).bottomRight),
      isTrue,
    );
    expect(header.backgroundColor, MoolColors.canvas);
    final titleStyle = DefaultTextStyle.of(
      tester.element(heading),
    ).style.merge(title.style);
    final foreground = Color.alphaBlend(
      titleStyle.color!,
      header.backgroundColor!,
    );
    final light = foreground.computeLuminance();
    final background = header.backgroundColor!.computeLuminance();
    expect(
      ((light > background ? light : background) + .05) /
          ((light < background ? light : background) + .05),
      greaterThanOrEqualTo(4.5),
    );
    final back = find.byKey(const Key('work-back'));
    expect(tester.widget<IconButton>(back).tooltip, 'Back');
    expect(tester.getSize(back).width, greaterThanOrEqualTo(48));
    expect(tester.getSize(back).height, greaterThanOrEqualTo(48));
    expect(back.hitTestable(), findsOneWidget);
    expect(find.byKey(const Key('work-store-stock')), findsNothing);
    expect(find.byKey(const Key('work-sales-switcher')), findsNothing);
    final counterTheme = Theme.of(tester.element(heading));
    expect(counterTheme, equals(storeTheme));
    expect(
      (Colors.white.computeLuminance() + .05) /
          (MoolColors.navy.computeLuminance() + .05),
      greaterThanOrEqualTo(4.5),
    );
    expect(
      1.05 / (MoolColors.success.computeLuminance() + .05),
      greaterThanOrEqualTo(4.5),
      reason: 'The separate green paid-status label remains readable on white.',
    );
    await tester.tap(back);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-sales-home')), findsOneWidget);
    expect(find.byKey(const Key('work-sales-recorded')), findsOneWidget);
    expect(heading, findsNothing);
    expect(Theme.of(tester.element(entry)), equals(storeTheme));
    expect(work.workspaceInvoices, equals(invoicesBefore));
    expect(work.workspaceInvoices, isEmpty);
    expect(tester.takeException(), isNull);
  });

