        tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
          channel,
          (call) async {
            if (call.method == 'requestPermissions') {
              return <int, int>{
                for (final id in call.arguments as List) id as int: 0,
              };
            }
            return 0;
          },
        );
