  // Labelled host fixtures: command dispatch is not provider acceptance.
  for (final change in ['none', 'trading', 'both', 'visibility', 'refused']) {
    testWidgets('Settings dispatch host-only $change', (tester) async {
      final gateway = ReviewWorkGateway();
      final work = liveStore(gateway: gateway);
      if (change == 'refused') {
        work.workspaceVisibleToCustomers = false;
        work.workspaceCatalogueItems.clear();
        expect(work.workspacePublicationReport.ready, isFalse);
      }
      final storeId = work.activeWorkspace?.id;
      final products = List.of(work.workspaceCatalogueItems);
      final orders = List.of(work.workspaceOrders);
      final invoices = List.of(work.workspaceInvoices);
      final activity = List.of(work.workspaceActivity);
      final updatedAt = work.workspaceLastUpdatedAt;
      final sound = work.workspaceOrderAlertSound;
      await mount(tester, route: '/app/work/workspace/dashboard', work: work);
      await openStoreSettings(tester);
      if (change == 'none') {
        expect(
          tester
              .widget<SegmentedButton<WorkspaceStoreState>>(
                find.byKey(const Key('work-status-store-state')),
              )
              .selected,
          {WorkspaceStoreState.open},
        );
        final visibility = find.byKey(const Key('work-status-visibility'));
        await reveal(tester, visibility);
        expect(tester.widget<SwitchListTile>(visibility).value, isTrue);
        final alerts = find.byKey(const Key('work-status-alert-sound'));
        await reveal(tester, alerts);
        expect(tester.widget<SwitchListTile>(alerts).value, sound);
        await tester.binding.handlePopRoute();
        await tester.pumpAndSettle();
        expect(
          find.byKey(const Key('work-store-operating-board')),
          findsOneWidget,
        );
        expect(work.workspaceActivity, orderedEquals(activity));
        expect(work.workspaceLastUpdatedAt, updatedAt);
        expect(gateway.operationalSaveCalls, 0);
        await openStoreSettings(tester);
      }
      final calls = gateway.operationalSaveCalls;
      if (change == 'both' || change == 'refused') {
        await tester.tap(
          find.descendant(
            of: find.byKey(const Key('work-status-store-state')),
            matching: find.text('Paused'),
          ),
        );
        await tester.pumpAndSettle();
      }
      if (change == 'trading' || change == 'both' || change == 'refused') {
        final soundControl = find.byKey(const Key('work-status-alert-sound'));
        await reveal(tester, soundControl);
        await tester.tap(soundControl);
        await tester.pumpAndSettle();
      }
      if (change == 'visibility' || change == 'refused') {
        final visibility = find.byKey(const Key('work-status-visibility'));
        await reveal(tester, visibility);
        await tester.tap(visibility);
        await tester.pumpAndSettle();
      }
      final save = find.byKey(const Key('work-status-save'));
      await reveal(tester, save);
      await tester.tap(save);
      await tester.pumpAndSettle();
      final expectedCalls = switch (change) {
        'trading' || 'visibility' => 1,
        'both' => 2,
        _ => 0,
      };
      expect(gateway.operationalSaveCalls - calls, expectedCalls);
      if (expectedCalls == 0) {
        expect(work.workspaceActivity, orderedEquals(activity));
        expect(work.workspaceLastUpdatedAt, updatedAt);
        expect(work.workspaceOrderAlertSound, sound);
        expect(work.workspaceStoreState, WorkspaceStoreState.open);
        expect(work.workspaceAcceptingOrders, isTrue);
      } else {
        final snapshot = gateway.lastOperationalSnapshot!;
        expect(snapshot.workspaceId, storeId);
        expect(
          snapshot.reason,
          change == 'visibility' ? 'visibility' : 'trading-controls',
        );
        expect(
          snapshot.state['orderAlertSound'],
          change == 'visibility' ? sound : !sound,
        );
        expect(snapshot.state['acceptingOrders'], change != 'both');
        expect(snapshot.state['visibleToCustomers'], change != 'visibility');
        expect(
          work.workspaceActivity.first.message,
          change == 'visibility'
              ? 'Private Store visibility preference requested.'
              : 'Store hours and order alerts updated.',
        );
        if (change == 'both') {
          expect(work.workspaceActivity[1].message, 'Store pause preference saved until In 1 hour.');
          expect(work.workspaceStoreState, WorkspaceStoreState.paused);
        } else {
          expect(work.workspaceStoreState, WorkspaceStoreState.open);
        }
      }
      if (change == 'refused') {
        expect(work.workspaceVisibleToCustomers, isFalse);
        expect(find.byKey(const Key('work-status-save')), findsOneWidget);
        final settingsScroll = find.descendant(
          of: find.byKey(const Key('work-dashboard-status-screen')),
          matching: find.byWidgetPredicate(
            (widget) =>
                widget is Scrollable &&
                widget.axisDirection == AxisDirection.down,
          ),
        );
        expect(settingsScroll, findsOneWidget);
        await tester.scrollUntilVisible(
          find.byKey(const Key('work-status-store-state')),
          -220,
          scrollable: settingsScroll,
        );
        await tester.pumpAndSettle();
        expect(
          tester
              .widget<SegmentedButton<WorkspaceStoreState>>(
                find.byKey(const Key('work-status-store-state')),
              )
              .selected,
          {WorkspaceStoreState.paused},
        );
        await reveal(tester, find.byKey(const Key('work-status-visibility')));
        expect(
          tester
              .widget<SwitchListTile>(
                find.byKey(const Key('work-status-visibility')),
              )
              .value,
          isTrue,
        );
        await reveal(tester, find.byKey(const Key('work-status-alert-sound')));
        expect(
          tester
              .widget<SwitchListTile>(
                find.byKey(const Key('work-status-alert-sound')),
              )
              .value,
          !sound,
        );
      } else {
        expect(
          find.byKey(const Key('work-store-operating-board')),
          findsOneWidget,
        );
      }
      expect(work.activeWorkspace?.id, storeId);
      expect(work.workspaceCatalogueItems, orderedEquals(products));
      expect(work.workspaceOrders, orderedEquals(orders));
      expect(work.workspaceInvoices, orderedEquals(invoices));
      expect(tester.takeException(), isNull);
    });
  }

  for (final scale in [1.0, 2.0]) {
    testWidgets('LF21 inline defaults confirm device save and retain failed entries $scale', (tester) async {
      final storage = _Lf20TradingFixtureStore();
      final work = WorkSession(gateway: ReviewWorkGateway(),
        contactDraftStore: _ContactDraftFixtureStore(), tradingPreferencesStoreFactory: (_) => storage)
        ..seedVerifiedWorkspace()..retailerSetupSaved = true..reviewStage = WorkReviewStage.live;
      addTearDown(work.dispose);
      final id = work.activeWorkspace!.id;
      storage.value = {'schemaVersion': 1, 'storeId': id, 'fields': {
        'openingTime': '21:30', 'closingTime': '05:15', 'maximumActiveOrders': 0,
        'alertSound': false, 'alertVibration': false,
      }};
      await work.loadWorkspaceProductDefaults(expectedStoreId: id);
      tester.view.devicePixelRatio = 1;
      tester.view.physicalSize = const Size(320, 800);
      addTearDown(tester.view.reset);
      await tester.pumpWidget(MaterialApp(builder: (context, child) => MediaQuery(
        data: MediaQuery.of(context).copyWith(textScaler: TextScaler.linear(scale)), child: child!),
        home: Scaffold(body: SingleChildScrollView(child: StoreSettingsStyle(
          child: StoreProductDefaultsSection(session: work))))));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Product controls'));
      await tester.pumpAndSettle();
      expect(find.textContaining('Defaults saved on this device.'), findsNothing,
        reason: 'Legacy trading-only record does not contain product defaults.');
      final low = find.byKey(const Key('work-default-low-stock'));
      await tester.ensureVisible(low);
      await tester.enterText(low, '17');
      final save = find.byKey(const Key('work-defaults-save'));
      await tester.ensureVisible(save);
      storage.saveGate = Completer<void>(); storage.failSave = true;
      await tester.tap(save);
      await tester.pump();
      expect(work.workspaceProductDefaultsSaved, isFalse);
      expect(tester.widget<FilledButton>(save).onPressed, isNull);
      storage.saveGate!.complete();
      await tester.pumpAndSettle();
      expect(tester.widget<TextField>(low).controller!.text, '17');
      expect(work.workspaceProductDefaultsSaved, isFalse);
      expect(storage.value!['schemaVersion'], 1);
      storage.failSave = false; storage.saveGate = null;
      await tester.ensureVisible(save);
      await tester.tap(save);
      await tester.pumpAndSettle();
      expect(work.workspaceProductDefaultsSaved, isTrue);
      expect((storage.value!['productDefaults'] as Map)['lowStockThreshold'], 17);
      expect((storage.value!['fields'] as Map)['openingTime'], '21:30');
      expect(find.textContaining('Defaults saved on this device.'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });
  }

