  for (final missingSetup in [true, false]) {
    for (final attentionTestName in [
      'Store coverage - truthful attention and Back setup=$missingSetup',
      if (missingSetup)
        'current Store qualification H24 attention queue is truthful and returns to dashboard',
    ]) {
      testWidgets(attentionTestName, (tester) async {
        final work = liveStore()
          ..retailerSetupSaved = !missingSetup
          ..primaryMobile = '9829012321'
          ..primaryMobileVerified = !missingSetup
          ..contactEmail = 'asha@example.com'
          ..contactEmailVerified = !missingSetup
          ..workspaceOrderCustomer = '';
        work.workspaceCatalogueItems.clear();
        work.workspaceOrders.clear();
        final storeId = work.activeWorkspace?.id;
        final invoices = List.of(work.workspaceInvoices);
        final reviewStage = work.reviewStage;
        await mount(tester, route: '/app/work/workspace/dashboard', work: work);
        await openStoreAlerts(tester);
        if (missingSetup) {
          expect(
            find.byKey(const Key('work-alert-contact-details')),
            findsOneWidget,
          );
          expect(
            find.byKey(const Key('work-alert-store-setup')),
            findsOneWidget,
          );
          expect(
            find.byKey(const Key('work-alert-dismiss-store-setup')),
            findsNothing,
          );
          expect(
            find.byKey(const Key('work-dashboard-alerts-empty')),
            findsNothing,
          );
          for (final destination in [
            ('store-setup', '/app/work/retailer/setup'),
            ('contact-details', '/app/work/workspace/contact'),
          ]) {
            final action = find.byKey(Key('work-alert-${destination.$1}'));
            await reveal(tester, action);
            await tester.tap(action);
            await tester.pumpAndSettle();
            expect(
              find.byKey(
                Key(
                  destination.$1 == 'store-setup'
                      ? 'retailer-setup-screen'
                      : 'work-contact-screen',
                ),
              ),
              findsOneWidget,
            );
            if (destination.$1 == 'contact-details') {
              expect(
                find.byKey(const Key('work-contact-screen')),
                findsOneWidget,
              );
            }
            await tester.binding.handlePopRoute();
            await tester.pumpAndSettle();
            expect(action, findsOneWidget);
            expect(work.activeWorkspace?.id, storeId);
            expect(work.retailerSetupSaved, isFalse);
            expect(work.reviewStage, reviewStage);
            expect(work.workspaceCatalogueItems, isEmpty);
            expect(work.workspaceOrders, isEmpty);
            expect(work.workspaceInvoices, orderedEquals(invoices));
          }
        } else {
          expect(
            find.byKey(const Key('work-dashboard-alerts-empty')),
            findsOneWidget,
          );
          expect(find.text('Nothing needs attention'), findsOneWidget);
        }
        await tester.binding.handlePopRoute();
        await tester.pumpAndSettle();
        expect(
          find.byKey(const Key('work-store-operating-board')),
          findsOneWidget,
        );
        expect(work.retailerSetupSaved, !missingSetup);
        expect(work.workspaceOrders, isEmpty);
        expect(tester.takeException(), isNull);
      });
    }
  }

  Future<void> verifyCurrentStoreGrowthOwners(WidgetTester tester) async {
    final work = liveStore();
    final storeId = work.activeWorkspace?.id;
    final products = List.of(work.workspaceCatalogueItems);
    final orders = List.of(work.workspaceOrders);
    final invoices = List.of(work.workspaceInvoices);
    await mount(tester, route: '/app/work/workspace/dashboard', work: work);
    await openStoreTools(tester);
    await tester.tap(find.byKey(const Key('work-business-grow')));
    await tester.pumpAndSettle();
    final growth = find.byKey(const Key('work-grow-destination'));
    expect(growth, findsOneWidget);
    for (final key in [
      'customers',
      'offers',
      'social',
      'paid-work',
      'services',
    ]) {
      final action = find.byKey(Key('work-growth-$key'));
      await reveal(tester, action);
      expect(action.hitTestable(), findsOneWidget);
    }
    expect(
      find.descendant(
        of: growth,
        matching: find.text('Buy stock at wholesale'),
      ),
      findsNothing,
    );
    expect(find.text('Publish paid work'), findsNothing);
    expect(find.text('Post requirement'), findsWidgets);
    final customers = find.byKey(const Key('work-growth-customers'));
    final growthScroll = find.descendant(
      of: growth,
      matching: find.byWidgetPredicate(
        (widget) =>
            widget is Scrollable && widget.axisDirection == AxisDirection.down,
      ),
    );
    expect(growthScroll, findsOneWidget);
    await tester.scrollUntilVisible(customers, -220, scrollable: growthScroll);
    await tester.pumpAndSettle();
    await tester.tap(customers);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-customers-destination')), findsOneWidget);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(growth, findsOneWidget);
    await reveal(tester, customers);
    await tester.tap(customers);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-customers-destination')), findsOneWidget);
    final visibleBack = find.byKey(const Key('work-operation-back'));
    expect(visibleBack.hitTestable(), findsOneWidget);
    expect(tester.widget<IconButton>(visibleBack).onPressed, isNotNull);
    await tester.tap(visibleBack);
    await tester.pumpAndSettle();
    expect(growth, findsOneWidget);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-store-operating-board')), findsOneWidget);
    await openStoreTools(tester);
    final directCustomers = find.byKey(const Key('work-business-customers'));
    await reveal(tester, directCustomers);
    await tester.tap(directCustomers);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('work-customers-destination')), findsOneWidget);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(growth, findsNothing);
    expect(find.byKey(const Key('work-store-operating-board')), findsOneWidget);
    expect(work.activeWorkspace?.id, storeId);
    expect(work.workspaceCatalogueItems, orderedEquals(products));
    expect(work.workspaceOrders, orderedEquals(orders));
    expect(work.workspaceInvoices, orderedEquals(invoices));
    expect(tester.takeException(), isNull);
  }

  testWidgets(
    'Store coverage - growth stays separate from stock purchasing',
    verifyCurrentStoreGrowthOwners,
  );
  testWidgets(
    'current Store qualification H32 Grow is customer growth and business support, not Wholesale',
    verifyCurrentStoreGrowthOwners,
  );

  Future<void> verifyCurrentFirstUseSetup(WidgetTester tester) async {
    final work = WorkSession()..seedVerifiedWorkspace();
    work.workspaceCatalogueItems.clear();
    work.workspaceOrders.clear();
    work.workspaceSalesToday = 0;
    work.workspaceSettlementBalance = 0;
    work.workspaceOrderCustomer = '';
    work.activeGroupBuy = null;
    await mount(tester, route: '/app/work/workspace/dashboard', work: work);
    expect(find.byKey(const Key('work-dashboard-hero')), findsNothing);
    expect(find.byKey(const Key('work-dashboard-live-metrics')), findsNothing);
    expect(find.byKey(const Key('work-store-recent-sales')), findsNothing);
    expect(find.byKey(const Key('work-activity-order-accept')), findsNothing);
    expect(find.byKey(const Key('work-activity-group-bulk')), findsNothing);
    expect(
      find.byKey(const Key('work-store-stock')).hitTestable(),
      findsOneWidget,
    );
    await tester.tap(find.byKey(const Key('work-store-orders')));
    await tester.pumpAndSettle();
    final operational = find.byKey(const Key('work-orders-destination'));
    expect(operational, findsOneWidget);
    for (final fakeMetric in [
      'No order waiting',
      'No delivery waiting',
      '₹0',
    ]) {
      expect(
        find.descendant(of: operational, matching: find.text(fakeMetric)),
        findsNothing,
      );
    }
    await tester.tap(find.byKey(const Key('work-dashboard-alerts')));
    await tester.pumpAndSettle();
    final setup = find.byKey(const Key('work-alert-store-setup'));
    expect(setup, findsOneWidget);
    await reveal(tester, setup);
    expect(setup.hitTestable(), findsOneWidget);
    await tester.tap(setup);
    await tester.pumpAndSettle();
    expect(find.byKey(const Key('retailer-setup-screen')), findsOneWidget);
    expect(work.retailerSetupSaved, isFalse);
    expect(work.workspaceOrders, isEmpty);
    expect(work.workspaceSalesToday, 0);
    expect(work.workspaceSettlementBalance, 0);
    expect(tester.takeException(), isNull);
  }

  testWidgets(
    'Store coverage - first-use priorities do not invent business',
