    ]) {
      testWidgets('O03 details inline payment evidence $variant $display', (
        tester,
      ) async {
        final work = storeViewFixture(null, _ContactDraftFixtureStore());
        final seed = StoreReviewSeed(
          accountScope: 'review-draft-account',
          orderCount: 12,
          now: DateTime.now().subtract(const Duration(minutes: 1)),
        );
        work.activeWorkspace = seed.workspace;
        final amount = variant == 'large-value' ? 1000000000 : 25000;
        final paid = variant == 'part-paid' ? 15000 : amount;
        final due = amount - paid;
        final refunded = variant == 'refunded' ? 25000 : 0;
        final payment = WorkspacePaymentRecord(
          orderId: 'INLINE-ORDER',
          invoiceId: 'INLINE-INVOICE',
          customerId: '9001234567',
          customerName: variant == 'name-missing'
              ? '9001234567'
              : 'Recorded customer',
          revision: 1,
          updatedAt: seed.finance.asOf,
          amountMinor: amount,
          paidMinor: paid,
          dueMinor: due,
          refundedMinor: refunded,
          state: variant == 'refunded'
              ? WorkspacePaymentState.refunded
              : due > 0
              ? WorkspacePaymentState.partPaid
              : WorkspacePaymentState.paid,
          channel: WorkspacePaymentChannel.cash,
        );
        final finance = WorkspaceFinanceSnapshot(
          accountScope: seed.accountScope,
          workspaceId: seed.storeId,
          revision: 1,
          asOf: seed.finance.asOf,
          salesTodayMinor: amount,
          duesMinor: due,
          availableMinor: 0,
          heldMinor: 0,
          requestedMinor: 0,
          paidOutMinor: 0,
          feesMinor: 0,
          deliveryAdjustmentsMinor: 0,
          refundsMinor: refunded,
          taxWithheldMinor: 0,
          payments: [payment],
          payouts: const [],
          customerLedgers: variant == 'mixed-reference'
              ? [
                  WorkspaceCustomerLedger(
                    accountScope: seed.accountScope,
                    workspaceId: seed.storeId,
                    customerId: payment.customerId,
                    customerName: payment.customerName,
                    revision: 1,
                    asOf: seed.finance.asOf,
                    openingBalanceMinor: 0,
                    historyComplete: true,
                    entries: [
                      for (var i = 0; i < 3; i++)
                        WorkspaceCustomerLedgerEntry(
                          id: 'reference-entry-$i',
                          operationId: 'reference-operation-$i',
                          invoiceId: payment.invoiceId!,
                          orderId: payment.orderId,
                          sequence: i + 1,
                          occurredAt: seed.finance.asOf,
                          kind: i == 0
                              ? WorkspaceLedgerEntryKind.invoice
                              : WorkspaceLedgerEntryKind.collection,
                          state: WorkspaceLedgerPostingState.posted,
                          amountMinor: i == 0
                              ? amount
                              : i == 1
                              ? 10000
                              : 15000,
                          channel: i == 2
                              ? WorkspacePaymentChannel.directUpi
                              : WorkspacePaymentChannel.cash,
                          paymentReference: i == 2
