  testWidgets('Store cart timed acknowledgement overlap and retained quantity', (
    tester,
  ) async {
    final semantics = tester.ensureSemantics();
    try {
      final work = liveStore();
      final controller = WorkProcurementController(
        currentAccountId: () => 'fixture-purchaser',
        currentStoreId: () => work.activeWorkspace?.id,
        storeApproved: () => work.activeWorkspace?.verified == true,
        bookmarks: _StorePurchaseBookmarks(),
        stateStoreFactory: _StorePurchaseState.new,
        sessionFactory: (identity, state) {
          final core = BuySession();
          addTearDown(core.dispose);
          return BuyV2Session(
            core: core,
            procurementIdentity: identity,
            customerStateStore: state,
            reviewDataEnabled: false,
            commerceAdapter: _StorePurchaseCommerce(identity.value!),
            productFactsAdapter: _StorePurchaseOrderReadyFacts(),
          );
        },
      );
      await mount(
        tester,
        route: '/app/work/workspace/dashboard',
        work: work,
        procurementFactory: () => controller,
      );
      await reveal(tester, find.byKey(const Key('work-quick-buy')));
      await reveal(tester, find.byKey(const Key('work-quick-buy')));
      await tester.tap(find.byKey(const Key('work-quick-buy')));
      await tester.pumpAndSettle();
      final buy = controller.session!;
      expect(buy.addProduct('w-rice'), isTrue);
      final acknowledgementAtAdd = buy.cartAcknowledgement;
      final acknowledgementClock = tester.binding.clock.now();
      final acknowledgementPumps = await tester.pumpAndSettle();
      debugPrintSynchronously(
        'STORE_CART_ACK_DIAGNOSTIC ${jsonEncode({'view': buy.view.name, 'destination': buy.destination.name, 'activeDockDestination': buy.activeDockDestination.name, 'acknowledgementAtAdd': acknowledgementAtAdd != null, 'acknowledgementAfterSettle': buy.cartAcknowledgement != null, 'activeAcknowledgement': buy.cartAcknowledgementForDestination(buy.activeDockDestination) != null, 'quantity': buy.quantityFor('w-rice'), 'activeCount': buy.countForDestination(buy.activeDockDestination), 'settlePumps': acknowledgementPumps, 'fakeElapsedMs': tester.binding.clock.now().difference(acknowledgementClock).inMilliseconds, 'addedIconCount': find.byKey(const ValueKey('buy-mini-cart-added-icon')).evaluate().length, 'normalIconCount': find.byKey(const ValueKey('buy-mini-cart-icon')).evaluate().length})}',
      );
      // F32 uses the compact Cart control here, not the floating icon switcher.
      final indicator = find.byKey(
        const ValueKey('buy-compact-cart-indicator'),
      );
      final cartButton = find.byKey(
        const ValueKey('buy-cart-navigation-button'),
      );
      expect(indicator, findsOneWidget);
      expect(cartButton.hitTestable(), findsOneWidget);
      // The admitted compatibility correction uses a 48dp embedded target;
      // the public/default compact Cart retains its separate 44dp contract.
      expect(tester.getSize(cartButton), const Size(48, 48));
      expect(
        find.descendant(of: indicator, matching: find.text('${buy.itemCount}')),
        findsOneWidget,
      );
      final acknowledgement = buy.cartAcknowledgement!;
      expect(tester.getSemantics(indicator).label, contains(acknowledgement));
      expect(
        tester.getSemantics(indicator).flagsCollection.isLiveRegion,
        isTrue,
      );
      final tooltip = find.descendant(
        of: indicator,
        matching: find.byType(Tooltip),
      );
      expect(
        tester.widget<Tooltip>(tooltip).message,
        tester.getSemantics(indicator).label,
      );
      expect(find.byKey(const ValueKey('buy-live-notice')), findsNothing);
      final before = buy.quantityFor('w-rice');
      await tester.pump(const Duration(milliseconds: 2600));
      await tester.pump(const Duration(milliseconds: 110));
      expect(buy.cartAcknowledgement, isNull);
      expect(cartButton.hitTestable(), findsOneWidget);
      expect(
        tester.getSemantics(indicator).label,
        isNot(contains(acknowledgement)),
      );
      expect(
        tester.widget<Tooltip>(tooltip).message,
        tester.getSemantics(indicator).label,
      );
      expect(buy.quantityFor('w-rice'), before);
      expect(buy.addProduct('w-rice'), isTrue);
      await tester.pump(const Duration(milliseconds: 16));
      expect(tester.takeException(), isNull);
      expect(buy.quantityFor('w-rice'), greaterThan(before));
      expect(cartButton.hitTestable(), findsOneWidget);
      expect(
        find.descendant(of: indicator, matching: find.text('${buy.itemCount}')),
        findsOneWidget,
      );
      expect(
        tester.getSemantics(indicator).label,
        contains(buy.cartAcknowledgement!),
      );
      expect(
        tester.getSemantics(indicator).flagsCollection.isLiveRegion,
        isTrue,
      );
      expect(
        tester.widget<Tooltip>(tooltip).message,
        tester.getSemantics(indicator).label,
      );
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pumpAndSettle();
      expect(tester.takeException(), isNull);
    } finally {
      semantics.dispose();
    }
  });
