  Future<void> verifyCurrentSavedRecordSearchBack(WidgetTester tester) async {
    // Host-only current-route discriminator, not historical H discharge or UAT.
    final work = liveStore();
    final storeId = work.activeWorkspace!.id;
    final stock = work.workspaceCatalogueItems
        .map((item) => (item.id, item.stock))
        .toList();
    final invoices = jsonEncode(
      work.workspaceInvoices.map((item) => item.toLedgerJson()).toList(),
    );
    await mount(tester, route: '/app/work/workspace/dashboard', work: work);
    await openSavedStoreRecordSearch(tester);
    final field = find.byKey(const Key('work-dashboard-search-field'));
    await tester.enterText(field, 'fortune');
    final restingPadding = tester.view.padding;
    tester.view.viewInsets = const FakeViewPadding(bottom: 300);
    tester.view.padding = FakeViewPadding(
      left: restingPadding.left,
      top: restingPadding.top,
      right: restingPadding.right,
    );
    await tester.pumpAndSettle();
    expect(work.workspaceSearchQuery, 'fortune');
    expect(tester.widget<TextField>(field).controller!.text, 'fortune');
    expect(tester.widget<TextField>(field).focusNode!.hasFocus, isTrue);
    expect(
      find.byKey(const Key('work-search-product-oil-fortune-1l')),
      findsOneWidget,
    );
    expect(
      find.byKey(Key('work-search-order-${work.currentWorkspaceOrderId}')),
      findsNothing,
    );
    expect(field.hitTestable(), findsOneWidget);
    expect(tester.getRect(field).top, greaterThanOrEqualTo(0));
    final unobscuredHeight =
        (tester.view.physicalSize.height - tester.view.viewInsets.bottom) /
        tester.view.devicePixelRatio;
    expect(
      tester.getRect(field).bottom,
      lessThanOrEqualTo(unobscuredHeight),
      reason: 'Full search field must remain above the actual root IME inset',
    );
    await tester.binding.handlePopRoute();
