  for (final drift in ['account', 'store', 'replacement visit']) {
    testWidgets('H22 retained exits cannot erase newer query after $drift', (
      tester,
    ) async {
      final account = _ContactDraftFixtureStore();
      final work = storeViewFixture(null, account);
      await mount(tester, route: '/app/work/workspace/dashboard', work: work);
      await openSavedStoreRecordSearch(tester);
      final field = find.byKey(const Key('work-dashboard-search-field'));
      final close = find.byKey(const Key('work-dashboard-search-close'));
      await tester.enterText(field, 'fortune');
      await tester.pumpAndSettle();
      final retainedBack = tester
          .widget<WorkPageScaffold>(find.byType(WorkPageScaffold))
          .onBack!;
      final retainedClose = tester.widget<IconButton>(close).onPressed!;
      final retainedTextChange = tester.widget<TextField>(field).onChanged!;
      final firstStore = work.activeWorkspace!;
      if (drift == 'account') {
        account.accountScope = 'other-labelled-host-account';
      } else if (drift == 'store') {
        work.activeWorkspace = WorkWorkspace(
          id: 'other-labelled-host-store',
          name: firstStore.name,
          profileLabel: firstStore.profileLabel,
          profileId: firstStore.profileId,
          area: firstStore.area,
          verified: true,
        );
      } else {
        await tester.tap(close);
        await tester.pumpAndSettle();
        await openSavedStoreRecordSearch(tester);
      }
      if (drift != 'replacement visit') {
        // clearMessages is intentionally non-notifying. Exercise the real
        // public notifying method so the mounted scope observer actually runs.
        work.dismissMessages();
        await tester.pumpAndSettle();
        expect(
          field,
          findsNothing,
          reason: 'Obsolete scope must not strand an inert search',
        );
        work.updateWorkspaceSearch('newer-query');
        if (drift == 'store') {
          await openSavedStoreRecordSearch(tester);
          expect(
            tester.widget<TextField>(field).controller!.text,
            'newer-query',
          );
        }
      }
      if (drift != 'account') await tester.enterText(field, 'newer-query');
      await tester.pumpAndSettle();
      final currentStore = work.activeWorkspace?.id;
      if (drift == 'account') {
        expect(currentStore, isNull);
        expect(find.text('No approved Workspace yet'), findsOneWidget);
      }
      retainedBack();
      retainedClose();
      retainedTextChange('obsolete-query-must-not-write');
      await tester.pumpAndSettle();
      // Changing the account does not confer approval for this Store. Do not
      // bypass the existing access surface to manufacture a new search visit.
      expect(field, drift == 'account' ? findsNothing : findsOneWidget);
      expect(work.workspaceSearchQuery, 'newer-query');
      if (drift != 'account') {
        expect(tester.widget<TextField>(field).controller!.text, 'newer-query');
      }
      expect(work.activeWorkspace?.id, currentStore);
      if (drift == 'account') {
        expect(find.text('No approved Workspace yet'), findsOneWidget);
      }
      expect(
        account.accountScope,
        drift == 'account'
            ? 'other-labelled-host-account'
            : 'review-draft-account',
      );
      expect(tester.takeException(), isNull);
    });
  }

