  for (final action in ['packing', 'Ready']) {
    for (final changed in [
      'customer',
      'items',
      'quantities',
      'amount',
      'source',
      'payment',
      'address',
      'fulfilment',
      'delivery',
      'deadline',
      'cancelled',
      'ready',
      'stored',
      'stored-cleared',
      'raw-amount',
      'packing-cleared',
      'selected',
      'store',
      'busy',
      'syncing',
      'handover',
      'disposed',
    ]) {
      if (changed == 'packing-cleared' && action == 'packing') continue;
      testWidgets('Legacy $action stale callback rejects $changed', (
        tester,
      ) async {
        final work = liveStore();
        seedIncomingOrder(work, stage: 'Preparing', delivery: true);
        await mount(
          tester,
          route: '/app/work/workspace/dashboard?section=orders',
          work: work,
        );
        final pack = find.byKey(const Key('work-order-pack-summary-0'));
        VoidCallback callback;
        if (action == 'Ready') {
          await tester.tap(pack);
          await tester.pump();
          await tester.tap(find.byKey(const Key('work-order-pack-summary-1')));
          await tester.pump();
          expect(work.workspaceOrders, isEmpty);
          callback = tester
              .widget<FilledButton>(
                find.widgetWithText(FilledButton, 'Mark ready'),
              )
              .onPressed!;
        } else {
          final onChanged = tester.widget<CheckboxListTile>(pack).onChanged!;
          callback = () => onChanged(true);
        }
        final original = work.visibleWorkspaceOrders.single;
        final invoices = List.of(work.workspaceInvoices);
        final stock = work.workspaceCatalogueItems
            .map((item) => (item.id, item.stock))
            .toList();
        switch (changed) {
          case 'customer':
            work.workspaceOrderCustomer = 'Other customer';
          case 'items':
            work.workspaceOrderItems = 'Different goods × 2';
          case 'quantities':
            work.workspaceOrderQuantities['other-product'] = 2;
          case 'amount':
            work.workspaceOrderAmount = '999';
          case 'source':
            work.workspaceOrderSource = 'Phone';
          case 'payment':
            work.workspaceOrderPayment = 'Unpaid';
          case 'address':
            work.workspaceOrderAddress = 'Another address';
          case 'fulfilment':
            work.workspaceOrderFulfilment = 'Pickup';
          case 'delivery':
            work.workspaceOrderNeedsDelivery = false;
          case 'deadline':
            work.workspaceOrderActionDeadline = DateTime(2026, 10, 10);
          case 'cancelled':
            work.workspaceOrderStage = 'Cancelled';
          case 'ready':
            work.workspaceOrderStage = 'Ready';
          case 'stored':
            work.workspaceOrders.add(original);
          case 'stored-cleared':
            work.workspaceOrders.add(original);
            work.workspaceOrderCustomer = '';
            work.workspaceOrderQuantities.clear();
          case 'raw-amount':
            work.workspaceOrderAmount = '01468';
          case 'packing-cleared':
            work.workspacePackedProductIds.clear();
          case 'selected':
            work.currentWorkspaceOrderId = 'SAVED-OTHER';
          case 'store':
            work.activeWorkspace = const WorkWorkspace(
              id: 'other-store',
              name: 'Other Store',
              profileId: 'retailer-grocery',
              profileLabel: 'Grocery',
              area: 'Jodhpur',
              verified: true,
            );
          case 'busy':
            work.busy = true;
          case 'syncing':
            work.workspaceOperationsSyncing = true;
          case 'handover':
            work.workspaceHandoverBusy = true;
          case 'disposed':
            await tester.pumpWidget(const SizedBox.shrink());
        }
        final stage = work.workspaceOrderStage;
        final selected = work.currentWorkspaceOrderId;
        final saved = List.of(work.workspaceOrders);
        final packed = Set.of(work.workspacePackedProductIds);
        callback();
        expect(work.workspacePackedProductIds, packed);
        expect(work.workspaceOrderStage, stage);
        expect(work.currentWorkspaceOrderId, selected);
        expect(work.workspaceOrders, orderedEquals(saved));
        expect(work.workspaceInvoices, orderedEquals(invoices));
        // Switching Store changes its scoped catalogue; check the unchanged Store
        // cases without asserting that another Store shares this one's records.
        if (changed != 'store') {
          expect(
            work.workspaceCatalogueItems.map((item) => (item.id, item.stock)),
            orderedEquals(stock),
          );
        }
        expect(tester.takeException(), isNull);
        await tester.pumpWidget(const SizedBox.shrink());
      });
    }
  }

