            work.workspaceOrderAddress = 'Another evaluation address';
          case 'stored':
            work.workspaceOrders.add(work.visibleWorkspaceOrders.single);
          case 'selection':
            work.currentWorkspaceOrderId = 'another-order';
          case 'account':
            account.accountScope = 'changed-evaluation-account';
          case 'account-selection':
            account.accountScope = 'changed-evaluation-account';
            work.currentWorkspaceOrderId = 'another-order';
          case 'store':
          case 'store-selection':
            work.activeWorkspace = const WorkWorkspace(
              id: 'HOST-REJECT-OTHER-STORE',
              name: 'Other Store',
              profileId: 'retailer-grocery',
              profileLabel: 'Grocery',
              area: 'Jaipur',
              verified: true,
            );
            if (changed == 'store-selection') {
              work.currentWorkspaceOrderId = 'another-order';
            }
          case 'closed':
            work.workspaceOrderStage = 'Cancelled';
          case 'deadline':
            work.workspaceOrderActionDeadline = DateTime.now().subtract(
              const Duration(minutes: 1),
            );
          case 'busy':
            work.busy = true;
          case 'sync':
            work.workspaceOperationsSyncing = true;
          case 'handover':
            work.workspaceHandoverBusy = true;
        }
        final records = jsonEncode(
          work.workspaceOrders.map((item) => item.toLedgerJson()).toList(),
        );
        final invoices = jsonEncode(
          work.workspaceInvoices.map((item) => item.toLedgerJson()).toList(),
        );
        final stock = work.workspaceCatalogueItems
            .map((item) => (item.id, item.stock))
            .toList();
        final selected = work.currentWorkspaceOrderId;
        final stage = work.workspaceOrderStage;
        final notice = work.noticeMessage;
        final error = work.errorMessage;
        await tester.tap(
          find.descendant(
            of: dialog,
            matching: find.widgetWithText(FilledButton, 'Reject order'),
          ),
        );
        // First frame starts the reverse route animation; the next advances it.
        await tester.pump();
        await tester.pump(const Duration(seconds: 1));
        expect(find.byKey(const Key('work-reject-order-dialog')), findsNothing);
        expect(
          jsonEncode(
            work.workspaceOrders.map((item) => item.toLedgerJson()).toList(),
          ),
          records,
        );
        expect(
          jsonEncode(
            work.workspaceInvoices.map((item) => item.toLedgerJson()).toList(),
          ),
          invoices,
        );
        expect(
          work.workspaceCatalogueItems.map((item) => (item.id, item.stock)),
          orderedEquals(stock),
        );
        expect(work.currentWorkspaceOrderId, selected);
        expect(work.workspaceOrderStage, stage);
        if (const [
          'account',
          'account-selection',
          'store',
          'store-selection',
        ].contains(changed)) {
          expect(work.noticeMessage, notice);
          expect(work.errorMessage, error);
          expect(
            find.text('This order changed. Review its latest status.'),
            findsNothing,
          );
        } else if (changed == 'selection') {
          expect(
            work.noticeMessage,
            'This order changed. Review its latest status.',
          );
        }
        expect(booking.requests, isEmpty);
        expect(tester.takeException(), isNull);
      },
    );
  }

