        operationId: command?.operationId ?? '',
        revision: command == null ? 1 : 2,
        state: rejected
            ? WorkOrderReplyState.rejected
            : WorkOrderReplyState.applied,
        order: command == null || rejected
            ? original
            : original.copyWith(
                stage: 'Cancelled',
                rejectionReason: 'Product unavailable',
                stockReserved: false,
              ),
      );
      operations.observe(reply());
      expect(work.bindWorkspaceOrderOperations(operations), isTrue);
      final originalLedger = jsonEncode(
        work.currentWorkspaceOrder!.toLedgerJson(),
      );
      final stock = work.workspaceCatalogueItems
          .map((item) => (item.id, item.stock))
          .toList();
      final invoices = jsonEncode(
        work.workspaceInvoices.map((item) => item.toLedgerJson()).toList(),
      );
      await mount(tester, route: '/app/work/workspace/dashboard', work: work);
      await tester.tap(find.byKey(const Key('work-store-orders')));
      await tester.pumpAndSettle();
      final reject = find.byKey(const Key('work-activity-order-reject'));
      await reveal(tester, reject);
      await tester.tap(reject);
      await tester.pumpAndSettle();
      final dialog = find.byKey(const Key('work-reject-order-dialog'));
      await tester.tap(find.text('Product unavailable'));
      await tester.pumpAndSettle();
      await tester.tap(
        find.descendant(
          of: dialog,
          matching: find.widgetWithText(FilledButton, 'Reject order'),
        ),
      );
      await tester.pumpAndSettle();
      expect(gateway.submitted, hasLength(1));
      final command = gateway.submitted.single;
      expect(
        (
          command.accountScope,
          command.workspaceId,
          command.orderId,
          command.expectedRevision,
          command.action,
          command.reason,
        ),
        (
          'review-draft-account',
          storeId,
          original.id,
          1,
          WorkOrderAction.reject,
          'Product unavailable',
        ),
      );
      expect(work.workspaceOrderStage, 'Confirmed');
      expect(
        jsonEncode(work.currentWorkspaceOrder!.toLedgerJson()),
        originalLedger,
      );
      if (outcome == 'account') {
        account.accountScope = 'different-evaluation-account';
      }
      if (outcome == 'unknown') {
        gateway.responses.single.completeError(StateError('response unknown'));
      } else {
        gateway.responses.single.complete(
          reply(command: command, rejected: outcome == 'rejected'),
        );
      }
      await tester.pumpAndSettle();
      if (outcome == 'unknown') {
        expect(operations.pending(original.id), isNotNull);
        final retry = find.byKey(
          Key('work-order-operation-retry-${original.id}'),
        );
        await reveal(tester, retry);
        await tester.tap(retry);
        await tester.pumpAndSettle();
        expect(gateway.reconciled.single, same(command));
        gateway.replies.single.complete(reply(command: command));
        await tester.pumpAndSettle();
        expect(operations.pending(original.id), isNull);
      }
      expect(work.currentWorkspaceOrderId, original.id);
      expect(
        work.workspaceOrderStage,
        ['applied', 'unknown'].contains(outcome) ? 'Cancelled' : 'Confirmed',
      );
      if (['rejected', 'account'].contains(outcome)) {
        expect(
          jsonEncode(work.currentWorkspaceOrder!.toLedgerJson()),
          originalLedger,
        );
      } else {
        expect(
          work.currentWorkspaceOrder!.rejectionReason,
          'Product unavailable',
        );
      }
      expect(gateway.submitted, hasLength(1));
      expect(gateway.reconciled, outcome == 'unknown' ? hasLength(1) : isEmpty);
      expect(
        work.workspaceCatalogueItems.map((item) => (item.id, item.stock)),
        orderedEquals(stock),
      );
      expect(
        jsonEncode(
          work.workspaceInvoices.map((item) => item.toLedgerJson()).toList(),
        ),
        invoices,
      );
      expect(tester.takeException(), isNull);
    });
  }

