      final records = jsonEncode(
        work.workspaceOrders.map((item) => item.toLedgerJson()).toList(),
      );
      if (result == 'stale-before') {
        account.accountScope = 'changed-before-call';
      }
      callback();
      await tester.pump();
      await tester.pump();
      expect(requests, result == 'stale-before' ? isEmpty : hasLength(1));
      if (requests.isNotEmpty) {
        expect(requests.single.scheme, 'tel');
        expect(
          requests.single.path,
          workspaceCustomerMobile(work.currentWorkspaceOrder!.customer),
        );
      }
      if (result == 'stale-after') {
        account.accountScope = 'changed-after-launch';
      }
      response.complete(result == 'success');
      await tester.pumpAndSettle();
      expect(
        find.text('Could not open your phone app. Please try again.'),
        result == 'failure' ? findsOneWidget : findsNothing,
      );
      expect(
        jsonEncode(
          work.workspaceOrders.map((item) => item.toLedgerJson()).toList(),
        ),
        records,
      );
      expect(work.currentWorkspaceOrderId, 'APP-1043');
      expect(tester.takeException(), isNull);
    });
  }

