          work.workspaceOrders.add(work.visibleWorkspaceOrders.single);
        case 'closed':
          work.workspaceOrderStage = 'Cancelled';
        case 'not-delivery':
          work.workspaceOrderStage = 'Preparing';
        case 'busy':
          work.busy = true;
        case 'sync':
          work.workspaceOperationsSyncing = true;
        case 'handover':
          work.workspaceHandoverBusy = true;
        case 'submitting':
          discard = work.discardWorkspaceCounterDraft();
          expect(work.counterDraftSubmitting, isTrue);
        case 'unchanged':
          break;
      }
      final records = jsonEncode(
        work.workspaceOrders.map((item) => item.toLedgerJson()).toList(),
