      expect(work.workspaceInvoices, isEmpty);
      expect(work.currentWorkspaceOrderId, selectedId);
      expect(work.workspaceOrderStage, stageAfterChange);
      expect(
        work.workspaceOrders.map((order) => (order.id, order.stage)),
        orderedEquals(orderStages),
      );
      expect(
        work.workspaceCatalogueItems.map((item) => (item.id, item.stock)),
        orderedEquals(stock),
      );
      expect(tester.takeException(), isNull);
    });
  }

