            expect(
              work.updateWorkspaceCounterDiscount(
                const WorkspaceBillDiscount.fixed(1),
              ),
              isTrue,
            );
          case 'catalogue':
            work.workspaceCatalogueItems[0] = product.copyWith(
              sellingPrice: product.sellingPrice + 1,
            );
          case 'raw-amount':
            work.workspaceOrderAmount = '01468';
          case 'stored':
            work.workspaceOrders.add(work.visibleWorkspaceOrders.single);
          case 'selection':
            work.currentWorkspaceOrderId = 'another-order';
          case 'account':
            account.accountScope = 'changed-evaluation-account';
          case 'closed':
            work.workspaceOrderStage = 'Cancelled';
          case 'busy':
            work.busy = true;
          default:
            break;
        }
        final records = jsonEncode(
