  testWidgets('DASH10 five thousand stock products are built lazily', (
    tester,
  ) async {
    final work = liveStore();
    for (var i = 1; i <= 5000; i++) {
      work.workspaceCatalogueItems.add(catalogueProduct(i));
    }
    await mount(
      tester,
      route: '/app/work/workspace/dashboard',
      work: work,
      viewport: const Size(412, 915),
      textScale: 1,
    );
    await tester.tap(find.byKey(const Key('work-store-stock')));
    await tester.pumpAndSettle();
    await openStoreStockStatement(tester);
    await tester.pumpAndSettle();
    final mounted = find.byWidgetPredicate(
      (widget) =>
          widget.key is ValueKey<String> &&
          (widget.key! as ValueKey<String>).value.startsWith(
            'work-stock-position-',
          ),
    );
    expect(mounted.evaluate().length, lessThan(30));
    expect(mounted.evaluate().length, greaterThan(0));
    expect(work.workspaceCatalogueItems.length, 5001);
    final firstBefore = tester.getTopLeft(
      find.byKey(const Key('work-stock-position-oil-fortune-1l')),
    );
    final changed = work.workspaceCatalogueItems.indexWhere(
      (product) => product.id == catalogueProduct(1).id,
    );
    expect(changed, greaterThanOrEqualTo(0));
    work.workspaceCatalogueItems[changed] = work
        .workspaceCatalogueItems[changed]
        .copyWith(stock: 0, available: false);
    work.notifyListeners();
    await tester.pumpAndSettle();
    expect(
      tester.getTopLeft(
        find.byKey(const Key('work-stock-position-oil-fortune-1l')),
      ),
      firstBefore,
    );
    expect(tester.takeException(), isNull);
    await captureStoreView(tester, 'stock-five-thousand-products');
  });

  // The APK wrapper requires the exact review-runtime test name below. Normal
  // builds instead verify that the review seed is unavailable; no test is skipped.
  if (!storeReviewRuntime) {
    test('STOREBACK01 non-review runtime refuses the review Store', () {
      final work = WorkSession(contactDraftStore: _ContactDraftFixtureStore())
        ..seedVerifiedWorkspace();
      addTearDown(work.dispose);
      expect(work.canLoadStoreReviewSeed, isFalse);
      expect(work.loadStoreReviewSeed(1000), isFalse);
    });
  } else {
    testWidgets(
      'STOREBACK02 SKU count overlapping loading transitions and exit',
      (tester) async {
        final previousPreferences = SharedPreferencesAsyncPlatform.instance;
        SharedPreferencesAsyncPlatform.instance =
            InMemorySharedPreferencesAsync.empty();
        addTearDown(
          () => SharedPreferencesAsyncPlatform.instance = previousPreferences,
        );
        const storageChannel = MethodChannel(
          'plugins.it_nomads.com/flutter_secure_storage',
        );
        final stored = <String, String>{};
        tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
          storageChannel,
          (call) async {
            final arguments = Map<String, dynamic>.from(call.arguments as Map);
            final key = arguments['key'] as String?;
            switch (call.method) {
              case 'read':
                return stored[key];
              case 'write':
                stored[key!] = arguments['value'] as String;
                return null;
              case 'delete':
                stored.remove(key);
                return null;
              case 'readAll':
                return stored;
              default:
                return null;
            }
          },
        );
        addTearDown(
          () => tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
            storageChannel,
            null,
          ),
        );
        final work = WorkSession(contactDraftStore: _ContactDraftFixtureStore())
          ..seedVerifiedWorkspace()
          ..retailerSetupSaved = true
          ..reviewStage = WorkReviewStage.live
          ..workspaceStoreState = WorkspaceStoreState.open;
        expect(work.loadStoreReviewSeed(1000), isTrue);
        await mount(tester, route: '/app/buy', work: work, uiReviewOnly: true);
        final router = GoRouter.of(tester.element(find.byType(BuyV2Screen)));
        unawaited(router.push('/app/work/workspace/dashboard'));
        await tester.pumpAndSettle();
        await reveal(tester, find.byKey(const Key('work-quick-buy')));
        await reveal(tester, find.byKey(const Key('work-quick-buy')));
        await tester.tap(find.byKey(const Key('work-quick-buy')));
        await tester.pumpAndSettle();
        await tester.pump(const Duration(milliseconds: 700));
        await tester.pumpAndSettle();
        final buy = tester.widget<BuyV2Screen>(find.byType(BuyV2Screen)).session;
        // The shared public pager replaced the detached Store count animation.
        // Exercise real catalogue updates and exit while frames overlap.
        for (final (query, mode, elapsed) in [
          ('', BuyV2WholesaleSaleType.wholesale, 220),
          ('zzqav12', BuyV2WholesaleSaleType.wholesale, 150),
          ('', BuyV2WholesaleSaleType.bulk, 16),
          ('zzqav12', BuyV2WholesaleSaleType.bulk, 16),
          ('', BuyV2WholesaleSaleType.wholesale, 16),
        ]) {
          buy.updateQuery(query);
          buy.chooseWholesaleSaleType(mode);
          await tester.pump(Duration(milliseconds: elapsed));
          expect(
            tester.takeException(),
            isNull,
            reason: 'Shared catalogue update $query/$mode',
          );
        }
        await tester.binding.handlePopRoute();
        await tester.pumpAndSettle();
        expect(tester.takeException(), isNull);
        expect(find.byKey(const Key('work-store-procurement-screen')), findsNothing);
        expect(find.byKey(const Key('work-dashboard-catalogue-screen')), findsOneWidget);
      },
    );
    testWidgets('STOREBACK01 full app Restock Bulk native Back lifecycle', (
      tester,
    ) async {
      final semantics = tester.ensureSemantics();
      try {
        final previousPreferences = SharedPreferencesAsyncPlatform.instance;
        SharedPreferencesAsyncPlatform.instance =
            InMemorySharedPreferencesAsync.empty();
        addTearDown(
          () => SharedPreferencesAsyncPlatform.instance = previousPreferences,
        );
        const storageChannel = MethodChannel(
          'plugins.it_nomads.com/flutter_secure_storage',
        );
        final stored = <String, String>{};
        var delayBookmarkWrites = false;
        tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
          storageChannel,
          (call) async {
            final arguments = Map<String, dynamic>.from(call.arguments as Map);
            final key = arguments['key'] as String?;
            switch (call.method) {
              case 'read':
                return stored[key];
              case 'write':
                if (delayBookmarkWrites) {
                  await Future<void>.delayed(const Duration(milliseconds: 250));
                }
                stored[key!] = arguments['value'] as String;
                return null;
              case 'delete':
                stored.remove(key);
                return null;
              case 'readAll':
                return stored;
              default:
                return null;
            }
          },
        );
        addTearDown(
          () => tester.binding.defaultBinaryMessenger.setMockMethodCallHandler(
            storageChannel,
            null,
          ),
        );
        final work = WorkSession(contactDraftStore: _ContactDraftFixtureStore())
          ..seedVerifiedWorkspace()
          ..retailerSetupSaved = true
          ..reviewStage = WorkReviewStage.live
          ..workspaceStoreState = WorkspaceStoreState.open;
        expect(work.loadStoreReviewSeed(1000), isTrue);
        await mount(tester, route: '/app/buy', work: work, uiReviewOnly: true);
        final router = GoRouter.of(tester.element(find.byType(BuyV2Screen)));
        unawaited(router.push('/app/work/workspace/dashboard'));
        await tester.pumpAndSettle();
        String? retainedProductId;
        int? retainedQuantity;
        for (final stackCase in [0, 1, 2]) {
          final replaceSignInStack = stackCase == 1;
          final oppoMetrics = stackCase == 2;
          if (oppoMetrics) {
            // OPPO CPH2375: measured physical viewport, system bars and IME.
            tester.view.devicePixelRatio = 2;
            tester.view.physicalSize = const Size(720, 1612);
            tester.view.viewPadding = const FakeViewPadding(
              top: 82,
              bottom: 88,
            );
            tester.platformDispatcher.textScaleFactorTestValue = 1;
            await tester.pumpAndSettle();
          }
          if (replaceSignInStack) {
            // Authentication returns through go(), replacing the pushed Store
            // stack. Exercise the same return after all original stack cases.
            // Analytics has no utility band. Use the actual Orders/Profile
            // entry without resetting the live Restock navigation stack.
            await openStoreProfile(tester);
            final security = find.byKey(const Key('global-profile-security'));
            // At enlarged text the nearest edge can lie below the panel's
            // clipped viewport. Center the real row, never tap the barrier.
            await Scrollable.ensureVisible(
              tester.element(security), alignment: .5,
            );
            await tester.pumpAndSettle();
            expect(security.hitTestable(), findsOneWidget);
            await tester.tap(security);
            await tester.pumpAndSettle();
            expect(find.byType(GlobalSecurityV2), findsOneWidget,
                reason: 'Security destination: '
                    '${router.routeInformationProvider.value.uri}; '
                    'router error: ${router.routerDelegate.currentConfiguration.error}');
            final securityLocation = GoRouterState.of(
              tester.element(find.byType(GlobalSecurityV2)),
            ).uri;
            expect(securityLocation.path, '/app/account/security');
            router.go(securityLocation.toString());
            await tester.pumpAndSettle();
            await tester.tap(find.byKey(const Key('global-security-back')));
            await tester.pumpAndSettle();
            expect(find.byType(BuyV2Screen, skipOffstage: false), findsNothing);
            expect(tester.takeException(), isNull);
          }
          for (final delay in [0, 1, 16, 50, 150, 650]) {
            for (var repeat = 0; repeat < 5; repeat++) {
              final nativeConnectionClosed = repeat == 3;
              await reveal(tester, find.byKey(const Key('work-quick-buy')));
              await reveal(tester, find.byKey(const Key('work-quick-buy')));
              await tester.tap(find.byKey(const Key('work-quick-buy')));
              await tester.pump(const Duration(milliseconds: 700));
              await tester.pumpAndSettle();
              expect(
                find.byKey(const Key('work-store-procurement-screen')),
                findsOneWidget,
              );
              final buy = tester
                  .widget<BuyV2Screen>(find.byType(BuyV2Screen))
                  .session;
              if (retainedProductId == null) {
                final product = buy.visibleProducts.first;
                retainedProductId = product.id;
                retainedQuantity = buy.quantityFor(product.id);
                // This real-app review harness has no supplier purchase grant.
                // Positive authorised Cart retention is covered by STOREBACK03.
                expect(buy.addProduct(product.id), isFalse);
                expect(buy.quantityFor(product.id), retainedQuantity);
                await tester.pumpAndSettle();
              }
              expect(buy.quantityFor(retainedProductId), retainedQuantity);
              await tester.tap(find.byKey(const ValueKey('buy-search-control')));
              await tester.pumpAndSettle();
              final search = find.byKey(const ValueKey('buy-search-field'));
              await tester.tap(search);
              await tester.enterText(search, 'zzqav12');
              tester.view.viewInsets = FakeViewPadding(
                bottom: oppoMetrics ? 656 : 220,
              );
              await tester.pumpAndSettle();
              tester.testTextInput.hide();
              if (nativeConnectionClosed) {
                tester.testTextInput.closeConnection();
              }
              tester.view.viewInsets = const FakeViewPadding();
              await tester.pump(Duration(milliseconds: delay));
              await tester.tap(
                find.byKey(const ValueKey('buy-search-clear')),
              );
              await tester.pump(Duration(milliseconds: delay));
              final searchFocus = tester.widget<EditableText>(
                find.descendant(of: search, matching: find.byType(EditableText)),
              ).focusNode;
              if (!nativeConnectionClosed) {
                expect(searchFocus.hasFocus, isTrue);
              }
              // Shared public search closes before sale-type tabs are exposed.
              await tester.binding.handlePopRoute();
              await tester.pump();
              expect(
                searchFocus.hasFocus,
                isFalse,
                reason:
                    'Public search Back releases focus before leaving Restock.',
              );
              await tester.pumpAndSettle();
              expect(find.byKey(const Key('work-store-procurement-screen')), findsOneWidget);
              await tester.tap(find.text('Bulk'));
              await tester.pump(Duration(milliseconds: delay));
              expect(tester.takeException(), isNull,
                  reason: 'Bulk $delay/$repeat');
              // Preserve delayed native writes and completed-write exits.
              delayBookmarkWrites = repeat != 4;
              await tester.binding.handlePopRoute();
              await tester.pump();
              for (var frame = 0; frame < 20; frame++) {
                await tester.pump(const Duration(milliseconds: 16));
              }
              await tester.pumpAndSettle();
              delayBookmarkWrites = false;
              expect(
                tester.takeException(),
                isNull,
                reason: 'Back $delay/$repeat',
              );
              expect(buy.quantityFor(retainedProductId), retainedQuantity);
              expect(
                find.byKey(const Key('work-store-procurement-screen')),
                findsNothing,
              );
              expect(
                find.byKey(const Key('work-dashboard-catalogue-screen')),
                findsOneWidget,
              );
            }
          }
        }
      } finally {
        semantics.dispose();
      }
    });
  }

  if (storeReviewRuntime) {
    testWidgets('STOREBACK04 dashboard workload count overlap and exit', (
      tester,
    ) async {
      final previousPreferences = SharedPreferencesAsyncPlatform.instance;
      SharedPreferencesAsyncPlatform.instance =
          InMemorySharedPreferencesAsync.empty();
      addTearDown(
        () => SharedPreferencesAsyncPlatform.instance = previousPreferences,
      );
      final work = liveStore();
      expect(work.loadStoreReviewSeed(1000), isTrue);
      final controller = WorkProcurementController(
        currentAccountId: () => 'fixture-purchaser',
        currentStoreId: () => work.activeWorkspace?.id,
        storeApproved: () => work.activeWorkspace?.verified == true,
        bookmarks: _StorePurchaseBookmarks(),
        stateStoreFactory: (scope) => _StorePurchaseState(scope),
      );
      await mount(
        tester,
        route: '/app/work/workspace/dashboard',
        work: work,
        procurementFactory: () => controller,
      );
      // The approved Analytics board replaces the four legacy workload rows.
      // Exercise its real count projection and expansion during rapid updates,
      // not detached copies of an unreachable legacy AnimatedSwitcher.
      final openOrders = work.visibleWorkspaceOrders
          .where((order) => !order.isClosed)
          .take(250)
          .toList();
      expect(openOrders, hasLength(250));
      final report = find.byKey(const Key('store-analytics-orders'));
      await reveal(tester, report);
      for (final (count, elapsed) in [
        (250, 220),
        (249, 100),
        (248, 16),
        (249, 16),
        (247, 16),
      ]) {
        // Explicit host fixture only; no device/runtime storage injection.
        work.workspaceOrders
          ..clear()
          ..addAll(openOrders.take(count));
        work.notifyListeners();
        await tester.pump(Duration(milliseconds: elapsed));
        final value = find.byKey(
          const Key('analytics-preview-value-orders-0'),
        );
        expect(value, findsOneWidget);
        expect(tester.widget<Text>(value).data, '$count');
        await reveal(tester, report);
        expect(report.hitTestable(), findsOneWidget);
        await tester.tap(report);
        await tester.pump(Duration(milliseconds: elapsed));
        expect(tester.takeException(), isNull,
            reason: 'Live Analytics count/expansion $count');
      }
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pumpAndSettle();
      expect(tester.takeException(), isNull);
    });
  }
  for (final delayed in [false, true]) {
    testWidgets(
      'STOREBACK03 return failure retry and repeated Back delayed=$delayed',
      (tester) async {
        final previousPreferences = SharedPreferencesAsyncPlatform.instance;
        SharedPreferencesAsyncPlatform.instance =
            InMemorySharedPreferencesAsync.empty();
        addTearDown(
          () => SharedPreferencesAsyncPlatform.instance = previousPreferences,
        );
        final work = liveStore();
        final bookmarks = _StorePurchaseBookmarks();
        final states = <String, _StorePurchaseState>{};
        final controller = WorkProcurementController(
          currentAccountId: () => 'fixture-purchaser',
          currentStoreId: () => work.activeWorkspace?.id,
          storeApproved: () => work.activeWorkspace?.verified == true,
          bookmarks: bookmarks,
          stateStoreFactory: (scope) =>
              states.putIfAbsent(scope, () => _StorePurchaseState(scope)),
          sessionFactory: (identity, state) {
            final core = BuySession();
            addTearDown(core.dispose);
            return BuyV2Session(
              core: core,
              procurementIdentity: identity,
              customerStateStore: state,
              commerceAdapter: _StorePurchaseCommerce(identity.value!),
              productFactsAdapter: _StorePurchaseOrderReadyFacts(),
              reviewDataEnabled: false,
            );
          },
        );
        await mount(
          tester,
          route: '/app/work/workspace/dashboard',
          work: work,
          procurementFactory: () => controller,
        );
        await reveal(tester, find.byKey(const Key('work-quick-buy')));
        await reveal(tester, find.byKey(const Key('work-quick-buy')));
        await tester.tap(find.byKey(const Key('work-quick-buy')));
        await tester.pumpAndSettle();
        final buy = controller.session!;
        final product = buy.visibleProducts.first;
        expect(buy.addProduct(product.id), isTrue);
        await tester.pumpAndSettle();
        final quantity = buy.quantityFor(product.id);
        if (delayed) {
          bookmarks.pendingInactive = Completer<bool>();
          await tester.binding.handlePopRoute();
          await tester.pump();
          await tester.binding.handlePopRoute();
          await tester.pump();
          bookmarks.pendingInactive!.complete(true);
          await tester.pumpAndSettle();
          expect(
            bookmarks.inactiveWrites,
            1,
            reason: 'Repeated Back must share one pending return.',
          );
        } else {
          bookmarks.failInactive = true;
          await tester.binding.handlePopRoute();
          await tester.pumpAndSettle();
          expect(
            work.errorMessage,
            'Your purchase return could not be saved. Please try again.',
          );
          expect(work.noticeMessage, isNull);
          expect(bookmarks.value!.active, isTrue);
          expect(
            find.byKey(const Key('work-store-procurement-screen')),
            findsOneWidget,
          );
          expect(buy.quantityFor(product.id), quantity);
          bookmarks.failInactive = false;
          await tester.binding.handlePopRoute();
          await tester.pumpAndSettle();
        }
        expect(work.errorMessage, isNull);
        expect(work.noticeMessage, isNull);
        expect(bookmarks.value!.active, isFalse);
        expect(buy.quantityFor(product.id), quantity);
        expect(
          find.byKey(const Key('work-dashboard-catalogue-screen')),
          findsOneWidget,
        );
        expect(tester.takeException(), isNull);
      },
    );
  }

