    testWidgets(
      'counter isolation refused save retains bill and recovers $scale',
      (tester) async {
        final work = liveStore();
        await mount(
          tester,
          route: '/app/work/workspace/dashboard',
          work: work,
          viewport: const Size(412, 915),
          textScale: scale,
        );
        await openCounterSaleFromSales(tester);
        await enterSaleCustomer(tester, '9829012345');
        await addCounterProduct(
          tester,
          find.byKey(const Key('work-order-add-oil-fortune-1l')),
        );
        await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('work-order-review')));
        await tester.pumpAndSettle();
        // A late selection update must not let the open form replace that order.
        final incoming = WorkspaceOrderRecord(
          id: 'incoming-protected',
          customer: 'Asha',
          items: 'Ordered oil',
          quantities: {'oil-fortune-1l': 2},
          amount: 500,
          source: 'App',
          fulfilment: 'Mool delivery',
          payment: 'Paid online',
          address: 'Market road',
          stage: 'Confirmed',
          needsDelivery: true,
          createdAt: DateTime(2026, 9, 10),
        );
        work.workspaceOrders.add(incoming);
        work.currentWorkspaceOrderId = incoming.id;
        final incomingBefore = jsonEncode(incoming.toLedgerJson());
        await tester.tap(find.byKey(const Key('work-order-save')));
        await tester.pumpAndSettle();
        expect(
          find.text('Bill updated. Review the items and total.'),
          findsOneWidget,
        );
        await tester.tap(find.byKey(const Key('work-order-save')));
        await tester.pumpAndSettle();
        expect(work.currentWorkspaceOrder, same(incoming));
        expect(work.workspaceInvoices, isEmpty);
        expect(work.workspaceOrderCustomer, '9829012345');
        expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
        expect(
          find.byKey(const Key('work-bill-review-update')),
          findsOneWidget,
        );
        expect(find.byKey(const Key('work-invoice-title')), findsNothing);
        expect(
          find.text(
            'Use this order’s actions. Start a new bill for a counter sale.',
          ),
          findsOneWidget,
        );
        await captureStoreView(tester, 'counter-refused-save-$scale');
        expect(tester.takeException(), isNull);
        // Recovery uses real controls; do not fix selection directly in tests.
        await tester.tap(find.byKey(const Key('work-back')));
        await tester.pumpAndSettle();
        // Full-screen Back first returns from Review to Items. Only the next
        // Back attempts to leave the protected Counter draft.
        expect(
          find.byKey(const Key('work-order-review-summary')),
          findsNothing,
        );
        expect(work.currentWorkspaceOrder, same(incoming));
        expect(work.workspaceOrderCustomer, '9829012345');
        expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
        expect(work.workspaceInvoices, isEmpty);
        await tester.tap(find.byKey(const Key('work-back')));
        await tester.pumpAndSettle();
        if (storeReviewRuntime) {
          // Sales retains its full-screen composer: Review -> Items -> Home.
          // Returning to Sales home is not leaving the Store or discarding it.
          expect(find.byKey(const Key('work-sales-home')), findsOneWidget);
          expect(work.currentWorkspaceOrder, same(incoming));
          expect(work.workspaceOrderCustomer, '9829012345');
          expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
          expect(work.workspaceInvoices, isEmpty);
          // Now attempt the actual Store-leave boundary. A selected incoming
          // order must not be overwritten by saving the unfinished Counter bill.
          expect(await work.saveWorkspaceCounterDraft(), isFalse);
          final leaveSales = find.byKey(const Key('work-store-home'));
          expect(leaveSales.hitTestable(), findsOneWidget);
          await tester.tap(leaveSales);
          await tester.pumpAndSettle();
          expect(
            find.byKey(const Key('work-order-discard-dialog')),
            findsOneWidget,
          );
          await tester.tap(find.text('Keep editing'));
          await tester.pumpAndSettle();
          expect(
            find.byKey(const Key('work-order-discard-dialog')),
            findsNothing,
          );
          expect(work.currentWorkspaceOrder, same(incoming));
          expect(work.workspaceOrderCustomer, '9829012345');
          expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
          expect(work.workspaceInvoices, isEmpty);
          expect(
            find.byKey(const Key('work-sales-home')),
            findsOneWidget,
          );
          expect(jsonEncode(incoming.toLedgerJson()), incomingBefore);
          await openSalesTask(tester, 'counter');
          await tester.pumpAndSettle();
          expect(find.byKey(const Key('work-order-review')), findsOneWidget);
          expect(work.workspaceOrderCustomer, '9829012345');
          expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
          expect(work.currentWorkspaceOrder, same(incoming));
          expect(work.workspaceInvoices, isEmpty);
          expect(tester.takeException(), isNull);
          return;
        }
        expect(
          find.byKey(const Key('work-order-discard-dialog')),
          findsNothing,
        );
        expect(work.workspaceInvoices, isEmpty);
        await openCounterSaleFromSales(tester);
        // Back/reopen resumes transient fields; it is not a new-bill command.
        expect(work.currentWorkspaceOrder, same(incoming));
        expect(work.workspaceOrderCustomer, '9829012345');
        expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
        expect(work.workspaceInvoices, isEmpty);
        await returnToSalesHome(tester);
        // This unscoped host session has no durable journal: leaving retains
        // its fields without a discard prompt. Fresh Counter entry after the
        // composer unmounts is the explicit new-bill boundary.
        final leave = find.byKey(const Key('work-store-home'));
        await tester.tap(leave);
        await tester.pumpAndSettle();
        expect(find.byKey(const Key('work-order-discard-dialog')), findsNothing);
        expect(work.currentWorkspaceOrder, same(incoming));
        expect(work.workspaceOrderCustomer, '9829012345');
        expect(work.workspaceOrderQuantities['oil-fortune-1l'], 1);
        expect(work.workspaceInvoices, isEmpty);
        expect(jsonEncode(incoming.toLedgerJson()), incomingBefore);
        await openCounterSaleFromSales(tester);
        expect(work.currentWorkspaceOrderId, isNull);
        expect(work.workspaceOrderCustomer, isEmpty);
        expect(work.workspaceOrderQuantities, isEmpty);
        expect(work.workspaceInvoices, isEmpty);
        expect(jsonEncode(incoming.toLedgerJson()), incomingBefore);
        await enterSaleCustomer(tester, '9829012345');
        await addCounterProduct(
          tester,
          find.byKey(const Key('work-order-add-oil-fortune-1l')),
        );
        await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('work-order-review')));
        await tester.pumpAndSettle();
        await tester.tap(find.byKey(const Key('work-order-save')));
        await tester.pumpAndSettle();
        expect(work.workspaceInvoices, hasLength(1));
        expect(work.workspaceInvoices.single.orderId, isNot(incoming.id));
        expect(jsonEncode(incoming.toLedgerJson()), incomingBefore);
        expect(
          work.workspaceOrders.firstWhere((o) => o.id == incoming.id),
          same(incoming),
        );
        expect(work.workspaceOrderCustomer, '9829012345');
        expect(find.byKey(const Key('work-invoice-title')), findsOneWidget);
        final next = find.byKey(const Key('work-sale-next'));
        await reveal(tester, next);
        await tester.tap(next);
        await tester.pumpAndSettle();
        expect(work.workspaceOrderCustomer, isEmpty);
        expect(work.workspaceOrderQuantities, isEmpty);
        expect(work.workspaceInvoices, hasLength(1));
        expect(tester.takeException(), isNull);
      },
    );
  }

