        if (method == 'Cash' && scale == 1.0) {
          final drafts = work.ledgerFormDraftStore! as _LedgerFormFixtureStore;
          final gate = Completer<void>();
          final entered = Completer<void>();
          drafts.nextWrite = gate;
          drafts.writeEntered = entered;
          final invoiceBefore = jsonEncode(invoice.toLedgerJson());
          final dueBefore = payment().dueMinor;
          final quantitiesBefore = Map<String, int>.of(
            work.workspaceOrderQuantities,
          );
          try {
            await tester.enterText(
              find.byKey(const Key('collection-amount')),
              '1.00',
            );
            await tester.pump(const Duration(seconds: 1));
            expect(entered.isCompleted, isTrue);
            await tester.tap(find.byKey(const Key('work-back')));
            await tester.pump();
            expect(find.byKey(const Key('collection-amount')), findsOneWidget);
            expect(work.workspaceOrderQuantities, quantitiesBefore);
            expect(payment().dueMinor, dueBefore);
            expect(jsonEncode(invoice.toLedgerJson()), invoiceBefore);
          } finally {
            if (!gate.isCompleted) gate.complete();
          }
          await tester.pumpAndSettle();
          // This held write exercises payment -> invoice, not invoice exit.
          expect(find.byKey(const Key('collection-amount')), findsNothing);
          expect(find.byKey(const Key('work-invoice-title')), findsOneWidget);
          expect(work.workspaceOrderQuantities, quantitiesBefore);
          expect(payment().dueMinor, dueBefore);
          expect(jsonEncode(invoice.toLedgerJson()), invoiceBefore);
          await press(action);
        }
        final amount = find.byKey(const Key('collection-amount'));
        final reference = find.byKey(const Key('collection-reference'));
        final confirm = find.byKey(const Key('collection-confirm'));
        void expectVisible(Finder field) {
          final viewport = tester.getRect(
            find
                .ancestor(
                  of: field,
                  matching: find.byType(SingleChildScrollView),
                )
                .first,
          );
          for (final target in [field, confirm]) {
            final rect = tester.getRect(target);
            expect(
              rect.top,
              greaterThanOrEqualTo(viewport.top),
              reason: '$target top',
            );
            expect(
              rect.bottom,
              lessThanOrEqualTo(viewport.bottom),
              reason: '$target bottom',
            );
            expect(target.hitTestable(), findsOneWidget);
          }
        }

        // No reveal/ensureVisible after opening: production owns IME fitment.
        await tester.tap(amount);
        for (final inset in [180.0, 255.0, 300.0]) {
          tester.view.viewInsets = FakeViewPadding(bottom: inset);
          await tester.pumpAndSettle();
          expectVisible(amount);
        }
        await tester.enterText(amount, '0');
        await tester.pumpAndSettle();
        await tester.tap(confirm);
        await tester.pumpAndSettle();
        expect(find.text('Enter an amount greater than zero.'), findsOneWidget);
        expectVisible(amount);
        expect(payment().paidMinor, 0);
        await tester.enterText(amount, '100');
        await tester.pumpAndSettle();
        if (method == 'Bank Transfer') {
          await tester.tap(confirm);
          await tester.pumpAndSettle();
          expect(
            find.text('Enter the bank transaction reference.'),
            findsOneWidget,
          );
          expectVisible(reference);
          expect(payment().paidMinor, 0);
          await tester.enterText(reference, 'QA-IME-015');
          await tester.pumpAndSettle();
          expectVisible(reference);
        }
        await awaitCataloguePhoto(
          tester,
          () => tester
              .widgetList<RawImage>(find.byType(RawImage))
              .any((image) => image.image != null),
        );
        await captureStoreView(tester, 'receipt-ime-$method-$scale');
        await tester.tap(confirm);
        await tester.pumpAndSettle();
        expect(payment().paidMinor, 10000);
        expect(payment().dueMinor, invoice.payableMinor - 10000);
        tester.view.viewInsets = FakeViewPadding.zero;
        FocusManager.instance.primaryFocus?.unfocus();
        await tester.pumpAndSettle();
        await press(action);
        expect(
          tester.widget<TextField>(amount).controller!.text,
          '${payment().dueMinor ~/ 100}',
        );
        expect(work.workspaceInvoices.single, same(invoice));
        expect(tester.takeException(), isNull);
        restorePhotos();
      });
