        route: '/app/work/workspace/dashboard',
        work: work,
        viewport: const Size(360, 806),
      );
      Future<void> press(String key) async {
        final target = find.byKey(Key(key));
        await reveal(tester, target);
        await tester.tap(target);
        await tester.pumpAndSettle();
      }

      await openCounterSaleFromSales(tester);
      await enterSaleCustomer(tester, '9000091936');
      await addCounterProduct(
        tester,
        find.byKey(const Key('work-order-add-oil-fortune-1l')),
      );
      await press('work-order-review');
      await press('work-sale-payment-cash');
      await press('work-order-save');
      final invoice = work.workspaceInvoices.single;
      final invoiceBefore = jsonEncode(invoice.toLedgerJson());
      final financeBefore = work.workspaceFinance!;
      String? financeFacts(WorkspaceFinanceSnapshot? finance) => finance == null
          ? null
          : jsonEncode([
              finance.accountScope,
              finance.workspaceId,
              finance.revision,
              finance.asOf.toUtc().toIso8601String(),
              finance.salesTodayMinor,
              finance.duesMinor,
              finance.availableMinor,
              finance.heldMinor,
              finance.requestedMinor,
              finance.paidOutMinor,
              finance.feesMinor,
              finance.deliveryAdjustmentsMinor,
              finance.refundsMinor,
              finance.taxWithheldMinor,
              finance.historyComplete,
              for (final p in finance.payments)
                [
                  p.orderId,
                  p.customerId,
                  p.customerName,
                  p.revision,
                  p.updatedAt.toUtc().toIso8601String(),
                  p.amountMinor,
                  p.paidMinor,
                  p.dueMinor,
                  p.refundedMinor,
                  p.state.name,
                  p.channel.name,
                  p.invoiceId,
                  p.transactionId,
                ],
            ]);
      final oldFinanceFacts = financeFacts(financeBefore);
      final paymentBefore = financeBefore.payments.singleWhere(
        (p) => p.invoiceId == invoice.id,
      );
      final draftKey = work.ledgerFormKey(paymentBefore, 'collection')!;
      final otherOrder = work.workspaceOrders.firstWhere(
        (p) => p.id != invoice.orderId,
      );
      expect(
        work.workspaceOrders.where((p) => p.id == otherOrder.id),
        hasLength(1),
      );
      final dueBefore = financeBefore.payments
          .singleWhere((p) => p.invoiceId == invoice.id)
          .dueMinor;
      String stockFacts() => jsonEncode(
        work.workspaceCatalogueItems.map((p) => [p.id, p.stock]).toList(),
      );
      final stockBefore = stockFacts();
      await press('work-invoice-record-payment');
      final drafts = work.ledgerFormDraftStore! as _LedgerFormFixtureStore;
      final gate = Completer<void>();
      final entered = Completer<void>();
      drafts.nextWrite = gate;
      drafts.writeEntered = entered;
      Object replacementFacts() => (
        work.counterDraftIdentity,
        work.currentWorkspaceOrderId,
        work.workspaceOrderCustomer,
        jsonEncode(work.workspaceOrderQuantities),
        financeFacts(work.workspaceFinance),
        jsonEncode(work.currentWorkspaceOrder?.toLedgerJson()),
        jsonEncode(
          work.workspaceInvoices.map((p) => p.toLedgerJson()).toList(),
        ),
        stockFacts(),
        find.byKey(const Key('collection-amount')).evaluate().length,
        find.byKey(const Key('work-invoice-title')).evaluate().length,
        find.byKey(const Key('work-sales-home')).evaluate().length,
        find
            .byKey(const Key('work-sales-task-heading'))
            .evaluate()
            .map((e) => (e.widget as Text).data)
            .join('|'),
      );
      Object? replacement;
      String? replacementOrder;
      try {
        await tester.enterText(
          find.byKey(const Key('collection-amount')),
          '1.00',
        );
        await tester.pump(const Duration(seconds: 1));
        expect(entered.isCompleted, isTrue);
        await tester.tap(find.byKey(const Key('work-back')));
        await tester.pump();
        expect(find.byKey(const Key('collection-amount')), findsOneWidget);
        if (interruption == 'failure') {
          drafts.failWrite = true;
        } else {
          // Deliberate host projection interleaving, not a user navigation claim.
          if (interruption == 'account') {
            contact.accountScope = 'host-other-account';
            work.notifyListeners();
          } else {
            replacementOrder = otherOrder.id;
            expect(work.selectWorkspaceOrder(replacementOrder), isTrue);
          }
          await tester.pump();
          await tester.pump(const Duration(milliseconds: 100));
          replacement = replacementFacts();
        }
      } finally {
        if (!gate.isCompleted) gate.complete();
      }
      await tester.pumpAndSettle();
      if (interruption == 'failure') {
        final amount = find.byKey(const Key('collection-amount'));
        expect(amount, findsOneWidget);
        expect(tester.widget<TextField>(amount).controller!.text, '1.00');
        expect(tester.widget<TextField>(amount).enabled, isTrue);
        expect(
          find.text('Input is not saved yet. Retry saving before leaving.'),
          findsOneWidget,
        );
        drafts.failWrite = false;
        await tester.enterText(amount, '1.01');
        await tester.pumpAndSettle();
        expect(drafts.drafts[draftKey]?.key, draftKey);
        expect(drafts.drafts[draftKey]?.fields['amount'], '1.01');
        await press('work-back');
        expect(find.byKey(const Key('collection-amount')), findsNothing);
        expect(find.byKey(const Key('work-invoice-title')), findsOneWidget);
      } else {
        expect(replacementFacts(), replacement);
        if (replacementOrder != null) {
          expect(work.currentWorkspaceOrderId, replacementOrder);
        }
      }
      expect(
        work.workspaceInvoices,
        interruption == 'account' ? isEmpty : hasLength(1),
      );
      expect(jsonEncode(invoice.toLedgerJson()), invoiceBefore);
      expect(
        financeBefore.payments
            .singleWhere((p) => p.invoiceId == invoice.id)
            .dueMinor,
        dueBefore,
      );
      expect(financeFacts(financeBefore), oldFinanceFacts);
      if (interruption == 'account') {
        expect(work.workspaceFinance, isNull);
        expect(work.activeWorkspace, isNull);
        expect(work.workspaceCatalogueItems, isEmpty);
        expect(find.byKey(const Key('collection-confirm')), findsNothing);
      } else {
        expect(stockFacts(), stockBefore);
      }
      expect(tester.takeException(), isNull);
      restorePhotos();
    });
  }

