// Test-only guard double; real secure-store serialization has separate host tests.
class _OpeningPostingFixtureStore extends _PurchaseEntryFixtureStore
    implements
        WorkPurchaseEntryRevisionGuard,
        WorkPurchaseBillGoodsReviewGuard,
        WorkPurchaseBillGoodsReviewAbandonment,
        WorkPurchaseGoodsReceiptReviewGuard {
  final reviewOperations = <String>[];
  @override
  Future<bool> saveReviewedGoodsReceipt(
    WorkspacePurchaseEntryBook book, {
    required int expectedRevision,
    required Future<bool> Function(Future<bool> Function() persist)
    withVerifiedStock,
  }) async {
    if (value?.revision != expectedRevision) return false;
    return withVerifiedStock(() async {
      if (value?.revision != expectedRevision) return false;
      await save(book, expectedRevision: expectedRevision);
      return true;
    });
  }

  @override
  Future<WorkspacePurchaseEntryBook?> abandonReviewedBillGoods(
    String account,
    String store, {
    required bool qa,
    required int expectedRevision,
    required WorkspaceBillGoodsReviewCancellation cancellation,
    required Future<bool> Function(WorkspaceSupplierBillGoodsReview review)
    verifyUncommitted,
  }) async {
    final old = value;
    if (old == null ||
        old.account != account ||
        old.store != store ||
        old.qa != qa ||
        old.revision != expectedRevision) {
      return null;
    }
    final review = old.billGoodsReviews
        .where((r) => r.allocation.operationId == cancellation.operationId)
        .singleOrNull;
    if (review == null ||
        !await verifyUncommitted(review) ||
        value?.revision != expectedRevision) {
      return null;
    }
    final next = WorkspacePurchaseEntryBook.fromJson({
      ...old.toJson(),
      'revision': cancellation.revision,
      'billGoodsCancellations': [
        ...old.billGoodsCancellations.map((c) => c.toJson()),
        cancellation.toJson(),
      ],
    });
    await save(next, expectedRevision: expectedRevision);
    return next;
  }

  @override
  Future<bool> saveReviewedBillGoods(
    WorkspacePurchaseEntryBook book, {
    required int expectedRevision,
    required Future<bool> Function() verifyCurrent,
  }) async {
    reviewOperations.add(book.billGoodsReviews.last.allocation.operationId);
    if (value?.revision != expectedRevision ||
        !await verifyCurrent() ||
        value?.revision != expectedRevision) {
      return false;
    }
    await save(book, expectedRevision: expectedRevision);
    return true;
  }

  @override
  Future<bool> withReviewedBook(
    String account,
    String store, {
    required bool qa,
    required int expectedRevision,
    required Future<bool> Function(WorkspacePurchaseEntryBook book) action,
  }) async {
    final book = value;
    if (book == null ||
        book.account != account ||
        book.store != store ||
        book.qa != qa ||
        book.revision != expectedRevision) {
      return false;
    }
    return action(book);
  }
}

